window.BLOG_ARTICLE_CONTENT = window.BLOG_ARTICLE_CONTENT || {};
window.BLOG_ARTICLE_CONTENT["en/embodied-agent-papers"] = {"body": "\n<aside aria-label=\"Translation status\" class=\"translation-note\">\n<p>English translation of the <a data-local-language=\"zh\" href=\"#/post/embodied-agent-papers\" lang=\"zh-CN\">Chinese article</a> revised 2026-10-22. Translation updated 2026-10-22.</p>\n<p>Companion articles labeled <span class=\"language-label\">Chinese only</span> are available in Chinese. English editions will be added as they are completed.</p>\n</aside>\n<blockquote>\n<p>This collection accompanies <a data-local-language=\"en\" href=\"#/post/ai-agent-survey\">AI Agents: A Survey</a> and the architecture guide <a data-local-language=\"en\" href=\"#/post/embodied-agent-harness-survey\">Embodied Agents: Harness and Runtime Architecture</a>. It provides detailed readings of representative embodied-agent papers and recent advances.</p>\n</blockquote>\n<h1 id=\"具身智能体论文精读\">Embodied Agents: Paper Readings</h1>\n<p>This article focuses on a common problem: how robots organize perception, planning, execution, verification, and recovery into a closed loop that can operate sustainably. The eighteen papers examine runtimes, orchestration, evaluation, evolution mechanisms, action interfaces, training objectives, general AgentOS, inspection-system governance, navigation-session handovers, navigation-tool orchestration, visual-memory inspection, reasoning-budget allocation, unified embodied reasoning, a unified taxonomy of agentic robots, recursive harness optimization, evaluation of embodied capabilities, weight-harness co-evolution, and history-replay-driven evolution of exploration policies. The experiments cover simulation environments, text-interaction environments, interactive visual games, real robots, and professional software tasks. The SuperNav entry provides a brief introduction and links to the full reading in the extended VLN collection. Evo² and Dream-RSI are evaluated directly on software tasks, so this article treats them as mechanisms that may transfer to embodied-harness evolution rather than as evidence of robot performance.</p>\n<table>\n<thead>\n<tr>\n<th>Paper</th>\n<th>Main entry points</th>\n<th>representative verification</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><a href=\"#holoagent-0\">HoloAgent-0</a></td>\n<td>AgentOS, typed skills and hierarchical Spatial memory</td>\n<td>HM3D, ScanNet, real heterogeneous robots</td>\n</tr>\n<tr>\n<td><a href=\"#pigey\">Pigey</a></td>\n<td>inference time physical orchestration, TAMP/VLA dual backend and double verification</td>\n<td>LIBERO-PRO, DROID real robot</td>\n</tr>\n<tr>\n<td><a href=\"#thea\">Thea</a></td>\n<td>Scene graph context and evaluator exit code</td>\n<td>L1–L3 long-horizon real robot tasks, cross-embodiment deployment</td>\n</tr>\n<tr>\n<td><a href=\"#zetta\">Zetta</a></td>\n<td>High-frequency judge, recovery action library and offline self-evolution</td>\n<td>LIBERO-Pro, concurrent sampling infrastructure</td>\n</tr>\n<tr>\n<td><a href=\"#show-harness\">Show-Harness</a></td>\n<td>Semantic action unit and embodiment interpreter</td>\n<td>Franka, AgileX, simulation and real robot generalization</td>\n</tr>\n<tr>\n<td><a href=\"#space\">SPACE</a></td>\n<td>Skill-guided adaptive action chunking and reinforcement learning</td>\n<td>ALFWorld, ScienceWorld</td>\n</tr>\n<tr>\n<td><a href=\"#abot-agentos\">ABot-AgentOS</a></td>\n<td>Dual LLM, Agent Harness, and Lifelong Multimodal Memory</td>\n<td>EmbodiedWorldBench, memory benchmark</td>\n</tr>\n<tr>\n<td><a href=\"#abot-er\">ABot-ER</a></td>\n<td>Unified embodied reasoning and data-model co-evolution</td>\n<td>Twelve embodied-understanding and planning benchmarks; qualitative robot demonstrations</td>\n</tr>\n<tr>\n<td><a href=\"#harness-robotic-os\">Harness Robotic OS</a></td>\n<td>Patrol runtime, hierarchical memory and self-evolution governance</td>\n<td>Real community navigation and inspection; cognitive operation needs to be controlled and verified</td>\n</tr>\n<tr>\n<td><a href=\"#navharness\">NavHarness</a></td>\n<td>Cross-session search handovers, memory processing, recovery, and two-stage verification</td>\n<td>GOAT-Bench, IR2R-CE, and continuous deployment across 36 houses in simulation</td>\n</tr>\n<tr>\n<td><a href=\"#supernav\">SuperNav</a></td>\n<td>Readable navigation skills, visual-point tools, and task-context management</td>\n<td>Single-object, multi-object, and demand-driven navigation; HM3D; Unitree Go2 deployment</td>\n</tr>\n<tr>\n<td><a href=\"#vista\">VISTA</a></td>\n<td>Lossless visual memory, model-directed visual inspection, and cross-context notes</td>\n<td>ARC-AGI-3, GameWorld, AI GameStore, BabyVision</td>\n</tr>\n<tr>\n<td><a href=\"#race\">RACE</a></td>\n<td>Cross-turn reasoning covers, likelihood proxy signals, and adaptive-reasoning RL</td>\n<td>ScienceWorld, WebShop, AppWorld, DeepSearch</td>\n</tr>\n<tr>\n<td><a href=\"#agentic-robots\">Agentic Robots</a></td>\n<td>Four domains—Model, Data, Environment, and Harness—and 17 functional categories</td>\n<td>Survey synthesis; no new method evaluated in a unified experiment</td>\n</tr>\n<tr>\n<td><a href=\"#harness2\">Harness²</a></td>\n<td>Behavioral contrasts without answer keys, two-level recursion, and an improvement library</td>\n<td>General-agent method reference; WorkBuddy-Bench, JobBench, LAB</td>\n</tr>\n<tr>\n<td><a href=\"#gpt-6-astra-jrt\">GPT-6-Astra-JRT</a></td>\n<td>Frozen knowledge packages, interaction budgets, fast-slow collaboration, and continuous-world evaluation</td>\n<td>12 simulation benchmarks, 8 real-robot configurations, and a household prototype</td>\n</tr>\n<tr>\n<td><a href=\"#evo2\">Evo²</a></td>\n<td>Weight-harness co-evolution, a dual-role evolver, and cross-branch strategy reuse</td>\n<td>Polyglot, SWE-bench Verified, LiveCodeBench, and LoCoMo; no robot evaluation</td>\n</tr>\n<tr>\n<td><a href=\"#dream-rsi\">Dream-RSI</a></td>\n<td>Historical discovery-tree replay, offline exploration-policy improvement, and recursive deployment</td>\n<td>KernelBench, mathematical optimization, Lasso, Terminal-Bench 2.1; no robot experiments</td>\n</tr>\n</tbody>\n</table>\n<p>The filter bar below supports multiple tag combinations; when multiple tags are selected at the same time, the page will only retain papers that meet these tags.</p>\n<div class=\"paper-filter-bar\" id=\"paper-filter-bar\"></div>\n<h2 id=\"holoagent-0\">1. HoloAgent-0 (2026)</h2>\n<p>——Unified embodied agent closed-loop operating system: decoupling heterogeneous physical skills, using layered 3D multi-modal Spatial memory as the physical anchor</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2606.23565\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2606.23565</a> · <a href=\"https://github.com/HorizonRobotics/HoloAgent\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<hr/>\n<h3 id=\"精华\">Key takeaways</h3>\n<ul>\n<li><strong>closed-loop embodied runtime architecture</strong>: Proposes the Embodied AgentOS operating system for physical robots, which reconstructs task planning from a single open-loop text generation to a continuous closed-loop of “observation-retrieval-action-monitoring”, effectively filling the execution uncertainty of the physical world.</li>\n<li><strong>Standardized Typed Skills Abstract (Typed Skills)</strong>: Developed action specifications including structured parameters, preconditions and runtime heartbeat status flow, unified encapsulation of VLA grasping, whole body movement control and active navigation, shielding the underlying differences of heterogeneous embodiment controllers.</li>\n<li><strong>Hierarchical multi-modal Scene graph (HMSG)</strong>: Constructs a four-layer topology structure consisting of floor, room, view and object, cleverly introduces the “view layer” to act as a bridge between geometric coordinates and appearance reasoning, supporting efficient spatial retrieval that mixes speed and slowness.</li>\n<li><strong>Open Vocabulary 3D Dynamic Semantic Mapping</strong>: Fusion of multi-camera neural depth estimation and multi-scale SigLIP features, combined with 3D instance back-projection correlation algorithm, to achieve local lightweight incremental refresh when physical changes occur in the environment.</li>\n<li><strong>real robot heterogeneous full-stack deployment verification</strong>: Completed deployment on Unitree G1 humanoid, R1 humanoid and dual-arm mobile chassis, comprehensively refreshing industry indicators on ScanNet semantic mapping and HM3D/real robot long-horizon navigation benchmarks.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题\">1. Background and problem</h3>\n<p>Large language model agents in the digital world rely on structured codes or software interfaces, with deterministic input and output, transparent state transitions, and reversible trial and error costs; however, in the physical world, the robot’s action execution is continuous, irreversible, and highly dependent on the specific body configuration. Due to perceptual degradation, sensor noise, and dynamic changes, robots often go to the wrong room due to outdated environmental memory, or long-horizon tasks are interrupted and crash due to incomplete feedback from the controller. This system-level obstacle is called the “Embodiment Gap.” Current embodied intelligence research often separates VLA operation strategies, 3D spatial representation, whole-body motion control, and active navigation into single-point algorithm modules. There is a lack of a unified operating system runtime to schedule heterogeneous skills, maintain a persistent 3D space base, and drive fault recovery based on real-time heartbeat evidence.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点\">2. Methods and innovations</h3>\n<h4 id=\"-整体框架概述\">① Overview of the overall framework</h4>\n<p>HoloAgent-0 organizes long-term embodied tasks into a self-Closed-loop systems project. The overall architecture includes three core coupling layers and a monitoring and verification layer, and implements strongly typed communication through the ROS2 topic bus:</p>\n<ul>\n<li><strong>Embodied AgentOS runtime layer</strong>: receives human natural language intentions, combines spatiotemporal memory to compile instructions into a skill graph with dependencies (Skill Graph), and is responsible for resource scheduling, execution status monitoring and autonomous re-planning during the execution period.</li>\n<li><strong>Embodied Skill Layer</strong>: Abstracts the underlying heterogeneous algorithms and controllers into typed skills (Typed Skills) with a unified interface, covering voice interaction, open vocabulary perception, autonomous navigation (HoloNavi), double-arm operation (HoloBrain) and whole-body movement (HoloMotion).</li>\n<li><strong>Embodied Memory Layer</strong>: Maintains three-dimensional metric geometry, topological navigation relationships, open vocabulary 3D semantic voxel maps, and hierarchical multimodal Scene graphs (HMSG) composed of floors, rooms, perspectives, and objects, while recording the temporal trajectory of task progress.</li>\n<li><strong>Monitoring &amp; Verification Layer (Monitoring &amp; Verification Layer)</strong>: Real-time monitoring of the heartbeat, confidence and error modes of skill execution, providing multi-modal interactive feedback to users, and waking up AgentOS for dynamic re-planning when unrecoverable faults occur.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-framework-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HoloAgent-0 closed-loop end-to-end runtime architecture overview</a>\n<figcaption>HoloAgent-0 closed-loop End-to-end runtime architecture overview</figcaption>\n</div>\n<h4 id=\"-具身技能层与类型化动作抽象typed-skills\">② Embodied skill layer and Typed actions abstraction (Typed Skills)</h4>\n<p>In traditional large model tool calls, agents usually treat the underlying tools as black-box functions, but this can easily lead to deadlocks on physical robots. To this end, HoloAgent-0 proposes a structured skill abstract contract:</p>\n<ol>\n<li><strong>Command Schema</strong>: Each skill explicitly declares the name, strongly typed input parameters, preconditions (Preconditions) and expected physical post-state (Expected Effects). For example, operational skill <code class=\"language-plaintext highlighter-rouge\">pick(object=mug, support=table)</code> declares pre-geometric anchoring requirements for grasping objects and support planes.</li>\n<li><strong>Runtime Status Interface</strong>: The execution end no longer just returns a binary completion identifier, but continuously broadcasts structured tracking data including progress ratio, success status, fine-grained failure modes (such as object inaccessibility, grip slippage, collision risk, and posture singularity), algorithm confidence, execution delay, and whether the failure is recoverable (Recoverability) through the ROS2 status topic.</li>\n</ol>\n<h5 id=\"卡点降维-1数字软件工具调用-vs-具身类型化技能typed-skills\">Stuck Point Dimensionality Reduction 1: Digital Software Tool Calling vs. Embodied Typed Skills (Typed Skills)</h5>\n<table>\n<thead>\n<tr>\n<th>Compare dimensions</th>\n<th>Traditional digital agent tool calling (Software Tool Calling)</th>\n<th>HoloAgent-0 Embodied Typed Skill</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>calling property</strong></td>\n<td>Synchronous or short-term asynchronous API, with determined input and output and clear semantic boundaries</td>\n<td>The physical world is a continuous and time-consuming process that is susceptible to interference from dynamic noise, occlusion and sensor drift.</td>\n</tr>\n<tr>\n<td><strong>feedback granularity</strong></td>\n<td>Only the final execution result or standard error code is returned</td>\n<td>Continuously publish runtime heartbeat stream (including progress percentage, local confidence and collision risk)</td>\n</tr>\n<tr>\n<td><strong>failure mode</strong></td>\n<td>Single error code (such as HTTP 404/500), usually no physical side effects</td>\n<td>Subdivide recoverable and non-recoverable modes (such as robot arm joint limit, grip slip, target loss)</td>\n</tr>\n<tr>\n<td><strong>recovery mechanism</strong></td>\n<td>Simple fixed number of exception retries (Retry) or text error return</td>\n<td>Explicitly expose recoverability, driving AgentOS rotation perspective recheck, navigation fine-tuning or re-planning</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Specific execution flow example</strong>:\nThe robot received the instruction “Put the yellow towel on the table into the laundry basket.”</p>\n<ol>\n<li>AgentOS issues instructions <code class=\"language-plaintext highlighter-rouge\">pick(object=\"yellow towel\", support=\"desk\")</code> through the ROS2 topic;</li>\n<li>The HoloBrain operation backend takes over control and continues to return the status stream <code class=\"language-plaintext highlighter-rouge\">{progress: 40%, status: \"in_progress\", confidence: 0.88}</code> when the robotic arm moves to the pre-grasping pose;</li>\n<li>When the gripper is closed, the tactile and posture feedback detects an empty grip, and the status flow is immediately reported <code class=\"language-plaintext highlighter-rouge\">{progress: 75%, status: \"failed\", failure_mode: \"grasp_slip\", recoverability: \"recoverable\"}</code>;</li>\n<li>AgentOS captures that recoverability is true and does not mechanically repeat blind grasping. Instead, it automatically schedules the perception backend to perform viewpoint fine-tuning and mask re-evaluation, updates the 3D bounding box of the target object, and then reinitiates grasping closed-loop.</li>\n</ol>\n</blockquote>\n<p>For different body postures, HoloAgent-0 is connected to four specialized backends:</p>\n<ul>\n<li><strong>HoloNavi space navigation</strong>: responsible for target search and path cruising in a wide range of environments;</li>\n<li><strong>HoloBrain embodied operation</strong>: Based on the general VLA large model, it generates the end posture trajectory of both arms and end clamps, and can autonomously complete delicate operations such as grasping, placing, pouring water, and folding clothes;</li>\n<li><strong>HoloMotion full body motion</strong>: supports trajectory tracking mode (for human-computer interaction actions such as waving, bowing, shaking hands, dancing, etc.) and speed control mode (for omnidirectional walking, steering, emergency obstacle avoidance and recovery after falling);</li>\n<li><strong>Cross-Embodiment Coordination</strong>: Multiple heterogeneous robots divide labor through a shared 3D Spatial memory base and a unified step state flow. For example, a wheeled mobile chassis first inspects and builds maps and marks the target location, and the humanoid robot then accurately performs complex desktop operations.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-closed-loop-execution.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: A real closed-loop implementation case of HoloAgent-0 on a diversified robot platform (operation control, object finding, multi-machine collaboration, long-distance folding)</a>\n<figcaption>HoloAgent-0 A real closed-loop implementation case on a diversified robot platform (operation control, object finding, multi-machine collaboration, long-distance folding)</figcaption>\n</div>\n<h4 id=\"-空间记忆与开放词表-3d-语义建图\">③ Spatial memory and open vocabulary 3D semantic mapping</h4>\n<p>Spatial memory provides a unified metric three-dimensional physical base for robot perception and action:</p>\n<ul>\n<li><strong>Unified geometry base</strong>: Decoupled sensor hardware configuration, supporting not only metric mapping (such as FAST-LIVO) where lidar, IMU and cameras are tightly coupled, but also pure visual multi-camera GeoFlow-SLAM++ system. GeoFlow-SLAM++ uses a 3D basic model to directly predict dense depth from multi-view RGB images, and builds high-quality metric maps without a hardware depth camera through multi-camera two-stage optical flow matching, point and surface geometry optimization, and loop bag-of-word retrieval.</li>\n<li><strong>Open vocabulary semantic projection</strong>: The online mapping module seamlessly upgrades the universal semantics of the 2D basic model to the 3D point cloud and voxel grid.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-semantic-mapping.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HoloAgent-0 open vocabulary 3D semantic mapping and dynamic scene adaptation framework</a>\n<figcaption>HoloAgent-0 Open Vocabulary 3D Semantic Mapping and Dynamic Scene Adaptation Framework</figcaption>\n</div>\n<h5 id=\"卡点降维-2三尺度-siglip-语义特征融合与-3d-实例持续关联\">Stuck Point Dimensionality Reduction 2: Three-Scale SigLIP Semantic Feature Fusion and 3D Instance Continuous Association</h5>\n<p>When upgrading 2D features to 3D space, if only a single cropped area feature is extracted, the environmental context is easily lost; if full image features are extracted, the discrimination of small objects will be diluted. HoloAgent-0 designed a multi-scale feature weighted fusion formula for this purpose:</p>\n\n\\[d = \\sum_{i=0}^2 w_i \\odot d_i\\]\n\n<p>Here, $d_i \\in \\mathbb R^d$ and $w_i \\in \\mathbb R^d$ are feature fusion weights, and $\\odot$ represents the Hadamard product.</p>\n<blockquote>\n<p><strong>A small example of hand-calculated feature fusion and projection correlation</strong>:\nAssume that the feature dimension is simplified to 3 dimensions, and a water glass is detected in the current key frame:</p>\n<ol>\n<li>Extract SigLIP embedding vectors at three scales:\n      <ul>\n<li>Full image context feature $d_0 = [0.2, 0.8, 0.1]$ (records large scene information such as kitchen and workbench);</li>\n<li>SAM2 precise segmentation mask feature $d_1 = [0.9, 0.1, 0.3]$ (highlighting the material and shape of the water cup);</li>\n<li>Minimum external rectangular frame feature $d_2 = [0.7, 0.4, 0.2]$ (supplementary handle and tabletop contact edge details);</li>\n</ul>\n</li>\n<li>Assume that the corresponding feature balance weight vectors are $w_0 = [0.2, 0.2, 0.2]$, $w_1 = [0.5, 0.5, 0.5]$, and $w_2 = [0.3, 0.3, 0.3]$;</li>\n<li>The final object vector after element-by-element fusion is:\n$d = (0.2 \\times [0.2, 0.8, 0.1]) + (0.5 \\times [0.9, 0.1, 0.3]) + (0.3 \\times [0.7, 0.4, 0.2]) = [0.70, 0.33, 0.23]$. This vector combines macroscopic scene attribution with local appearance details.</li>\n<li><strong>cross-view 3D instance association</strong>: When a new frame is collected after the robot is displaced, the system back-projects the maintained 3D instance point cloud $V_{t-1}$ back to the current camera plane through the external parameter matrix to obtain the projection prediction mask $\\tilde m_j$. The system calculates the intersection ratio $\\operatorname{IoU}(m_k, \\tilde m_j)$ of $\\tilde m_j$ and the current new segmentation mask $m_k$. If the intersection ratio is greater than 0.5, it is considered to be the same object and the unique instance ID is reused; if there is no overlap, a new 3D independent instance is opened.</li>\n</ol>\n</blockquote>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-instance-association.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-time frame 3D instance back-projection matching and continuous ID tracking mechanism</a>\n<figcaption> Cross-time frame 3D instance back-projection matching and continuous ID tracking mechanism</figcaption>\n</div>\n<h4 id=\"-分层多模态场景图hmsg与快慢混合检索机制\">④ Hierarchical multi-modal Scene graph (HMSG) and fast and slow hybrid retrieval mechanism</h4>\n<p>In order to take into account both spatial range and fine-grained perception, HMSG vertically decouples environmental information into a four-layer topology:</p>\n<ol>\n<li><strong>Floor</strong>: records the vertical height range and the overall semantics of the floor, and delineates the vertical range in coarse granularity;</li>\n<li><strong>Room layer (Room)</strong>: Contains 2D polygon geometric boundaries, point clouds and room type CLIP vectors to define the functional space;</li>\n<li><strong>perspective layer (View)</strong>: <strong>, the core innovation layer of</strong>HMSG. Record the 6-DoF rigid body pose, RGB-D image frame and local panoramic descriptor at the historical sampling location of the robot;</li>\n<li><strong>Object layer (Object)</strong>: Maintain 3D Oriented BBox, point cloud clusters and fused instance SigLIP features.</li>\n</ol>\n<pre><code class=\"language-mermaid\">graph TD\n    subgraph S1[\"1. Language intent decomposition\"]\n        A[\"Enter natural language commands&lt;br/&gt;'found1Pills on bedside table in upstairs bedroom'\"] --&gt; B[\"LLM Hierarchical semantic parsing&lt;br/&gt;Extract: Floor/room/target object\"]\n    end\n\n    subgraph S2[\"2. HMSG Quick initial screening (Fast Matching)\"]\n        B --&gt; C[\"Floor match: Filter to Floor-1\"]\n        C --&gt; D[\"Room match: Lock Bedroom\"]\n        D --&gt; E[\"CLIP Characteristic coarse screening&lt;br/&gt;primaries Top-K candidate perspective View\"]\n    end\n\n    subgraph S3[\"3. Multimodal slow verification (Slow Reasoning)\"]\n        E --&gt; F[\"VLM Review candidate perspective images&lt;br/&gt;'Whether there are tablets in the current field of view?'\"]\n        F -- \"confirm existence\" --&gt; G[\"Compute objects 3D Space center coordinates&lt;br/&gt;Dispatch navigation to the best operating position\"]\n        F -- \"not detected / Obstructed viewing angle\" --&gt; H[\"Rotate the body in place to capture a partial panorama&lt;br/&gt;Perform secondary word opening detection and retry\"]\n    end\n\n    subgraph S4[\"4. Active exploration of frontiers (Frontier Exploration)\"]\n        H -- \"Second verification still fails\" --&gt; I[\"Determine memory failure or no mapping&lt;br/&gt;Compute unexplored boundaries Frontier\"]\n        I --&gt; J[\"Comprehensive information gain and popularity navigation exploration&lt;br/&gt;Dynamic updates while walking HMSG Scene graph\"]\n    end\n</code></pre>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-hmsg-structure.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Hierarchical multimodal Scene graph (HMSG) four-layer structure (floor-room-view-object) and hierarchy and topological edge association</a>\n<figcaption> Hierarchical multimodal Scene graph (HMSG) four-layer structure (floor-room-view-object) and level and topological edge association</figcaption>\n</div>\n<p>The traditional Scene graph points directly across the room to discrete objects, resulting in the robot’s lack of perception of the real observation angle and occlusion conditions. Blindly calling the time-consuming multi-modal model (VLM) when facing a large space will cause a computing power collapse. The “View” in HMSG naturally retains the visual links (Visibility Links) between the observer’s perspective and objects, allowing the system to quickly screen out a very small number of relevant perspectives on metric geometry, and then call VLM specifically for high-quality visual identification.</p>\n<h4 id=\"-holonavi-目标导航流水线\">⑤ HoloNavi target navigation pipeline</h4>\n<p>Based on HMSG, the HoloNavi navigation system connects tasks into three interlocking execution loops:</p>\n<ol>\n<li><strong>Hierarchical Object Navigation</strong>: Use semantic analysis to match floor, room and object candidates, and use hierarchical CLIP similarity to quickly prune the irrelevant search space;</li>\n<li><strong>Online Verification Loop</strong>: When the robot reaches the candidate viewpoint, the real-time camera image is submitted to the open word detector and VLM for double verification. If the initial determination fails, the robot automatically rotates in place at multiple angles to collect the surrounding perspective for a second recheck, confirms the true coordinates of the target and then navigates to a safe operating distance;</li>\n<li><strong>Frontier Exploration Loop</strong>: If the initial search of HMSG fails or the online verification fails again, the system immediately switches to Frontier Exploration mode. Comprehensive scoring is performed based on the information gain expectation, task semantic relevance, traversability and dynamic constraints of the candidate frontier points, guiding the robot to explore unknown areas and continue to perform incremental mapping and target sniffing while traveling.</li>\n</ol>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-holonavi-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The whole process of HoloNavi object navigation: hierarchical semantic matching, online multi-view verification and cutting-edge incremental exploration</a>\n<figcaption> HoloNavi object target navigation whole process: hierarchical semantic matching, online multi-view verification and cutting-edge incremental exploration</figcaption>\n</div>\n<h4 id=\"-动态时空记忆自适应增量更新dynamic-memory-update\">⑥ Dynamic spatiotemporal memory adaptive incremental update (Dynamic Memory Update)</h4>\n<p>The real world is constantly evolving. HoloAgent-0 defines three types of core events that trigger memory refresh:</p>\n<ul>\n<li><strong>Perception conflict event</strong>: The new sensor data and the existing map are significantly offset in spatial geometry or color;</li>\n<li><strong>skill operation result event</strong>: The robot performs grasping placement (such as picking up a water cup) to cause the object to break away from the original support surface, or navigation is blocked and new obstacles are exposed;</li>\n<li><strong>Human explicit feedback event</strong>: The user issued error correction instructions for room naming or object attributes through voice.</li>\n</ul>\n<p>When performing an update, the memory layer first uses the current observation to perform robust relocation in the existing geometric map, locally clears out-of-date point clouds and voxels that cause conflicts, and integrates new features into the local geometry. The semantic layer updates the bounding box of the affected 3D instance, and HMSG <strong>only performs an in-situ topology update</strong> on the affected local subgraph (recalculates the room and visual angle to which the object belongs), without having to bear the high cost of reconstructing the entire global Scene graph.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/HoloAgent-0-dynamic-memory-update.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of adaptive refresh of local scene memory in dynamic environment (in-situ update of local map and Scene graph subgraph after desktop objects move)</a>\n<figcaption> Comparison of adaptive refresh of local scene memory in dynamic environment (in-situ update of local map and Scene graph subgraph after desktop object moves)</figcaption>\n</div>\n<hr/>\n<h3 id=\"3-核心结果发现\">3. Results and findings</h3>\n<ul>\n<li><strong>HM3D-ObjNav simulation benchmark navigation performance jumps</strong>: Under the standard simulation benchmark without hardware noise, HoloAgent-Nav equipped with AgentOS closed-loop achieved a success rate (SR) of <strong>82.6%</strong> and <strong>42.8% path length weighted success rate (SPL)</strong> is significantly ahead of existing representative navigation solutions in the industry, such as MSGNav (74.1% SR / 33.4% SPL), WMNav (72.2% SR / 33.3% SPL) and FSR-VLN in open-loop state (80.8% SR / 41.0% SPL), confirming that the closed-loop monitoring and retry re-planning mechanism can significantly improve the completion rate of complex tasks while ensuring path efficiency.</li>\n<li><strong>Excellent robustness of long-distance navigation in real physical apartments</strong>: In the multi-target search evaluation of real indoor apartments, HoloAgent-Nav achieved a real arrival rate of <strong>97.70%</strong> under the most stringent Top-1@1.0m hit standard, and the Top-5 arrival rate reached <strong>98.90%</strong>; for comparison, the well-known baseline OK-Robot in the same scenario has only 60.92%, HOV-SG only 51.72%, and MobilityVLA only 34.48%. What’s even more striking is that the scores of HoloAgent-Nav under different judgment thresholds of 1.0m, 2.0m and 3.0m are completely consistent, indicating that the successful samples all accurately approach the core operating area within 1.0m, showing extremely robust position and orientation docking accuracy.</li>\n<li><strong>High-quality open vocabulary 3D semantic mapping</strong>: On the ScanNet data set, HoloAgent-Memory achieved <strong>31.58% mIoU</strong> and <strong>61.58% in online (Online) computing mode Frequency-weighted accuracy (f-Acc)</strong>, the performance clearly overwhelms other online mapping algorithms (such as Open-Fusion’s 18.02% mIoU, Concept-Graph’s 16.29% mIoU), and even approaches the large model mapping algorithm of offline computing, providing a solid and accurate high-quality semantic index base for upper-layer agents.</li>\n<li><strong>real robot multi-morphological complex long-distance composite tasks</strong>: Successfully completed on the Unitree G1/R1 bipedal humanoid and two-arm mobile platform including “finding objects from the bedroom”, “multi-machine voice collaborative dance guidance” and the extremely challenging “long-distance mobile laundry folding” (covering autonomous cruising from the mobile chassis to the target workstation, flexible clothing sorting and grasping with both arms) , table tiles to fine folding) and many other closed-loop tasks.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性\">4. Limitations</h3>\n<ul>\n<li>At present, the basic model of robot embodiment is still unable to seamlessly cover the complete action spectrum from large-scale spatial navigation, precise dual-arm operation to whole-body torque-level motion control with a single model. The system’s cross-embodiment migration of different physical configurations still relies on engineered controller bridging and dynamics tuning.</li>\n<li>The industry still lacks an end-to-end unified long-horizon real robot evaluation benchmark covering operation, multi-modal navigation and whole-body dynamic interaction. For large-scale complex architectural scenes, there is still room for further improvement in the delay of long-term cross-view feature fusion and fine-grained geometric reconstruction accuracy.</li>\n</ul>\n<h2 id=\"pigey\">2. Pigey (2026)</h2>\n<p>———Addressing the Orchestration Gap in Generalist Robots via Physical Agency</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2607.21725\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2607.21725</a></p>\n<hr/>\n<h3 id=\"精华-1\">Key takeaways</h3>\n<ul>\n<li><strong>reveals the “Orchestration Gap” of embodied intelligence</strong>: It is pointed out that the main bottleneck of current general-purpose robots is not the lack of low-level motion control capabilities, but the lack of a closed-loop orchestration architecture that can coordinate perception, planning, verification and recovery; a single end-to-end model is easily overfitted and blindly executed when directly prompted, resulting in greatly limited performance.</li>\n<li><strong>Pure inference time closed-loop physical agent (no need for any new training)</strong>: Build a closed-loop orchestrator Pigey driven by the Frontier Visual Language Model (Frontier VLM), decompose complex long-term instructions into short-term sub-goals, and only call the frozen motion strategy of the underlying organization through high-level perception and tools, without retraining or fine-tuning low-level weights at all.</li>\n<li><strong>Geometric Programming (TAMP) and Neural Strategy ($\\pi_{0.5}$) Complementary Dual Backend</strong>: Combining deterministic tasks with motion planning (TiP ToP) and end-to-end visual motion strategy ($\\pi_{0.5}$) are decoupled and integrated - rigid objects use grab-and-place planning with geometric certainty, and deformable objects, contact-intensive operations, or planning are seamlessly upgraded to VLA.</li>\n<li><strong>sensor and wrist vision conservative double verification mechanism</strong>: Split the open-loop “grab-and-release” atomic action, and use the gripper width sensor (<code class=\"language-plaintext highlighter-rouge\">is_grasped</code>) combined with the wrist camera image to perform strict conservative verification after grasping; if grasping is not stable, immediately retry or upgrade in place, eliminating the compound error of “empty gripper delivery” from the source.</li>\n<li><strong>out-of-distribution and real robot long-term task performance leap</strong>: The frozen $\\pi_{0.5}$-LIBERO zero-sample success rate soared from 12.8% to 53.3% on the strong perturbation benchmark LIBERO-PRO; it reached 97.3% in 30 complex long-term evaluations of the real DROID robotic arm The overall success rate (baseline $\\pi_{0.5}$ is only 16.7%).</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-1\">1. Background and problem</h3>\n<p>With the development of large models and robotics technology, the field of robotics generally tends to build huge single vision-language-action (VLA) models, hoping to integrate high-level semantic understanding, common sense reasoning, space planning, successful detection, abnormality recovery and underlying millimeter-level motor control into the same neural network through large-scale pre-training. However, this monolithic end-to-end paradigm faces practical bottlenecks that are difficult to overcome:</p>\n<ol>\n<li><strong>Instruction sensitivity and semantic degradation</strong>: In the end-to-end strategy, high-level natural language instructions often degrade into weak prior conditions, and the model can easily fall into the mechanical memory of specific training trajectories and completely lose its ability to adjust when faced with scene disturbances (such as target displacement, occlusions, and the target is occupied);</li>\n<li><strong>open-loop execution and compound errors</strong>: Existing code-as-policies or traditional task and motion planning (TAMP) often rely on one-time offline generation and are in an open-loop blind running state during the execution phase; once grasping slippage or collision occurs in the middle, the system still advances mechanically according to the predetermined trajectory, and ultimately fails completely;</li>\n<li><strong>Lack of orchestration capabilities</strong>: True physical versatility requires the system to have a “Physical Agency” - not only knowing “what to do”, but also observing “whether it was done or not” during execution, and actively retrying, bypassing obstacles or changing means when it fails.</li>\n</ol>\n<p><strong>Core question</strong>: Without retraining or fine-tuning the underlying motion strategy at all, can the full potential of the pre-trained frozen strategy be unleashed and bridge the “orchestration gap” of general-purpose robots through only a closed-loop physical orchestration framework at inference time?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-1\">2. Methods and innovations</h3>\n<p>The core idea of Pigey is to decouple <strong>control and orchestration</strong>: the bottom layer only retains two frozen motion executors (TAMP planner and $\\pi_{0.5}$ VLA), and the upper layer consists of cutting-edge VLM (such as multi-modal cutting-edge large models such as Claude/GPT) to form a closed-loop decision-making brain, running “Perceive”→ The physical execution cycle of “Reason → Action → Verify”.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Pigey closed-loop physical Agent system architecture: cutting-edge VLM acts as an orchestrator to coordinate perception, reasoning, execution and double verification, routing down to the frozen TAMP and VLA motion backends</a>\n<figcaption>Pigey closed-loop physical Agent system architecture: Frontier VLM acts as an orchestrator to coordinate perception, reasoning, execution and double verification, routing down to the frozen TAMP and VLA motion backend</figcaption>\n</div>\n<h4 id=\"-整体框架概述-1\">① Overview of the overall framework</h4>\n<p>As a closed-loop embodied intelligence Agent, Pigey maintains the global context history $h$ after receiving the global long instruction $I$ (for example: “A child is visiting - put the toys on the plate and put the dangerous items in the box”). In each step of interaction, VLM only selects and calls a structured tool (Tool Call), obtains real feedback from the physical world sensors and cameras, and updates the internal state accordingly until all sub-goals are achieved and terminated by calling <code class=\"language-plaintext highlighter-rouge\">Done</code>.</p>\n<p>The system splits the complex responsibilities originally undertaken by a single large model into clear module chains:</p>\n<ul>\n<li><strong>Open vocabulary target perception and spatial anchoring</strong>: Use the open vocabulary detector to lock objects and their labels in the scene to limit the vocabulary space of high-level planning;</li>\n<li><strong>Task-level long-term memory</strong>: Maintain the list of completed operations, current gripper holdings and remaining items on the desktop;</li>\n<li><strong>Geometry and Neural Dual Motion Backend</strong>: Rigid catch-and-release analytically verifiable TAMP, irregular/contact-intensive operation VLA;</li>\n<li><strong>Conservative double verification and two-way upgrading and downgrading engine</strong>: Sensor signals and visual judgments support each other, driving retry, troubleshooting and strategy switching.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Pigey’s physical reasoning capabilities demonstrated in real robot dog/robot arm scenarios: deductive reasoning, safety common sense, obstacle elimination, long-term scene memory and spatial geometry stacking</a>\n<figcaption>Pigey’s physical reasoning capabilities demonstrated in real robot dog/robot arm scenarios: deductive reasoning, safety common sense, obstacle elimination, long-term scene memory and spatial geometry stacking</figcaption>\n</div>\n<h4 id=\"-逐模块讲解\">② Explain module by module</h4>\n<ul>\n<li><strong>Perception and target semantic anchoring (Perceive &amp; Grounding)</strong>\n<ul>\n<li><strong>Input</strong>: multi-view camera images (main view and wrist view) and underlying robot joint status.</li>\n<li><strong>Processing</strong>: Call the open vocabulary detector to generate a set of object candidates with bounding boxes and semantic labels. These detection tags strictly constitute Pigey’s “controlled vocabulary” (Vocabulary), and the parameters of all grasping or placement operations must directly reference the detection tags.</li>\n<li><strong>output</strong>: structured scene perception dictionary, including object label list, local high-resolution image of the wrist and current gripper status.</li>\n<li><strong>Design motivation</strong>: To prevent the language model from inventing the names of unseen objects out of thin air in physical interactions, connect high-level fuzzy concepts (such as “dangerous goods”, “vegetarian food”, “smallest container”) directly to specific entities that have been positioned in the physical scene.</li>\n</ul>\n</li>\n<li><strong>Decoupled complementary dual-motion backends (Frozen Motor Backends)</strong>\n<ul>\n<li><strong>TAMP geometric backend (<code class=\"language-plaintext highlighter-rouge\">Pick(ℓ)</code> / <code class=\"language-plaintext highlighter-rouge\">DropAbove(ℓ)</code>)</strong>: built based on the TiPToP framework, responsible for spatial collision-free motion planning and six-degree-of-freedom geometric grasping pose generation. Pigey performed a key refactoring - forcibly cutting Pick-and-Place, which was originally packaged as a single open-loop execution, into two independent tool calls, and inserting physical verification between grasping and placement.</li>\n<li><strong>VLA neural backend (<code class=\"language-plaintext highlighter-rouge\">VLARollout(s)</code>)</strong>: encapsulates frozen pre-training $\\pi_{0.5}$ closed-loop visual action control model, receiving short plain text sub-action description $s$ (such as <code class=\"language-plaintext highlighter-rouge\">“grasp the cable”</code>), directly outputs continuous high-frequency end displacement and clamping jaw opening and closing.</li>\n<li><strong>collaborative mechanism</strong>: Conventional rigid objects tiled on the desktop call TAMP first to obtain extremely high trajectory certainty; stacked objects, easily deformable objects (such as cables, plush toys), or objects in deep containers are directly solved by VLA with compliant control characteristics.</li>\n</ul>\n</li>\n<li><strong>Conservative Dual Verification</strong>\n<ul>\n<li><strong>input</strong>: the Boolean quantity <code class=\"language-plaintext highlighter-rouge\">is_grasped</code> read by the displacement sensor embedded in the gripper, and the hand-eye (wrist) camera snapshot after the action is completed.</li>\n<li><strong>processing</strong>: The hardware sensor is used to confirm whether the physical clamping gap is within the clamping threshold; the leading edge VLM simultaneously observes the wrist camera to determine whether the target object in the field of view has been moved away from its original position and is in the center of the clamping jaw.</li>\n<li><strong>conservative synthesis rule</strong>: Both adopt the most pessimistic strategy - even if the motion backend report is completed, as long as <code class=\"language-plaintext highlighter-rouge\">is_grasped == False</code> or the visual display target is still on the table, the step will be immediately judged as a failure and subsequent actions will be cancelled.</li>\n</ul>\n</li>\n</ul>\n<h4 id=\"-卡点降维与决策流图\">③ Dimensionality reduction and decision flow diagram of stuck points</h4>\n<p>Readers in the field of embodied intelligence are often confused: <strong>Why is the single end-to-end model (such as $\\pi_0$ / $\\pi_{0.5}$) still unable to perform simple catch and release with perturbation after large-scale pre-training? What exactly did Pigey’s closed-loop orchestration change?</strong></p>\n<p>We dismantle its inner mechanism through the self-made Mermaid decision flow chart and comparison table:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    Start[\"input: Natural language long instructions I + Scene global observation\"] --&gt; Perceive[\"Perceive: Open vocabulary detection object label collection\"]\n    Perceive --&gt; Reason[\"Reason: Plan the next short-term sub-goal based on situational history\"]\n    Reason --&gt; CheckType{\"Target object type and physical state?\"}\n    CheckType -- \"desktop rigid object\" --&gt; CallTAMP[\"call TAMP Planner: Pick(ℓ)\"]\n    CheckType -- \"Flexible/Cable/complex contact\" --&gt; CallVLA[\"call π0.5 VLA: VLARollout(s)\"]\n    CallTAMP --&gt; DualVerify{\"double check: is_grasped and the wrist image is in place?\"}\n    CallVLA --&gt; DualVerify\n    DualVerify -- \"Verification passed (True)\" --&gt; Place[\"Allow to proceed to next step: DropAbove(Target location)\"]\n    DualVerify -- \"Verification failed (False)\" --&gt; CheckRetry{\"Number of retries?\"}\n    CheckRetry -- \"first failure\" --&gt; Retry[\"Re-perceive and update pose -&gt; Try again in place\"]\n    CheckRetry -- \"Second failure\" --&gt; Escalate[\"Two-way strategy upgrade: TAMP switch to VLA\"]\n    Retry --&gt; CallTAMP\n    Escalate --&gt; CallVLA\n    Place --&gt; CheckAllDone{\"Has the global goal been achieved??\"}\n    CheckAllDone -- \"Not completed\" --&gt; Reason\n    CheckAllDone -- \"All done\" --&gt; Finish[\"call Done terminate and deliver\"]\n</code></pre>\n<p>To further see Pigey’s subversion of the traditional robot control paradigm, the comparison table is as follows:</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>End-to-end single VLA (such as $\\pi_{0.5}$ / OpenVLA)</th>\n<th>open-loop code planning (Code-as-Policies / TiPToP)</th>\n<th>closed-loop physical agent (Pigey article)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Control division of labor</strong></td>\n<td>Language understanding, planning, verification and motion control are all coupled into a single large model</td>\n<td>LLM generates complete Python code or action plan, and the underlying open-loop is completed</td>\n<td>Frontier VLM is only responsible for closed-loop orchestration and verification, and all actions are delegated to the freezing strategy</td>\n</tr>\n<tr>\n<td><strong>execution mode</strong></td>\n<td>Step autoregressive, lack of reflection on macro task status</td>\n<td>One-time planning, “blind” to object slippage and environmental changes during execution</td>\n<td>Each tool call must undergo double verification by sensors and vision, and dynamic closed-loop advancement</td>\n</tr>\n<tr>\n<td><strong>Abnormal recovery</strong></td>\n<td>Extremely poor (after catching the air, continue to place the air gripper later)</td>\n<td>None (planning failure or execution interruption directly throws an exception and crashes)</td>\n<td>Native support for obstacle removal, replacement and re-grabbing, TAMP and VLA two-way upgrading and downgrading</td>\n</tr>\n<tr>\n<td><strong>Training cost</strong></td>\n<td>Tens of thousands of hours of real robot trajectory re-fine-tuning/post-training are required</td>\n<td>No training required, but relies on an ideal simulation environment</td>\n<td><strong>Zero fine-tuning</strong>, fully utilizing ready-made frozen pre-trained models and classic planners</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>gives an example (target displacement and empty recovery)</strong>:\nSuppose the task is “put the red cup into the tray”.</p>\n<ul>\n<li><strong>single VLA / open-loop planning</strong>: calculate the grasping trajectory and execute placement directly and coherently. If the cup is bumped and slips when the robotic arm reaches down, the robotic arm will still close the empty gripper and move it to the top of the tray to release it, thinking that the “mission is completed”, and ultimately failing completely.</li>\n<li><strong>Pigey closed-loop processing</strong>:\n      <ol>\n<li>Execute <code class=\"language-plaintext highlighter-rouge\">Pick(red_cup)</code>;</li>\n<li>After the robotic arm is closed, the gripper width sensor returns to <code class=\"language-plaintext highlighter-rouge\">is_grasped = False</code>, and the wrist image detects that the cup is still in place;</li>\n<li>Pigey intercepts the subsequent <code class=\"language-plaintext highlighter-rouge\">DropAbove</code> action and records grasping failure;</li>\n<li>Trigger <code class=\"language-plaintext highlighter-rouge\">Perceive</code> to re-detect the precise coordinates of the cup after displacement, update the grasping posture and try again; if the cup is still not grasped correctly the second time, the backend is actively upgraded to <code class=\"language-plaintext highlighter-rouge\">VLARollout</code> with supple fault tolerance to implement tactile grasping, ultimately ensuring that the cup is securely placed on the plate.</li>\n</ol>\n</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-1\">3. Results and findings</h3>\n<p>The paper conducted a system comparative evaluation on the simulation benchmark LIBERO-PRO and the DROID workbench based on the real Franka robotic arm, which fully verified the multiplication effect of inference time physical orchestration on model capabilities.</p>\n<h4 id=\"-libero-pro-仿真基准评测\">① LIBERO-PRO simulation benchmark evaluation</h4>\n<p>LIBERO-PRO is the industry’s most difficult perturbation test benchmark for complex long-term desktop operations. It introduces six rigorous perturbation suites, including object position swap (Obj. swap), target attribute swap (Goal swap), and spatial geometry perturbation (Spatial swap/task).</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-libero-pro.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of success rates under LIBERO-PRO's six major perturbation suites: keeping the underlying frozen weights completely unchanged and only changing the inference orchestration mechanism</a>\n<figcaption>LIBERO-PRO Success rate comparison under six major perturbation suites: keeping the underlying frozen weight completely unchanged, only changing the inference orchestration mechanism</figcaption>\n</div>\n<ul>\n<li>The performance of the original SOTA VLA of <strong>has seriously declined.</strong>: When running directly with the open-loop prompt, even the current top $\\pi_{0.5}$-LIBERO has an average success rate of only <strong>12.8%</strong>, and directly returns to zero in multiple tasks, proving that the end-to-end strategy has seriously overfitted the training set trajectory.</li>\n<li><strong>Pigey achieves SOTA breakthrough</strong>: Under a zero-sample setting that does not use task-specific memory at all and does not fine-tune any weights, Pigey increases the average success rate of the freezing strategy to <strong>53.3%</strong>. Compared with the original strategy, it achieves a performance improvement of more than 4 times, significantly exceeding the code generation baseline. CaP-Agent0 (18.2%).</li>\n</ul>\n<h4 id=\"-真实机械臂droid能力测试\">② Real robot arm (DROID) capability test</h4>\n<p>In the real robot experiment, the research team set up 30 rigorous long-term tasks in 8 core competency dimensions, including common sense reasoning, conditional logic, spatial reasoning, obstacle clearance safety reasoning, active error recovery, and long-term memory recovery.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-droid-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Type 8 capability probe success rate (%) on the real robots arm DROID: The bottom layer all runs the same π0.5-DROID weight</a>\n<figcaption> Type 8 capability probe success rate (%) on the real robot arm DROID: The bottom layer all runs the same π0.5-DROID weight</figcaption>\n</div>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Pigey-qualitative-rollout.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Real robot long-term execution and single-frame inference chain demonstration: identifying non-vegetarian food and placing it in the bowl in sequence in the vegetarian selection task</a>\n<figcaption> real robot long-term execution and single-frame inference chain demonstration: identifying non-vegetarian food in the vegetarian selection task and placing it in the bowl in sequence</figcaption>\n</div>\n<ul>\n<li><strong>comprehensive success rate 97.3% vs 16.7%</strong>: $\\pi_{0.5}$-DROID under direct prompts was almost completely wiped out on tasks requiring common sense reasoning, multi-step logic and spatial geometry (success rates were all 0%), with an overall success rate of only 16.7%; while Pigey relied on closed-loop common sense orchestration With backtracking verification, it achieved 100% perfect scores in most categories, with a total success rate as high as <strong>97.3%</strong>.</li>\n<li><strong>real robot abnormal recovery record</strong>: When the placed target is occupied by foreign objects (such as debris in the coffee cup), Pigey can independently reason out the cascade recovery logic of “first remove the debris, place it next to it, and then put the target object in”; when the blind box blocks the target, it can infer that the target is under the box and actively lift the box to retrieve the object.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-1\">4. Limitations</h3>\n<ol>\n<li><strong>relies on cutting-edge large models for visual understanding and reasoning delay</strong>: Since the cloud or high-specification VLM needs to be called after each key action for visual reflection and decision-making, the overall task execution rhythm is limited by API communication and reasoning throughput, and the interaction delay is higher than that of a single end-to-end model;</li>\n<li><strong>The physical limit of the underlying action strategy cannot be exceeded</strong>: Although the orchestrator can greatly repair logic and grasping timing errors, if both underlying motion backends (TAMP solver and $\\pi_{0.5}$) cannot generate valid end trajectories due to singular points, collision deadlocks, or physical deformation distortion, it is still difficult for the upper-layer Agent to complete physical contact out of thin air.</li>\n</ol>\n<hr/>\n<h2 id=\"thea\">3. Thea (2026)</h2>\n<p>———Towards the Harness of Embodied Agents</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2608.11246\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2608.11246</a> · <a href=\"https://github.com/EIT-HAI/Thea\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a> · <a href=\"https://eit-hai.github.io/thea\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-2\">Key takeaways</h3>\n<ul>\n<li><strong>Migrating the “Code Agent Harness Paradigm” to the Embodied Physical World</strong>: Analogous to the successful essence of Claude Code and Codex in software engineering, it lies in the test feedback closed-loop (Harness) rather than the single model itself. It is pointed out that the key to realizing complex long-term tasks with embodied intelligence also lies in building a closed-loop Harness infrastructure that connects the physical reality.</li>\n<li><strong>Complements the two missing signal infrastructures in the physical world</strong>: The software world naturally has “reading world status” (file tree/AST) and “judging action results” (exit code/error call stack), while the physical world has neither. Thea innovatively proposed two cornerstone mechanisms, <strong>SceneGraph as Context</strong> (Scene graph is context) and <strong>Evaluation as Exit Codes</strong> (evaluator is exit code), to realize physical closed-loop.</li>\n<li><strong>Strict reliability theory establishes the theoretical bound of evaluation accuracy $\\alpha$</strong>: Mathematically proves that the success rate of long-term tasks open-loop exponentially decays with the number of steps $n$ ($P_{\\text{open}} = \\prod p_i \\to 0$); the error correction upper limit of closed-loop Harness strictly depends on the independent evaluator The judgment accuracy rate is $\\alpha$ (“The upper limit of Harness is determined by its judge”).</li>\n<li><strong>Cross-platform portability of decoupled models and embodiments</strong>: Defines the standardized embodiment Profile and Tool abstract contracts, the model (LLM/VLM) and the hardware embodiment (bipedal humanoid Unitree G1, bionic humanoid Astribot S1, double-arm wheeled AgileX Cobot Magic) are bidirectionally pluggable and replaceable, and a single set of architectures is deployed aCross-embodiments.</li>\n<li><strong>long-term compound task performance jumped significantly</strong>: In the real physics evaluation of multi-stage complex tasks (L1~L3), as the task complexity and number of steps increased, the success rate of traditional end-to-end strategies (ACT, $\\pi_{0.5}$, LingBot-VLA) dropped sharply to 30%~40%, while Thea still maintained the highest difficulty level at L3 Ultra-high success rate of <strong>87%</strong>.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-2\">1. Background and problem</h3>\n<p>The explosion of coding agents (Coding Agents, such as Claude Code, SWE-agent) has completely changed software engineering. The success of this type of system does not rest on the Superman model of “writing perfect code at once”, but on the <strong>test and retry closed-loop mechanism (Harness)</strong> composed of the compiler, testing framework and Git - the agent runs the test after writing the code, captures stack errors, reflects on modifications and iterates repeatedly until the test passes.</p>\n<p>When researchers attempted to translate this efficient Harness paradigm to the physical world, they encountered an essential structural gap. The foundational support that has taken decades to build up in the software world is all missing in the physical world:</p>\n<ol>\n<li><strong>state cannot be “read” natively</strong>: The code world has clear file systems and type symbols; while the sensors of physical robots only spit out chaotic and unstructured high-dimensional continuous point clouds and image pixels, which large models cannot directly use as accurate inferable context;</li>\n<li><strong>action cannot be “determined” natively</strong>: If an error occurs in the running program, a clear non-zero exit code (Exit Code) and stack trace (Stack Trace) will be returned immediately; but in reality, if the robotic arm reaches out to grasp, loses its hand, or collides, the physical world is silent. It will neither return a status code nor actively notify that “the action has ended”, resulting in infinite accumulation of errors during open-loop execution.</li>\n</ol>\n<p><strong>Core question</strong>: How to build a set of embodied Harness in the physical world that can provide “persistent readable state” and “accurate exit code determination”, so that high-level language/multi-modal models can reliably orchestrate underlying heterogeneous motion strategies and achieve closed-loop self-healing for long-term tasks?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-2\">2. Methods and innovations</h3>\n<p>Thea built an embodied closed-loop Harness that decouples the cutting-edge decision-making model (Model) from the diverse robot embodiment (Body) orchestration, and closed the embodied control loop through structured context evolution, standardized tool interfaces, and independent post-evaluators.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Thea Embodied Harness System Panorama: Completely decouple model (Model) and embodiment (Body), establish a perception-action-verification closed-loop through callable tools (Tool), Scene graph context (Scene graph) and independent evaluator (Evaluator), and verify it on three different embodiments</a>\n<figcaption>Thea Embodied Harness system panorama: Completely decouple the model (Model) and embodiment (Body), establish a perception-action-verification closed-loop through callable tools (Tool), Scene graph context (Scene graph) and independent evaluator (Evaluator), and verify it on three different embodiments</figcaption>\n</div>\n<h4 id=\"-整体框架概述-2\">① Overview of the overall framework</h4>\n<p>In the Thea architecture, embodied agent consists of four core components:</p>\n<ol>\n<li><strong>model (Model)</strong>: high-level large language/visual language model, only responsible for understanding tasks, reading dynamic context, and output structured tool calls;</li>\n<li><strong>embodiment and tool layer (Body &amp; Tools)</strong>: Unify the underlying mobile navigation, robotic arm grasping, and skill strategies (such as ACT, diffusion strategy, $\\pi_0$) into a standardized Tool with pre-check (Pre-hook) and post-trigger (Post-hook);</li>\n<li><strong>Scene graph context (SceneGraph as Context)</strong>: Precipitate a persistent, symbolic Scene graph with 3D bounding boxes and topological relationships from the continuous perceptual flow, analogous to the file system in software engineering;</li>\n<li><strong>exit code evaluator (Evaluation as Exit Codes)</strong>: an independent visual evaluator triggered by the system structure after each action, returning a three-state execution verdict (Success/Failure/In-progress) and failure attribution.</li>\n</ol>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-scenegraph.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: SceneGraph as Context: Fusion of continuous multi-modal observations from sensors and action results confirmed by evaluators into a unified symbol Scene graph, generating a streamlined briefing (Brief) that is refreshed in rounds and injected into the context, supporting on-demand in-depth queries.</a>\n<figcaption>SceneGraph as Context: Fusion of the sensor’s continuous multi-modal observation and the action results confirmed by the evaluator into a unified symbol Scene graph, generating a streamlined briefing (Brief) that is refreshed and injected into the context in rounds, and supports on-demand in-depth query</figcaption>\n</div>\n<h4 id=\"-逐模块讲解-1\">② Explain module by module</h4>\n<ul>\n<li><strong>SceneGraph as Context (readability of world state)</strong>\n<ul>\n<li><strong>Input</strong>: RGB image, depth map, LiDAR point cloud, and robot pose reported by the underlying odometer.</li>\n<li><strong>processing</strong>: The system uses the perception pipeline to discretize the continuous physical space into a dynamic graph structure containing the object center coordinates, 3D bounding box, visible confidence and spatial topological relationships (such as <code class=\"language-plaintext highlighter-rouge\">on(bowl, table)</code>, <code class=\"language-plaintext highlighter-rouge\">near(robot, table)</code>, <code class=\"language-plaintext highlighter-rouge\">holding(gripper, cup)</code>); only after passing through the evaluator Only the action results that are confirmed to be truly successful (Confirmed) will be written into the topological relationship changes of the graph.</li>\n<li><strong>output</strong>: Before each round of decision-making, the graph is refined into a high-level structured brief (Scene graph brief) and pushed into the refreshed context (Refreshed context); the model can also call tools on demand through reference ID (Ref-keyed queries) to query the historical high-definition snapshots and detailed geometric properties of a specific object.</li>\n<li><strong>Design motivation</strong>: Completely solve the problem of context being overwhelmed by massive continuous video/image tokens in long-term multi-round interactions, and give large models the ability to understand scenes similar to “reading the project code structure tree”.</li>\n</ul>\n</li>\n<li><strong>Evaluation as Exit Codes (Judgment of action results)</strong>\n<ul>\n<li><strong>trigger mechanism</strong>: Harness forces structured triggering through the built-in post-hook after each operation is executed, depriving the underlying execution strategy of the right to “self-evaluate and boast”.</li>\n<li><strong>Processing</strong>: evaluator It only receives the visual observation at the current moment and the post-condition declared by the tool, which is completely independent of the high-level decision-making model; it outputs three-state judgments - <code class=\"language-plaintext highlighter-rouge\">Success</code> (success), <code class=\"language-plaintext highlighter-rouge\">Failure</code> (failure with detailed causal explanation, such as “not grasped due to end offset”, “target blocked by drawer”), <code class=\"language-plaintext highlighter-rouge\">In-progress</code> (the action is still progressing for a long time and has not timed out).</li>\n<li><strong>output</strong>: Package the verdict and failure attribution into the exit code response and inject the conversation history for the decision-making model to perform targeted retry or solution switching.</li>\n</ul>\n</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-evaluator-exit-codes.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Evaluation as Exit Codes triggering sequence: the model calls the Tool execution strategy. After the execution, the Harness post-hook actively triggers the independent Evaluator, and outputs a three-state judgment with the failure reason and feeds it back to the model.</a>\n<figcaption>Evaluation as Exit Codes Trigger timing: The model calls the Tool execution strategy. After the execution is completed, the Harness post hook actively triggers the independent Evaluator, and outputs a three-state judgment with the failure reason and feeds it back to the model</figcaption>\n</div>\n<h4 id=\"-卡点降维与理论推导\">③ Dimensionality reduction and theoretical derivation of stuck points</h4>\n<p><strong>stuck point 1: How do software Harness and embodied physical Harness correspond?</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>Software Engineering Agent (such as Claude Code / SWE-agent)</th>\n<th>Traditional robot control (single VLA/teaching playback)</th>\n<th>Embodied Physics Harness (Thea)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>status carrier</strong></td>\n<td>File system directory tree, AST, text code</td>\n<td>Instantaneous single frame/multi frame continuous camera image pixels</td>\n<td><strong>SceneGraph as Context</strong> (persistent 3D topology symbol Scene graph)</td>\n</tr>\n<tr>\n<td><strong>action output</strong></td>\n<td>Terminal Shell Commands, File Editing Patch</td>\n<td>Continuous joint angles/end 6-DoF track points</td>\n<td>Semantic Tool encapsulated as standardized pre/post Hook (such as <code class=\"language-plaintext highlighter-rouge\">grasp(ref)</code>)</td>\n</tr>\n<tr>\n<td><strong>Execution feedback</strong></td>\n<td>Operating system return code (Exit 0 / 1), Stack Trace</td>\n<td>There is no feedback. Once the action is over, you will blindly proceed to the next step.</td>\n<td><strong>Evaluation as Exit Codes</strong> (three-state decision + structured failure diagnosis reason)</td>\n</tr>\n<tr>\n<td><strong>Error correction mechanism</strong></td>\n<td>Read the error log, rewrite the code and recompile</td>\n<td>There is no way to correct the error. After catching a short shot, I will run through the subsequent long sequence empty-handed.</td>\n<td>Read in the failure attribution, fine-tune the pose and try again or actively search for hidden targets</td>\n</tr>\n</tbody>\n</table>\n<p><strong>stuck point 2: Why is it said that “the upper limit of Harness is determined by its evaluator accuracy $\\alpha$”?</strong></p>\n<p>In a long-term multi-step embodied task, assuming a task contains $n$ sequential stages, the single-step success rate is $p_i$.</p>\n<ul>\n<li>In traditional open-loop mode, task success requires that every step must succeed:\n\\(P_{\\text{open}} = \\prod_{i=1}^n p_i\\)</li>\n<li>When $n$ is large (such as $n=5$), even if the single-step success rate is as high as $p=0.8$, the total success rate will quickly degrade to $0.8^5 \\approx 32.8\\%$.</li>\n</ul>\n<p>Thea introduces a detect-retry loop with a maximum retry count of $k$. The evaluator makes a correct judgment with an accuracy of $\\alpha$ and a wrong judgment with an accuracy of $1-\\alpha$. The paper strictly proves that because the evaluator has <strong>false negatives</strong> (misjudgment of true success as failure, resulting in redundant retries that damage the results) and <strong>false positives</strong> (misjudgment of failure as success, resulting in downward penetration of errors), the net pass reliability of each step of the system is directly determined by $\\alpha$ Locked:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    Exec[\"Execute single step action Attempt\"] --&gt; Eval{\"independent evaluator judgment (Accuracy α)\"}\n    Eval -- \"The verdict is Success (Contains true success p*α with false positives (1-p)*(1-α))\" --&gt; Pass[\"Release to next stage\"]\n    Eval -- \"The verdict is Failure (Contains true failure (1-p)*α with false negatives p*(1-α))\" --&gt; RetryCheck{\"Current attempts &lt; k ?\"}\n    RetryCheck -- \"Yes\" --&gt; Diagnose[\"parse Failure attribution -&gt; Adjust strategy and try again\"]\n    Diagnose --&gt; Exec\n    RetryCheck -- \"No\" --&gt; Abort[\"Step budget limit reached -&gt; Declare task failure and termination\"]\n</code></pre>\n<blockquote>\n<p><strong>gives an example (specific number of reliability doubling)</strong>:\nAssume a long-term delivery task of $n=5$ steps, and the success rate of the underlying strategy at each step is $p=0.8$:</p>\n<ul>\n<li><strong>open-loop running</strong>: the total success rate is only $0.8^5 = 32.8\\%$;</li>\n<li><strong>Thea closed-loop (evaluator precision $\\alpha=0.95$, allowed to retry $k=3$ times)</strong>: The effective reliability of a single step under retry and precise release jumps to $97.6\\%$, and the total success rate of the entire 5-step task reaches $0.976^5 \\approx 88.5\\%$ achieves a task-level reliability gain of nearly 3 times that of !</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-2\">3. Results and findings</h3>\n<p>Thea has carried out comprehensive real-life physical experimental verification on diverse hardware platforms (Unitree G1 humanoid robot, Astribot S1 flexible humanoid robot, AgileX Cobot Magic wheeled dual-arm collaborative robot).</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-task-complexity-scaling.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of task success rates across different difficulty levels (L1 basic operations, L2 spatial combination, L3 long-term long-distance multi-stage interaction): As the number of task steps increases, the baseline model drops off a cliff, while Thea maintains excellent robustness</a>\n<figcaption> Comparison of task success rates across different difficulty levels (L1 basic operations, L2 spatial combination, L3 long-term long-distance multi-stage interaction): As the number of task steps increases, the baseline model drops off a cliff, while Thea maintains excellent robustness</figcaption>\n</div>\n<h4 id=\"-随任务复杂度扩展的绝对优势\">① Absolute advantages that scale with task complexity</h4>\n<p>The evaluation divided the tasks into three levels: L1, L2, and L3 according to time course and stage complexity, and compared mainstream single or layered baselines such as ACT, $\\pi_{0.5}$, LingBot-VLA-V2, CaP-X, and SayCan:</p>\n<ul>\n<li><strong>L1 base layer (short-term single step)</strong>: There is not much difference between each baseline and Thea, and the success rate is between 80% and 95%;</li>\n<li><strong>L2 Advanced level (including space rearrangement and multi-step dependency)</strong>: The single strategy begins to experience trajectory drift and short-sucking disorder, the success rate drops to 55%~80%, Thea reaches <strong>90%</strong>;</li>\n<li><strong>L3 Ultimate layer (cross-room long-distance navigation + drawer opening retrieval + target object grasping and delivery)</strong>: Single model (such as $\\pi_{0.5}$, LingBot) plummeted to <strong>40%</strong> due to accumulated error, SayCan Due to the lack of fine-grained geometry and closed-loop verification, it is only 53%, while Thea maintains a success rate of <strong>87%</strong> with closed-loop retries and Scene graph memory.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Thea-emergent-capabilities.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Diversified physical intelligence behaviors that emerged driven by Thea: (a) autonomously draw power across rooms and deliver power banks; (b) actively open drawers for hierarchical retrieval when the target is not seen; (c) fine-tune poses for secondary grasping based on the failure reasons fed back by the evaluator; (d) proactively initiate human-machine dialogue to negotiate alternatives when the target drink is out of stock; (e) seamless migration of a single set of Harness across three completely different robot embodiments</a>\nThe diverse physical intelligent behaviors that emerged driven by<figcaption>Thea: (a) autonomously draw power across rooms and deliver power banks; (b) actively open drawers for hierarchical retrieval when the target is not seen; (c) fine-tune the pose for secondary grasping based on the failure reasons fed back by the evaluator; (d) actively initiate human-machine dialogue to negotiate alternatives when the target drink is out of stock; (e) a single set of Harness across three completely different robots Seamless migration</figcaption>\n</div>\n<h4 id=\"-闭环涌现出的高级物理行为\">② Advanced physical behaviors emerging from closed-loop</h4>\n<p>Thanks to the dynamic closed-loop orchestration of tools by the general Harness architecture, the robot exhibits several high-order emergent behaviors that could not be achieved by the previous single model:</p>\n<ul>\n<li><strong>Active Perception</strong>: When the power bank is not retrieved in the Scene graph, the model actively plans the detection link of “navigate to the counter → call the drawer pull tool → tilt the wrist camera to observe the inner layer of the drawer”;</li>\n<li><strong>Targeted fault diagnosis and correction (Diagnosed Recovery)</strong>: When the grasping can slips due to too far distance, the evaluator returns <code class=\"language-plaintext highlighter-rouge\">“Fail: target slipped due to hand clearance offset”</code>, and the model actively generates <code class=\"language-plaintext highlighter-rouge\">reposition(base, delta=[-0.05, 0])</code> in the next round. After adjusting the micro distance of the base, grasping is successful again;</li>\n<li><strong>Human-computer collaborative interaction (User Clarification)</strong>: When the user requests the delivery of specific mineral water but only juice and tea are available on the desktop, the Agent autonomously suspends physical execution and asks the user questions to negotiate alternatives through the mobile phone interface.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-2\">4. Limitations</h3>\n<ol>\n<li><strong>Scene graph maintenance computational overhead and latency bottleneck</strong>: As the indoor exploration space continues to expand, the computational overhead of 3D instance point cloud segmentation and real-time topology map merging increases significantly, which may lead to significant lags in round decision-making;</li>\n<li><strong>Risk of misjudgment of the evaluator under three-dimensional occlusion and extreme deformation</strong>: The evaluator relies on visual feedback from a single perspective or a hand-eye camera. Misjudgment may still occur under strong reflection, small object occlusion or extreme lighting conditions. Once a misjudgment occurs, it will directly limit the final reliability of the system.</li>\n</ol>\n<hr/>\n<h2 id=\"zetta\">4. Zetta (2026)</h2>\n<p>———An Efficient Closed-Loop Embodied Harness for Self-Evolving Physical Intelligence</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2608.16590\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2608.16590</a> · <a href=\"https://air-embodied-brain.github.io/zetta\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-3\">Key takeaways</h3>\n<ul>\n<li><strong>proposes an embodied closed-loop Harness for self-evolution physical intelligence</strong>: Aiming at the dilemma that end-to-end single VLA/WAM lacks micro-correction during execution and traditional post-hoc reflection (Post-hoc Reflection) is difficult to attribute high-frequency physical interactions, a self-evolution system Zetta is built that integrates high-frequency online judgeing, in-situ exception recovery and offline skill distillation.</li>\n<li><strong>Structured evolvable Harness abstraction ($H = {C, R, T}$)</strong>: Keep the underlying motion strategy frozen with the high-level orchestration commander, and define Harness decoupling as a runtime judge collection $C$, a recovery action library $R$, and a heterogeneous toolset $T$. The physical trial and error experience is directly distilled into parameterized code modules, which evolve autonomously with the interaction rounds.</li>\n<li><strong>Top-down minimal intervention hierarchical causal diagnosis</strong>: Establish the core principle of “if the high-level logic can be solved, never change the underlying parameters”, conduct top-down investigation according to priority (evaluation → judge → status → planning → recovery → parameters) to prevent generalization collapse caused by overfitting to a single use case.</li>\n<li><strong>Discovering the Robotic “Aha Moment” of Embodied Physical Intelligence</strong> : Reveals the objective law of the nonlinear transition of embodied self-evolution - the initial repair of the appearance keeps the performance at a low plateau. Once the root cause is located and the key “judge-recovery” closed-loop mechanism is evolved, the task success rate shows an instant vertical increase (such as a sudden surge from 10% to 95%).</li>\n<li><strong>High-throughput infrastructure with decoupled software and hardware Z-Infra</strong>: Design a multi-node heterogeneous concurrent infrastructure, decouple the environment from the model computing pool, achieve an effective sampling throughput of up to 35.1 episodes/min (20.6 times improvement), and significantly shorten the inference delay by 91%, strongly supporting large-scale closed-loop self-evolution.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-3\">1. Background and problem</h3>\n<p>Although Vision-Language-Action (VLA) and World Action Model (WAM) have made significant progress in large-scale data pre-training, they are still highly fragile when deployed in the physical world. The root cause is: <strong>The physical environment is a continuous system</strong> that evolves at high frequency at the millisecond level. If an object slips slightly, the desktop reaction force is unbalanced, or a small contact disturbance is not sensed and corrected at the moment of occurrence, it will quickly trigger a compound error cascade, eventually leading to the collapse of the global task.</p>\n<p>In order to overcome this bottleneck, in recent years, academic circles have tried to introduce multi-modal Agents for “Post-hoc Reflection”. However, traditional reflection mechanisms face insurmountable theoretical and engineering obstacles in embodied physical scenarios:</p>\n<ol>\n<li><strong>Credit Assignment Problem (Credit Assignment Problem)</strong>: A long-term operation failure involves hundreds or thousands of continuous control steps. Afterwards, the large model is asked to reflect in detail. The model cannot accurately infer which tiny declination angle of the wrist in the few seconds caused the disaster;</li>\n<li><strong>Lack of on-site online verification environment</strong>: The corrective hypothesis generated by post-mortem reflection can only be tested after the next complete re-run, which is extremely inefficient and easily misleading;</li>\n<li><strong>Patching causes over-fitting (Over-Parameterized Repair)</strong>: In the past, manual tuning or simple parameter tuning often forcibly modified the underlying control parameters for specific failed use cases, which not only destroyed the global semantic understanding and generalization distribution of the base VLA, but also caused catastrophic performance degradation in unseen environments and new random seeds.</li>\n</ol>\n<p><strong>Core question</strong>: How to build an embodied closed-loop Harness that does not need to modify the underlying policy parameters, can achieve high-frequency micro online correction, and can automatically sublimate failed physical experience and continue to evolve autonomously?</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-3\">2. Methods and innovations</h3>\n<p>Zetta proposes a dual-loop physical intelligence system that integrates online high-frequency governance <strong>and offline autonomous evolution</strong>. Together with the hardware-decoupled high-throughput concurrent infrastructure Z-Infra, it achieves self-propagation and robust evolution of physical strategies.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Zetta self-evolution embodied Harness panorama: high-frequency runtime judge leads the online action error correction loop, offline evolution Agent clusters failure trajectories and distills reusable skills, and cooperates with the decoupled infrastructure Z-Infra to drive throughput doubling and \"aha moment\"</a>\n<figcaption>Zetta self-evolution Embodied Harness Panorama: High-frequency running time, the judge leads the online action error correction loop, offline evolution Agent clusters failure trajectories and distills reusable skills, and cooperates with the decoupled infrastructure Z-Infra to drive throughput doubling and \"aha moment\"</figcaption>\n</div>\n<h4 id=\"-整体框架与双环运行机制\">① Overall framework and double-loop operating mechanism</h4>\n<p>Zetta clearly divides the system into two immutable entities and a core evolution carrier:</p>\n<ul>\n<li><strong>Two immutable entities</strong>: underlying action strategy $\\pi$ (frozen VLA/WAM parameters, $\\nabla_\\theta = 0$) and high-level orchestration Agent $A_{orch}$ (multimodal decision operator, constant decision logic);</li>\n<li><strong>core evolution carrier Harness ($H = {C, R, T}$)</strong>:\n    <ul>\n<li><strong>Runtime Critics ($C$)</strong>: A high-frequency monitoring function that runs higher than the low-level action strategy, continuously scans real-time trajectory fragments and generates proposals with fault evidence and status suggestions \\(P_t = \\langle e_t, \\hat{\\sigma}_t \\rangle\\);</li>\n<li><strong>Recovery Action Library (Recovery Playbook, $R$)</strong>: A collection of parameterized micro-actions targeting specific fault causal mechanisms;</li>\n<li><strong>Heterogeneous Toolset ($T$)</strong>: motion planner, 6-DoF grasping generator (GraspGen) and placement stabilizer.</li>\n</ul>\n</li>\n</ul>\n<p>The operation of the system is divided into <strong>online parallel Rollout</strong> and <strong>offline Reflection &amp; Evolve evolution cycle</strong>:</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-evolution-framework.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Zetta evolution framework three-stage process: online concurrent collection of success and failure trajectories, offline Harness update through failure portrait clustering (Phase I), hierarchical causal diagnosis and repair (Phase II), and cross-task generalization merging (Phase III)</a>\n<figcaption>Zetta evolution framework three-stage process: online concurrent collection of success and failure trajectories, offline update through failure portrait clustering (Phase I), hierarchical causal diagnosis and repair (Phase II), and cross-task generalization merging (Phase III) Harness</figcaption>\n</div>\n<h4 id=\"-逐模块讲解-2\">② Explain module by module</h4>\n<ul>\n<li><strong>Phase I: Failure Profiling</strong>\n<ul>\n<li><strong>input</strong>: a collection of failed trajectories collected concurrently by multiple threads, and the corresponding nominal success reference trajectory (Nominal baseline).</li>\n<li><strong>processing</strong>: Slice the failed trajectories according to the physical stages of task advancement (pre-contact approach, grasping closure, spatial transportation, placement and release), and use the successful trajectories as the benchmark to cluster common instability modes.</li>\n<li><strong>outputs</strong>: a structured failure portrait list, pinpointing the common stage distribution of multiple failures.</li>\n</ul>\n</li>\n<li><strong>Phase II: Hierarchical causal diagnosis and minimal intervention repair (Diagnosis &amp; Repair)</strong>\n<ul>\n<li><strong>Top-down diagnostic level</strong>: Strictly follow the six-level priority investigation:\n\\(\\text{Evaluation} \\to \\text{Critic} \\to \\text{State} \\to \\text{Planning} \\to \\text{Recovery} \\to \\text{Parameter}\\)</li>\n<li><strong>Design Motivation</strong>: Give priority to solving problems by adding pre-aligned critics at high levels or calling geometric planning tools; it is strictly prohibited to directly dive into tampering with the joint stiffness of the underlying motor or fine-tune the low-level weights to maximize the broad generalization of the base model.</li>\n<li><strong>Validation Guard</strong>: Each code-level fix patch generated must be retested in-place on the same random seed that caused the failure, and submission is only allowed if it passes validation (Validate Passed).</li>\n</ul>\n</li>\n<li><strong>Phase III: Harness Generalization and Merger (Harness Generalization)</strong>\n<ul>\n<li><strong>processing</strong>: Promote the specific seed patch that has passed verification into a universal judge and recovery logic with abstract parameters, perform conflict-free merging across use cases, package and generate versioned $H_{merged}$, and hot-reload it to the online environment.</li>\n</ul>\n</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-critic-recovery-sequence.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Record of judge-recovery cascade intervention in a single rollout: when an object is detected to be off during transportation, re-approach is immediately triggered, when an invalid posture is detected, GraspGen is called to generate the posture, and in the final stage, smooth placement recovery is called</a>\n<figcaption> Record of judge-recovery cascade intervention in a single rollout: when an object is detected to be off during transportation, re-approach is immediately triggered, when an invalid posture is detected, GraspGen is called to generate the posture, and in the final stage, smooth placement recovery is called</figcaption>\n</div>\n<h4 id=\"-卡点降维与自制架构图\">③ Card point dimensionality reduction and self-made architecture diagram</h4>\n<p><strong>stuck point 1: Why can’t physical interaction be solved by post-mortem reflection? How exactly does Zetta’s microscopic closed-loop work?</strong></p>\n<p>We clearly present the decoupled collaboration of Zetta’s online millisecond-level interception and offline minute-level self-evolution through the Mermaid double-loop mechanism diagram:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    subgraph Online [\"Online high-speed execution loop (millisecond level)\"]\n        Obs[\"Real-time sensor observations s_t\"] --&gt; Policy[\"freeze action strategy π (VLA)\"]\n        Policy --&gt; Action[\"Predictive control actions a_t\"]\n        Action --&gt; Critic{\"High frequency runtime judge C Monitor\"}\n        Critic -- \"Nominal normal (Nominal)\" --&gt; Exec[\"Physical execution of actions\"]\n        Critic -- \"trigger exception (Slip/Collision)\" --&gt; Intervene[\"Suspend action, call Recovery R\"]\n        Intervene --&gt; Tool[\"Toolset T (Such as GraspGen / Re-approach)\"]\n        Tool --&gt; Exec\n        Exec --&gt; StatusCheck{\"determine the Episode Is it over??\"}\n        StatusCheck -- \"Not over\" --&gt; Obs\n        StatusCheck -- \"success/failed\" --&gt; Buffer[\"Save to track storage pool\"]\n    end\n\n    subgraph Offline [\"Offline evolving self-healing loop (Minute level)\"]\n        Buffer --&gt; Cluster[\"Phase I: Failure trajectory clustering and stage slicing\"]\n        Cluster --&gt; Diagnosis[\"Phase II: top-down causal diagnosis (E -&gt; C -&gt; S -&gt; P -&gt; R)\"]\n        Diagnosis --&gt; Patch[\"Synthesis reusable Critic / Recovery Skill code\"]\n        Patch --&gt; Test{\"Validation guard: Original failed seed retest verification\"}\n        Test -- \"Verification passed\" --&gt; Generalize[\"Phase III: Abstract and merge to generate a new version H_merged\"]\n        Generalize --&gt; Online\n    end\n</code></pre>\n<p><strong>stuck point 2: What is the “Aha Moment” of embodied physical intelligence?</strong></p>\n<p>In the process of embodied self-evolution, many readers easily mistakenly believe that the success rate of the strategy will increase uniformly and linearly with the amount of interactive data. Zetta reveals a very physically inspiring phenomenon:</p>\n<table>\n<thead>\n<tr>\n<th>Evolution stage</th>\n<th>Repair strategy type</th>\n<th>typical behavior</th>\n<th>Success rate performance</th>\n<th>essential reason</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Round 0 (initial)</strong></td>\n<td>Pure Freeze VLA open-loop run</td>\n<td>Grabbing air, sliding, and hard collision between the end and the table</td>\n<td>0% ~ 15% (very low)</td>\n<td>Lack of any physical interaction feedback</td>\n</tr>\n<tr>\n<td><strong>Round 1 (Initial exploration)</strong></td>\n<td><strong>Symptomatic Fixes</strong> (Symptomatic Fixes)</td>\n<td>Relax the time budget, increase the number of retries, and increase the clamping jaw closing threshold</td>\n<td>5% ~ 15% (<strong>stagnation plateau period</strong>)</td>\n<td>The root cause of physical failure has not been touched, and errors still occur during transportation.</td>\n</tr>\n<tr>\n<td><strong>Round 2 (moment of enlightenment)</strong></td>\n<td><strong>Root-Cause Repair</strong> (Root-Cause Repair)</td>\n<td>Evolved <code class=\"language-plaintext highlighter-rouge\">Pre-grasp Staging</code> (front space posture alignment) and <code class=\"language-plaintext highlighter-rouge\">Grasp Retention Critic</code> (slip-off high-frequency interception)</td>\n<td><strong>instantly soared to 90% ~ 95%</strong></td>\n<td>Completely solves the line of sight obstruction and initial normal vector misalignment when the robotic arm reaches down.</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Give an example (the epiphany deduction of putting a red wine bottle into a deep dish)</strong>:\nThe task requires a robotic arm to place an upright red wine bottle smoothly onto a plate.</p>\n<ul>\n<li><strong>Stage 1 (Pure VLA)</strong>: Pounces directly towards the bottleneck, frequently knocking over wine bottles due to reflection and perspective deviation, the success rate is only 5%;</li>\n<li><strong>Phase 2 (Trying to cure the symptoms)</strong>: Evolution Agent tries to make the robot arm quickly retreat after grasping fails and increase the speed to try again. However, the bottle has been knocked crooked, and the next descent will inevitably miss the target again. The success rate is always hovering around 10%;</li>\n<li><strong>Stage 3 (Aha Moment)</strong>: Evolution Agent finally discovered the fundamental contradiction through causal diagnosis - “The bottle body is slender. If a pre-aligned posture is not established from the side, direct dive will inevitably touch the mouth of the bottle.” So Zetta automatically synthesized two collaborative mechanisms:\n      <ol>\n<li><code class=\"language-plaintext highlighter-rouge\">Pregrasp Staging</code>: The robotic arm first hovers 5cm directly in front of the bottle and flattens the wrist;</li>\n<li><code class=\"language-plaintext highlighter-rouge\">Retention Critic</code>: Monitor the terminal inclination angle in real time during the lifting process, and immediately decelerate and fine-tune it once it slips.\nAfter the patch is loaded, the success rate of this task changes from <strong>10% jumps to 90%</strong> , truly crossing the physical bottleneck!</li>\n</ol>\n</li>\n</ul>\n</blockquote>\n<hr/>\n<h3 id=\"3-核心结果发现-3\">3. Results and findings</h3>\n<p>Zetta conducted system evaluations on the international common embodied operation benchmark LIBERO-Pro and the RoboCasa kitchen long-term benchmark, and conducted comprehensive comparisons with the latest end-to-end baselines and Agent systems.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-aha-moments.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The “Aha Moment” of physical intelligence on LIBERO-Pro: Initial temporary fixes caused performance to stagnate for a long time. Once the root cause is located and the key judge-recovery mechanism is generated, the success rate increases dramatically.</a>\nThe \"Aha Moment\" of physical intelligence on<figcaption>LIBERO-Pro: The initial temporary fix caused the performance to stagnate for a long time. Once the root cause is located and the key judge-recovery mechanism is generated, the success rate increases sharply</figcaption>\n</div>\n<h4 id=\"-卓越的任务成功率与自演化扩展性\">① Excellent task success rate and self-evolution scalability</h4>\n<ul>\n<li><strong>LIBERO-Pro simulation benchmark</strong>: In the most challenging perturbation test, the success rate of the pure $\\pi_{0.5}$ strategy was only 34.5%, while Zetta went through several rounds of autonomous closed-loop evolution and finally significantly increased the success rate to <strong>90.8%</strong>;</li>\n<li><strong>RoboCasa virtual kitchen benchmark</strong>: In the complex long-term hinge cabinet door opening, kitchen appliance operation and item organization tasks, the success rate of the base model GR00T is 73.6%. After Zetta’s independent evolution, it reaches the ultra-high level of <strong>93.6%</strong>;</li>\n<li><strong>Endless evolutionary gains</strong>: Experiments have proven that with the accumulation of concurrent rollout experience pool, the self-evolution curve continues to rise, completely breaking the performance deadlock of traditional fixed strategies under data bottlenecks.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Zetta-cross-task-scaling.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-task zero-sample skills transfer verification: The pre-grasping, grasping retention and retry skill stacks precipitated in the source task (Goal-T8 red wine bottle operation) have been implemented on unseen target tasks (Goal-T2, T6, S3) without fine-tuning plug-and-play migration.</a>\n<figcaption> Cross-task zero-sample skills transfer verification: The pre-grasping, grasping retention and retry skill stacks precipitated in the source task (Goal-T8 red wine bottle operation) are implemented on the unseen target tasks (Goal-T2, T6, S3) without fine-tuning plug-and-play migration</figcaption>\n</div>\n<h4 id=\"-零样本跨任务技能迁移\">② Zero-sample cross-task skill transfer</h4>\n<p>The Critic and Recovery skills learned through evolution on a single task are not islands of overfitting, but have strong physical versatility:</p>\n<ul>\n<li>In the alignment approach, drop re-grab and buffer placement skill stack evolved on RoboCasa’s <code class=\"language-plaintext highlighter-rouge\">PnP-Stove</code> (stove pick and place), when the zero sample is migrated to the sink (<code class=\"language-plaintext highlighter-rouge\">PnP-Sink</code>) task, the success rate jumps directly from 58% to <strong>82%</strong>; from 62% to <strong>80%</strong> when migrating to cabinets (<code class=\"language-plaintext highlighter-rouge\">PnP-Cabinet</code>); from 72% to when migrating to toasters (<code class=\"language-plaintext highlighter-rouge\">PnP-Toaster</code>) <strong>90%</strong>.</li>\n</ul>\n<h4 id=\"-z-infra-带来的工程效率质变\">③ Qualitative changes in engineering efficiency brought about by Z-Infra</h4>\n<ul>\n<li><strong>throughput increased by 20.6 times</strong>: By decoupling environment simulation nodes and model inference resource pools, Z-Infra increased the effective trajectory sampling throughput from 1.7 episodes/min to <strong>35.1 episodes/min</strong> under 64 concurrency, significantly ahead of the existing baseline. 7.7~12.8 times;</li>\n<li><strong>delay is significantly reduced by 91%</strong>: The end-to-end decision-making delay is reduced by 91% (up to 11.1 times faster), completely eliminating the delay shackles of large model Agents participating in physical real-time closed-loop from the engineering base.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-3\">4. Limitations</h3>\n<ol>\n<li><strong>relies on the resetability of the emulator or digital twin.</strong>: Offline autonomous evolution requires multiple in-place replays and patch verifications for failed random seeds. Currently, it performs most smoothly in simulation and high-precision digital twin environments with resettable characteristics. It is still risky to carry out independent trial and error in purely realistic physical scenarios with completely irreversible damage;</li>\n<li><strong>Search boundary for automatic synthesis of high-frequency critic code</strong>: When faced with highly nonlinear, non-rigid and extremely complex fluid or cloth operations, the automatically generated heuristic critic and recovery action space are difficult to exhaust all dynamic physical boundaries.</li>\n</ol>\n<hr/>\n<h2 id=\"show-harness\">5. Show-Harness (2026)</h2>\n<p>———Just a VLM Agent Can Play Robots</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.10522\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.10522</a> · <a href=\"https://showlab.github.io/Show-Harness\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-4\">Key takeaways</h3>\n<ul>\n<li><strong>proposed Embodied Harness’s “semantic action unit” interface</strong>: rewrite the robot control into a set of discrete, interpretable semantic symbols (<code class=\"language-plaintext highlighter-rouge\">MV_FWD</code> / <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> / <code class=\"language-plaintext highlighter-rouge\">GRASP</code>…), VLM only spits out one symbol at each step, and then the embodiment The dedicated interpreter deterministically completes a small segment of real motion - the semantics of <strong>are left to the model, and the metrics are left to the interpreter</strong>. The two sides are completely decoupled, and the model is therefore always responsible for fine-grained physical decisions.</li>\n<li><strong>The same interface feeds the computing power of both ends at the same time</strong>: Closed-source cutting-edge VLM can directly start the robot with zero samples (Cross-Task 89.0%); 2B open source small model can learn the same set of action vocabulary (86.0%) using rank-64 LoRA and single card H200 within two hours of fine-tuning. The key lies in the semantic action prediction based on the VLM native vocabulary. <strong>does not add action headers and does not add special token</strong>.</li>\n<li><strong>“Symbol + Increment” brings no-retraining adaptability</strong>: When changing the accuracy, only the interpreter step size is changed (2 cm→1 cm, ZS 60%→80%), when changing the robot, only the interpreter is changed, and the unseen 90° rotation relies on extrapolation of 15° unit combinations repeated 6 times (70% vs $\\pi_{0.5}$’s 20%), the model parameters remain unchanged throughout the process.</li>\n<li><strong>reveals that the real source of interface effectiveness is “plain text convention” rather than symbol name</strong>: 2×2 ablation shows that arbitrary symbols A–F are paired with direction conventions and still 95%, while only giving symbols without conventions plummets to 5%; the direction mapping inferred by the model’s own trial is only 23.3% correct (16.7% random), and the left and right directions on the confusion matrix mirror each other in large areas.</li>\n<li><strong>GUMI: A data acquisition interface that exposes action words lists as web page buttons</strong>: Human keyboard, computer-use agent clicks on the same web page, and universal VLM directly predicts symbols. The three share the same action space; no dedicated remote operation hardware is required, and one demonstration can train semantic action strategies and continuous control strategies at the same time, and naturally supports cross-embodiment reuse and human-computer hybrid acquisition.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-4\">1. Background and problem</h3>\n<p>The basic VLM has actually installed most of the knowledge required for robot operation (recognizing objects, judging spatial relationships, and dismantling long-horizon targets), but this knowledge does not fall on the joints. The existing two paths have their own costs: VLA fine-tunes VLM into a continuous action regressor, and the semantics are compressed into an uninterpretable “pixel → driver” mapping. When changing tasks, environments, or embodiments, data must be collected again; hierarchical/skill library-based agents allow VLM to only issue sub-goals or adjust skills, and the physical implementation is left to the downstream controller. The model “says it but does not see how to do it”, and each intermediate representation is tied to a carefully engineered grounding pipeline.</p>\n<p>The author’s judgment is: what is missing is not model capacity, but a <strong>It is both friendly to VLM semantics and detailed enough to directly control the physical action space.</strong> .</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-4\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Show-Harness uses a set of semantic action interfaces to connect cutting-edge VLM to different robot embodiments: the model only outputs symbols such as MV_RIGHT, and the action interpreter is responsible for safety boundaries and step sizes, and then translates them into respective underlying instructions.</a>\n<figcaption>Show-Harness uses a set of semantic action interfaces to connect the cutting-edge VLM to different robot embodiments: the model only outputs symbols such as MV_RIGHT, and the action interpreter is responsible for the safety boundary and step size, and then translates them into the underlying instructions of the respective embodiments</figcaption>\n</div>\n<h4 id=\"-整体框架概述-3\">① Overview of the overall framework</h4>\n<p>Show-Harness consists of three parts: <strong>semantic action interface</strong> (action vocabulary faced by the model \\(\\mathcal A\\)), <strong>embodiment interpreter</strong> (deterministically translate symbols into robot motion), <strong>Embodied Harness Plug-in loop</strong> (organizes perception-reasoning-action into a configurable closed-loop). In addition, it is equipped with <strong>GUMI</strong> - a data collection interface that exposes the same set of action words as web buttons. One sentence summarizes the data flow: multi-view images and embodiment states are first organized into context by the perception plug-in. The reasoning plug-in splits the task into visually verifiable sub-tasks and determines the step size for this step. Based on this, VLM spits out <strong>and a</strong> semantic action unit. The interpreter converts it into a small displacement, and the execution results are reflowed into the next observation.</p>\n<h4 id=\"-语义动作接口模型只需要认-11-个符号\">② Semantic action interface: The model only needs to recognize 11 symbols</h4>\n<p>The action word list \\(\\mathcal A\\) is a compact set of semantic units:</p>\n<ul>\n<li><strong>translates</strong>: <code class=\"language-plaintext highlighter-rouge\">MV_FWD</code> / <code class=\"language-plaintext highlighter-rouge\">MV_BACK</code>, <code class=\"language-plaintext highlighter-rouge\">MV_LEFT</code> / <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>, <code class=\"language-plaintext highlighter-rouge\">MV_UP</code> / <code class=\"language-plaintext highlighter-rouge\">MV_DOWN</code>, the direction is defined relative to the currently selected reference perspective;</li>\n<li><strong>rotates</strong>: <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> / <code class=\"language-plaintext highlighter-rouge\">ROTATE_CCW</code>, each with a rotating axis ($x$ / $y$ / $z$);</li>\n<li><strong>jaws and termination</strong>: <code class=\"language-plaintext highlighter-rouge\">GRASP</code>, <code class=\"language-plaintext highlighter-rouge\">RELEASE</code>, <code class=\"language-plaintext highlighter-rouge\">DONE</code>.</li>\n</ul>\n<p>The author deliberately designed this vocabulary list around three properties:</p>\n<ol>\n<li><strong>Incremental</strong> - Each unit only causes a small and local physical change. The advantage is that the model always “stands in the loop”: it can see the effect of its previous step from the next frame and rely on continuous fine-tuning to approach accuracy, rather than planning an entire trajectory in one go.</li>\n<li><strong>is interpretable and embodiment-agnostic</strong> - the actions are symbols rather than numerical targets, the underlying control related to the embodiment is pushed to the downstream interpreter, and the space faced by the model is therefore fully reusable between different robots.</li>\n<li><strong>Vision can be anchored</strong> - the direction is defined relative to the observable perspective, and spatial reasoning can be directly mapped to action selection.</li>\n</ol>\n<h4 id=\"-本体解释器符号如何变成真实位移\">③ embodiment interpreter: how symbols become real displacements</h4>\n<p>Each decision \\(a_t \\in \\mathcal A\\) is handed over to the embodiment-specific interpreter \\(g_E\\), which maintains a 6-DoF Cartesian pose set point \\(s_t = (\\mathbf x_t, Q_t)\\) and updates it as follows:</p>\n\n\\[s_{t+1} = \\Pi_E\\big(\\mathbf x_t + \\sigma_t R_E d_a,\\ \\exp(\\theta_t [R_E r_a]_\\times)\\, Q_t\\big)\\]\n\n<p>Here, \\(d_a\\) and \\(r_a\\) respectively encode the translation direction and rotation axis (translation unit \\(r_a = 0\\), rotation unit \\(d_a = 0\\), and \\(r_a \\in \\{\\pm e_x, \\pm e_y, \\pm e_z\\}\\)); \\(\\sigma_t\\), \\(\\theta_t\\) It is the calibrated translation/rotation increment; \\(R_E\\) maps the semantic direction to the motion coordinate system of the embodiment $E$; \\([\\cdot]_\\times\\) is the antisymmetric matrix operator; the projection \\(\\Pi_E\\) enforces the workspace, desktop height and single-step amplitude limits, and out-of-bounds actions are blocked before execution. The gripper unit skips pose updates and is directly mapped to opening and closing commands.</p>\n<blockquote>\n<p><strong>gives an example (a complete landing process of MV_RIGHT)</strong>: VLM spits out <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>. The interpreter’s current set point position is \\(\\mathbf x_t = (0.40,\\ 0.00,\\ 0.25)\\) m. Look up the table and get \\(d_a = +e_y\\), \\(r_a = 0\\); Franka’s \\(R_E\\) maps “right relative to the reference perspective” to the base system \\(+y\\); the target has entered the wrist field of view, so use the fine step size \\(\\sigma_t = 0.02\\) m. The new position is \\((0.40,\\ 0.02,\\ 0.25)\\), and the posture does not move. \\(\\Pi_E\\) Check again: not out of the workspace and not lower than the desktop → Release. When he landed on the bottom floor, Franka used impedance control to follow the Cartesian set point, AgileX inverse kinematics + joint target flow, and the simulator issued an operating space command - the same <code class=\"language-plaintext highlighter-rouge\">MV_RIGHT</code>, which was “2 cm to the right” on the three systems. For a new robot, the only thing that needs to be written is this interpreter.</p>\n</blockquote>\n<h4 id=\"-和现有两条路线的差别\">④ Differences from the existing two routes</h4>\n<p>This step is the argument of the whole article, which can be best understood with a table:</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>VLA(π0.5 / GR00T)</th>\n<th>Layering/skill library agent</th>\n<th>Show-Harness</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>What does VLM output?</td>\n<td>Continuous Action Blocks (Regression/Diffusion/Flow Matching)</td>\n<td>Subtask description or skill invocation</td>\n<td>a semantic action unit</td>\n</tr>\n<tr>\n<td>Who is responsible for fine-grained physics decisions?</td>\n<td>Model, but suppressed into unexplainable perceptual→driven mapping</td>\n<td>Downstream controller or VLA, process invisible to model</td>\n<td>The model itself, and you can see the results at every step</td>\n</tr>\n<tr>\n<td>What should I change when replacing a robot?</td>\n<td>Re-collect data + re-fine-tune</td>\n<td>Rewrite skill library and grounding pipeline</td>\n<td>Just change an interpreter</td>\n</tr>\n<tr>\n<td>What should be changed to improve accuracy requirements?</td>\n<td>Supplement a batch of fine motor data for retraining</td>\n<td>Depends on underlying controller capabilities</td>\n<td>Interpreter step size changed from 2 cm to 1 cm</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-embodied-harness九个插件如何串成一步\">⑤ Embodied Harness: How nine plug-ins are strung together in one step</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Show-Harness architecture: three sections of configurable plug-ins, namely perception, reasoning and action, form a closed-loop around the central VLM. Pink is the reasoning flow, green is the action flow, and the dotted box is the optional plug-in enabled on demand.</a>\n<figcaption>Show-Harness architecture: three sections of configurable plug-ins: perception-reasoning-action form a closed-loop around the central VLM. Pink is the reasoning flow, green is the action flow, and the dotted box is the optional plug-in  that is enabled on demand.</figcaption>\n</div>\n<p>The perception and reasoning plug-in processes the original observation into a “refined context” \\(c_t = \\Phi_{\\mathcal P}(\\ell, o_t, h_t)\\) ($\\ell$ is a language command, $o_t$ is a multi-perspective observation, and $h_t$ is an interaction history), and VLM selects the action \\(a_t = \\pi(c_t)\\) on this context. The division of labor among the nine plug-ins is as follows:</p>\n<p><strong>Perception (Perception)</strong></p>\n<ul>\n<li><strong>Multi-View Guidance</strong>: Tells VLM how to use each camera - global first/third person perspective for scene-level context, wrist perspective for detailed evidence of close alignment.</li>\n<li><strong>Proprioception</strong>: Translate the internal state of the robot into short text, including the height of the gripper from the table, how far it will go in a single step, phased prompts (descend first if it is still too high), contact status and the opening and closing status of the gripper.</li>\n</ul>\n<p><strong>Reasoning</strong></p>\n<ul>\n<li><strong>Subtask Planning</strong>: First let VLM act as the planner to split the instructions into ordered subtasks. Each subtask has a <strong>available image to directly check the completion criterion of</strong>; during execution, each step will be compared with the current image to determine whether it has been achieved. If it is not achieved, it will continue to be done. If it is achieved, it will be announced to advance.</li>\n<li><strong>Situated Planning</strong> (default off): Suspend <strong>for the branch decision</strong> that currently lacks information, and come back to solve it after the relevant evidence becomes visible during execution. It is suitable for conditional tasks such as “Which of the three cups is the block hidden in?” to avoid planning all branches at the beginning.</li>\n<li><strong>Action Chunking</strong>: When the target is still far away and fine-grained feedback is not needed, VLM is allowed to spit out a small series of actions at a time for open-loop execution, reducing the frequency of model calls.</li>\n<li><strong>Adaptive Step</strong>: Use a 2 cm fine step when the target appears in the wrist field of view, otherwise use a 4 cm coarse step.</li>\n<li><strong>Visual Prompt</strong> (off by default): Use a dedicated model call to convert the linguistically difficult-to-define goal of “grasping the cup handle” into a visual mark on the image, and subsequent inferences are directly anchored to this mark.</li>\n</ul>\n<p><strong>Action (Action)</strong></p>\n<ul>\n<li><strong>Action History</strong>: Bring the last 5 actions into the next step context, and attach a usage tip “Don’t swing back and forth between opposite directions” to provide lightweight memory for stepping.</li>\n<li><strong>Failure Recovery</strong>: Automatically detect grasping, reset the gripper state and roll back to the corresponding grasping subtask to start again.</li>\n</ul>\n<p>The order of these plug-ins in one-step interaction is as follows:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"observation: multi-view images + embodiment state\"] --&gt; B[\"Perception: Multi-View Guidance Division of labor + Proprioception Literalization\"]\n    B --&gt; C[\"Subtask Planning: Compare the image to determine whether the current subtask has been achieved\"]\n    C --&gt; D[\"Adaptive Step: Target is within wrist view? Small steps 2cm / rough steps 4cm\"]\n    D --&gt; E[\"VLM Output a semantic action unit\"]\n    E --&gt; F[\"Action History: write recently 5 step, Suppress back and forth oscillation\"]\n    F --&gt; G[\"Interpreter: symbol -&gt; 6-DoF Pose set point increment\"]\n    G --&gt; H[\"safe projection: workspace / Desktop height / Single step range upper limit\"]\n    H --&gt; I[\"Robot execution, Environment and execution status updates\"]\n    I --&gt; J[\"Failure Recovery: Shortage detection -&gt; Roll back to grasping subtask\"]\n    J --&gt; A\n</code></pre>\n<h4 id=\"-同一个接口两种用法\">⑥ The same interface, two usages</h4>\n<p><strong>ZS mode (frontier VLM zero sample as agent)</strong>: The closed-source frontier model does not require any fine-tuning and controls the robot directly through the harness. The advantage is that as subsequent models become stronger, the robot’s capabilities will automatically increase accordingly.</p>\n<p><strong>FT mode (fine-tuned open source small model)</strong>: The same set of action words can also be used to train small models. Given the demo \\(\\mathcal D\\) collected with the same action space, the policy minimizes the token-level cross-entropy of the target unit:</p>\n\n\\[\\min_{\\theta}\\ \\mathcal L(\\theta) = -\\sum_{(\\ell, o, h, a) \\in \\mathcal D} \\log \\pi_\\theta\\big(a \\mid \\Phi_{\\mathcal P_{\\min}}(\\ell, o, h)\\big)\\]\n\n<p>The \\(\\mathcal P_{\\min}\\) here is deliberately trimmed to the thinnest context (leaving only instructions, multi-perspective observations and a small piece of action history) for the purpose of controlled comparison. The key is: <strong>semantic actions are</strong> predicted using VLM’s own native vocabulary. There are no additional action heads and no special tokens, so a rank-64 LoRA (freezing the visual encoder and multi-modal projection layer, only updating about 3% of parameters) is enough. Qwen3.5-2B can be trained on a single H200 in less than 2 hours, 24GB Level graphics cards can also run.</p>\n<h4 id=\"-gumi把动作词表变成一个网页\">⑦ GUMI: Turn the action vocabulary into a web page</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-GUMI-interface.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: GUMI interface: Each semantic action unit corresponds to a button with a key. People can use the keyboard to \"play\" the robot, and the computer-use agent can also directly operate the same web page. Each arm has a set of keys and supports action queuing and submission.</a>\n<figcaption>GUMI interface: Each semantic action unit corresponds to a button with a key. People can use the keyboard to \"play\" the robot, and the computer-use agent can also directly operate the same web page. Each arm has a set of keys and supports action queuing and submission</figcaption>\n</div>\n<p>Because the action space is discrete and can be directly manipulated by humans, the author conveniently made it into a graphical interface GUMI. Each unit is mapped to a button with a shortcut key: a human can control it with a keyboard, a computer-use agent can click on the same web page, and a general-purpose VLM agent can directly predict the symbols. Each step of GUMI records the pair of “pre-execution observation + selected semantic action” \\((o_t, a_t)\\), which is naturally a trainable sample; and because the implementation of the interpreter is deterministic, the same rollout can also leave underlying instructions and tracks incidentally - <strong>A demonstration can simultaneously train the semantic action strategy and the continuous control strategy</strong>.</p>\n<p>Compared with acquisition pipelines that rely on dedicated teleoperation hardware or simulation-specific control, GUMI does not require any special hardware and supports single-step control, action queuing, single-arm, and hybrid acquisition where humans intervene to correct during agent rollout; the same batch of demonstrations can be reused between different embodiments that implement the same set of units, and also supports remote acquisition (people do not have to stay with the robot).</p>\n<hr/>\n<h3 id=\"3-核心结果发现-4\">3. Results and findings</h3>\n<p><strong>Experimental setup</strong>: Two real robots - 7-DoF Franka Research 3 (one RealSense D435 external view facing the workbench + one wrist D405) and two-arm AgileX (two 6-DoF arms, one shared self-view + one per wrist, three Orbbec Dabai DC1 in total). The task is 5 objects (squares, bananas, tennis balls, teddy bears, chess pieces) × 2 containers (plates, bowls) = 10 catch-and-place tasks, each task has 10 random placement trials, and the upper limit of a single episode is 50 steps before the timeout fails. The FT mode demo only covers cubes, bananas, and tennis balls, leaving teddy bears and chess pieces as OOD. ZS uses Gemini-3.1 Pro by default (medium thinking effort), and FT uses Qwen3.5-2B by default. The demo has a total of 164 real robot episodes (7.8K decision steps) + 230 simulation episodes (13.5K steps, from ManiSkill and RoboLab).</p>\n<p>The three levels of generalization of <strong>are significantly ahead of</strong> (success rate, average):</p>\n<table>\n<thead>\n<tr>\n<th>generalization level</th>\n<th>π0.5</th>\n<th>GR00T</th>\n<th>Harness-VLA</th>\n<th>Goal-VLA</th>\n<th>CaP-X</th>\n<th>RATS</th>\n<th><strong>ZS</strong></th>\n<th><strong>FT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cross-Task (10 tasks)</td>\n<td>39.0</td>\n<td>35.0</td>\n<td>50.0</td>\n<td>13.0</td>\n<td>44.0</td>\n<td>57.0</td>\n<td><strong>89.0</strong></td>\n<td><strong>86.0</strong></td>\n</tr>\n<tr>\n<td>Cross-Environment</td>\n<td>40.0</td>\n<td>34.0</td>\n<td>63.8</td>\n<td>15.0</td>\n<td>52.5</td>\n<td>65.0</td>\n<td><strong>100.0</strong></td>\n<td><strong>88.0</strong></td>\n</tr>\n<tr>\n<td>Cross-Embodiment</td>\n<td>41.0</td>\n<td>36.0</td>\n<td>49.0</td>\n<td>11.0</td>\n<td>43.0</td>\n<td>52.0</td>\n<td><strong>93.0</strong></td>\n<td><strong>87.0</strong></td>\n</tr>\n</tbody>\n</table>\n<p>A few points worth mentioning separately: The advantage is also true for the teddy bears and chess pieces that <strong>has not appeared in the fine-tuning data</strong> (ZS is 10/10 on the chess piece task, π0.5 is only 1/10); <strong>sim-to-real</strong> In one item, FT, which only uses simulation demonstration training, gets 13/20, while π0.5 and GR00T, which also only feed simulation data, get 0/20; when <strong>crosses embodiment</strong>, ZS only needs to change an interpreter, and FT directly evaluates each after joint training on the data of both arms.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-capability-analysis.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Capability analysis: The upper four boxes are physical adaptability (fine control, rotation extrapolation, action combination, workspace offset), and the lower three boxes are multi-arm collaboration and semantic adaptability (reasoning-intensive tasks, video in-context learning)</a>\n<figcaption> Capability analysis: The upper four boxes are physical adaptability (fine control, rotation extrapolation, action combination, workspace offset), and the lower three boxes are multi-arm collaboration and semantic adaptability (inference-intensive tasks, video in-context learning)</figcaption>\n</div>\n<p><strong>Physical adaptability - change the interpreter instead of retraining the model</strong></p>\n<ul>\n<li><strong>Fine control</strong>: Block stacking and latch tasks, only adjusting the interpreter step size from 2 cm to 1 cm, without moving the interface and not retraining, ZS increased from 60% to 80%, FT increased from 40% to 65%; π0.5 trained with the same batch of demonstrations was only 15%, and an additional batch of fine motion data was required to reach 60%.</li>\n<li><strong>action combination</strong>: Synthesizing two orthogonal translation units into one diagonal displacement is only a matter of the interpreter - ZS has −26% steps per episode, FT −24%, and the success rate has only dropped slightly from 94%/84% to 92%/82%.</li>\n<li><strong>Rotation Extrapolation</strong>: See example below.</li>\n<li><strong>workspace offset</strong>: expanded from the core 25% area (S@1) to 90% close to the boundary (S@3), ZS 98%→92%, FT 88%→82% only declined slightly, and π0.5 collapsed from 48% to 24%.</li>\n<li><strong>Multi-arm collaboration</strong>: On both AgileX arms, the joint action prediction of “clearing the table” is 90% (0 collisions), while the two independent single-arm agents each manage only 70% (1 collision); the gap in “passing bananas” that requires handover is even greater - joint 70% (0 collisions) versus independent 30% (3 collisions).</li>\n</ul>\n<blockquote>\n<p><strong>as an example (rotation extrapolation)</strong>: Each <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> only rotates 15°. In the training demonstration, the carrot only swung through 0° and 45°, but during the test it swung to an unseen 90° - the model does not need to have “seen 90°”, as long as it vomits 6 <code class=\"language-plaintext highlighter-rouge\">ROTATE_CW</code> in a row, it will be in place. FT gets 70% at 90°, while the π0.5 of direct regression to continuous action is only 20%: the angle of the regression output is locked by the training distribution, while the incremental unit can be extrapolated by repeated combinations. By the way, if the rotation unit is removed from the vocabulary, the success rates at 45° and 90° drop to 50% and 10% respectively.</p>\n</blockquote>\n<p><strong>Semantic adaptability—preserving VLM’s instruction following flexibility</strong></p>\n<ul>\n<li><strong>Reasoning-intensive task</strong> (find out which of the three inverted cups hides the square, arrange the scattered letters to form “SHOW”): ZS opens Situated Planning and gets 85%, FT and π0.5 run alone only 10% and 0%; feed them the same subtask instructions generated by Gemini, FT rises to 70%, π0.5 still only has 5%.</li>\n<li><strong>video in-context learning</strong>: It is required to collect three objects in the order in the demonstration video. When there is no demonstration, ZS only gets 20% (the order is not clear in the first place). After giving a human or robot demonstration video, both sources are 20/20; FT gets 90% from both sources under the condition of the task outline extracted by the same planner.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-plugin-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Ablation of nine plug-ins (real robot Franka + Gemini-3.1 Pro zero sample): the default plug-in leaves one method behind, Visual Prompt and Situated Planning are superimposed on the default configuration and evaluated in special scenarios, the complete configuration baseline is 96%</a>\n<figcaption> Ablation of nine plug-ins (real robot Franka + Gemini-3.1 Pro zero sample): The default plug-in leaves one method behind, Visual Prompt and Situated Planning are superimposed on the default configuration and evaluated in special scenarios. The complete configuration baseline is 96%</figcaption>\n</div>\n<p><strong>plug-in ablation</strong> (complete configuration 96%):</p>\n<ul>\n<li><strong>Multi-View Guidance</strong>: Drops to 58% only for global view - wrist view is almost a necessity for fine alignment of small objects.</li>\n<li><strong>Proprioception</strong>: Removed and dropped to 68%. Compact signals such as gripper height and contact status provide reliable guidance when appearance or depth makes visual judgment slip.</li>\n<li><strong>Subtask Planning</strong>: Removed and dropped to 60%. A typical failure is <strong>dragging the object toward the plate without lifting it</strong> - this problem disappears only after the operation sequence is broken into stages that are locally valid and can be verified by images.</li>\n<li><strong>Action Chunking</strong>: Turning it off is still 96% but requires 32 model calls; forcing chunk throughout the process reduces the calls to 20 times (-38%) but drops to 74%. Conclusion supports <strong>selective chunk</strong>: compresses redundant handling segments and retains fine-grained feedback before and after contact.</li>\n<li><strong>Adaptive Step</strong>: Only 82% of fine steps are used (38 steps, easy to overshoot), only 70% of coarse steps are used (22 steps, easy to overshoot), and 96% of adaptive switching is based on target visibility (30 steps).</li>\n<li><strong>Visual Prompt</strong>: Basically ineffective in regular tasks (96% vs 94%), support it to be turned off by default; but in “grasping the cup handle” it improved from 40% to 85%. Note that just drawing the mark without language alignment is 35% - <strong>The gain comes from explicitly aligning the language instructions with the marked interaction points, not the mark itself</strong>.</li>\n<li><strong>Situated Planning</strong>: Zero impact on regular tasks, hidden object search increased from 35% to 85%.</li>\n<li><strong>Action History</strong>: After removal, it dropped to 76%, and the number of steps increased from 30 to 39. Most of the failures were oscillations between opposite actions.</li>\n<li><strong>Failure Recovery</strong>: Removed and dropped to 72%. The main failure mode is undetected empty gripping, and then the empty gripper is used to continue through the rest of the process.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-action-space-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: 2×2 ablation of action space representation: the horizontal axis is whether there is an explicit agreement, and the vertical axis is semantic name or arbitrary symbol; the right side is the direction mapping confusion matrix detected by the model under setting (D), with a large area mirrored in the left and right directions</a>\n2×2 ablation of<figcaption> action space representation: the horizontal axis is whether there is a clear text agreement, the vertical axis is the semantic name or an arbitrary symbol; the right side is the direction mapping confusion matrix detected by the model under setting (D), with a large area mirrored in the left and right directions</figcaption>\n</div>\n<p><strong>The most interesting group of ablation - what exactly does the action symbol rely on grounding</strong>. The author fixed the rest of the harness unchanged and only changed the representation of the six translation units to do a 2×2 comparison:</p>\n<table>\n<thead>\n<tr>\n<th> </th>\n<th>There is an express agreement</th>\n<th>No express agreement</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>semantic name</strong> (<code class=\"language-plaintext highlighter-rouge\">MV_LEFT</code>…)</td>\n<td>(A) <strong>100%</strong>, 25 steps</td>\n<td>(B) 90%, 34 steps</td>\n</tr>\n<tr>\n<td><strong>Any symbol</strong> (A–F)</td>\n<td>(C) <strong>95%</strong>, 27 steps</td>\n<td>(D) <strong>5%</strong>, 49 steps</td>\n</tr>\n</tbody>\n</table>\n<p>The reading is: <strong>The convention provides most of the grounding, and the semantic name is just a useful prior</strong>. Any symbol is paired with a clear description of “where this symbol will move the end” (C), which is almost the same as the default configuration; conversely, only semantic names are given without conventions (B), although it can still be used, but the efficiency is significantly reduced. In setting (D), the model can only test it by itself - spitting out an unknown symbol, comparing observations before and after, and guessing its effect - only 1 episode was successful out of 20 episodes, and the inferred mapping was only 23.3% correct (randomly 16.7%), and the left and right directions on the confusion matrix mirrored each other in large areas. <strong>It is unreliable to rely solely on visual changes to deduce action semantics. Writing the agreement into prompt is the key.</strong></p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-backbone-thinking-effort.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Left: The distribution of different cutting-edge VLM and thinking effort on the success rate-number of steps plane; Right: The ability to place chess cannons is divided into two stages: planning and fine-grained alignment. The bottleneck is obviously in the latter.</a>\n<figcaption> Left: The distribution of different frontier VLM and thinking effort on the success rate-number of steps plane; Right: In the chess cannon placement task, the ability is divided into planning and fine-grained alignment. The bottleneck is obviously in the latter</figcaption>\n</div>\n<p><strong>backbone model and thinking budget</strong>: Zero-sample performance generally follows the capabilities of the underlying model (Gemini-3.1 Pro &gt; GPT-5.6-sol &gt; Opus 5 &gt; GPT-5.6-luna &gt; Gemini-3.6 Flash). To improve thinking effort, <strong>mainly reduces the number of redundant interaction steps</strong>. The improvement in success rate is limited, but the wall clock time increases significantly (GPT-5.6-sol reaches 3.4×). The command following of all models is very stable, and more than 98% of the responses can produce legal action units. Taking the chess cannon placement task apart, <strong>planning is not the bottleneck of</strong> (the plan correct of the three models are all 80–95%). The errors are concentrated in fine grasping and placement (place correct is only 70/30/15); additionally given the target bounding box, it can be mentioned further, indicating that explicit visual grounding clues are of great value.</p>\n<p><strong>Fine-tuning backbone scale</strong>: 2B is already very strong, and the larger backbone mainly has gains in fine tasks such as stacking and latching; the 1B-level model will do too many local fine-tuning near the target, resulting in a significantly longer set length; but the small model can outperform the large model in tasks such as tennis that require timely correction of moving objects. Overall 2B is a balance between accuracy and responsiveness.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/Show-Harness-qualitative-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Qualitative results of real robot: new objects, background changes, lighting changes, cluttered scenes, spatial reasoning (putting letters to spell \"SHOW\") and double-arm coordination (opening drawers and putting cups in) are all completed by the same set of action interfaces</a>\n<figcaption> real robot qualitative results: new objects, background changes, lighting changes, cluttered scenes, spatial reasoning (putting letters to spell \"SHOW\") and arm coordination (opening drawers and placing cups) are all completed by the same set of action interfaces</figcaption>\n</div>\n<hr/>\n<h3 id=\"4-局限性-4\">4. Limitations</h3>\n<ol>\n<li><strong>embodiment has limited coverage</strong>: Currently, it has only been verified on single-arm (Franka) and double-arm (AgileX) operations equipped with parallel grippers. It is still unknown to extend it to embodiments with higher degrees of freedom and more complex contact patterns such as dexterous hands and humanoids;</li>\n<li><strong>Single sensing mode</strong>: The sensing side only has vision and embodiment states, lacks tactile and force feedback, and is still short of fine physical interactions that require intensive contact and compliant control.</li>\n</ol>\n<hr/>\n<h2 id=\"space\">6. SPACE (2026)</h2>\n<p>———Learn from programmed skills when to act continuously and when to stop and observe</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.02042\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.02042</a></p>\n<hr/>\n<h3 id=\"精华-5\">Key takeaways</h3>\n<ul>\n<li>The key to <strong>action blocks is boundaries</strong>: Outputting multiple actions at once can reduce large model calls, but the strategy also needs to learn which actions can be executed continuously, and when it should stop to obtain new observations.</li>\n<li><strong>uses skill structure to provide supervision</strong>: SPACE summarizes compound skills and sub-skills from success trajectories, converts sub-skill call boundaries into action block boundaries, and supplements the time structure that terminal rewards are difficult to provide directly.</li>\n<li><strong>has skills during training and takes direct action during deployment</strong>: Skill calls are expanded into ordinary action block samples and trained together with data independently sampled by the strategy. The final strategy does not need to access the skill library.</li>\n<li><strong>Simultaneously compares the entire trajectory with the local state</strong>: The trajectory-level advantage measures the final result, and the block-aware step-level advantage compares the returns discounted by decision round under the same anchor point observation, so that the learning signal takes into account both success and decision-making efficiency.</li>\n<li><strong>The benefits have a clear experimental scope</strong>: In the text interaction settings of ALFWorld and ScienceWorld, SPACE improves 7.0–31.3 percentage points compared with the baseline with the highest success rate in each setting, and reduces LLM decision rounds.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-5\">1. Background and problem</h3>\n<p>ReAct-style agents usually only generate one atomic action per round, read environmental feedback after execution, and then call a large model to determine the next step; deterministic routines in long-term tasks therefore require multiple model calls. Directly changing to output a variable-length action sequence at once, and then using standard reinforcement learning training may not necessarily lead to good learning: the paper observed phenomena such as single action collapse, excessively long action blocks leading to a decrease in success rate, and multi-action PPO training being unstable. The authors attribute the core difficulty to action block boundary learning—sparse terminal rewards lack supervision that directly signals “this is the time to pause and re-observe.”</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-multiaction-failure-modes.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Single-action collapse and over-commitment phenomenon of multi-action GRPO\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> allows the output of multiple actions and does not guarantee effective chunking; different backbone models exhibit single-action collapse and over-commitment respectively</figcaption>\n</div>\n<hr/>\n<h3 id=\"2-主要方法创新点-5\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: SPACE skill induction, hybrid sampling, joint training and deployment process\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> Successfully generated programmed skills from trajectories. Skill calls were expanded into original action blocks and trained together with directly sampled action blocks; only the action block strategy was retained during testing</figcaption>\n</div>\n<p>SPACE (Skill-guided Policy with Adaptive Chunk Execution) consists of two layers of programmed skills <strong>, hybrid trajectory sampling and skill expansion, and block-aware policy optimization</strong>. Skills provide reusable task decomposition, the expansion process converts the decomposition into training samples, and joint optimization absorbs this structure into a strategy that directly outputs action blocks.</p>\n<h4 id=\"-动作块接口减少决策次数保留必要的反馈边界\">① Action block interface: Reduce the number of decisions and retain necessary feedback boundaries</h4>\n<p>First write several actions at a time, and then execute them sequentially by the executor. This is action chunking (Action Chunking). The strategy generates $u_i=(a_{i,1},\\dots,a_{i,L_i})$ based on the interaction history $h_i$ of the $i$ round, where $1\\leq L_i\\leq K$; the executor stops execution when the block is completed or encounters an invalid action, and then enters the next LLM decision, experimental setting $K=6$.</p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>single action strategy</th>\n<th>Simple multi-action RL</th>\n<th>SPACE</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Output per round</td>\n<td>an atomic action</td>\n<td>Variable length atomic action sequence</td>\n<td>Variable length atomic action sequence</td>\n</tr>\n<tr>\n<td>How to determine boundaries</td>\n<td>Fixed segmentation after each action</td>\n<td>Mainly relies on task reward learning</td>\n<td>Demonstration of adding sub-skill boundary formation</td>\n</tr>\n<tr>\n<td>training data</td>\n<td>Atomic motion trajectory</td>\n<td>Autonomously generated action block trajectories</td>\n<td>Autonomous action blocks and skill expansion action blocks</td>\n</tr>\n<tr>\n<td>test interface</td>\n<td>single action</td>\n<td>action block</td>\n<td>Action block, no skill call</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Take an example (mechanism diagram)</strong>: If the location of the refrigerator is known, you can first output “walk to the refrigerator and open the refrigerator”, wait for feedback to confirm what objects are inside, and then decide which object to take. If objects that have not yet been confirmed to exist are also written into the same block in advance, it may fail due to lack of mid-way feedback; it is this kind of trade-off that boundary learning aims to solve.</p>\n</blockquote>\n<h4 id=\"-两层程序化技能把成功经验变成可切分的例程\">② Two levels of procedural skills: turning successful experiences into divisible routines</h4>\n<p><strong>input</strong> is the trajectory of successful interaction. The large model divides it into sub-task stages, generating a composite skill responsible for scheduling, and several sub-skills (Subskills) that complete local routines; each sub-skill contains behavior descriptions, parameter modes and executable functions, and the composite skill also records an ordered sequence of sub-skill calls. The generated code is checked for syntax, compilability and function signature, and then standardized and deduplicated according to the Abstract Syntax Tree (AST). <strong>output</strong> to the skill library.</p>\n<p>The two-layer structure provides a specific basis for segmentation: the composite skill is responsible for the sequence of “find the object first, then heat it, then place it”. Each sub-skill call corresponds to an action block, and block boundaries are formed between calls. These bounds are training demonstrations taken from the program structure and do not imply that they have been proven to be optimal bounds for all states.</p>\n<p><strong>Cold start and update</strong>: Appendix A.2 clearly uses the initial skills of manual sorting, 3 for ALFWorld and 5 for ScienceWorld, and serves as a few sample examples for subsequent skill induction. The search prioritizes the matching task category, and selects the top 3 composite skills based on the UCB-style score that combines the success rate and the number of uses; when there is no corresponding category, 7 sub-skills that are as diverse as possible are retrieved based on the description semantic similarity. During training, skills are regularly summarized from new success trajectories, with a maximum of 20 composite skills for each type, and entries with zero long-term success rate are cleared.</p>\n<h4 id=\"-混合采样与技能展开把代码调用转换为部署接口\">③ Mixed sampling and skill expansion: convert code calls into deployment interfaces</h4>\n<p>The training is based on <strong>track</strong> mixed two modes. The trajectory of proportion $\\rho_{\\mathrm{prim}}$ adopts Primitive-Chunk Mode, and the strategy directly outputs action chunks to form the same strategy data $\\mathcal D_{\\mathrm{on}}$; the remaining trajectories adopt Skill-Augmented Mode, and the strategy receives the retrieved skills and can output original action chunks or call skills.</p>\n<p>In order for the deployment strategy to output only atomic action sequences, skill enhancement trajectories are expanded via Skill-to-Chunk Expansion:</p>\n<ul>\n<li>Already the output of the original action block, leave it as is.</li>\n<li>Calling a sub-skill is converted into a set of “current history, action blocks output by this sub-skill”.</li>\n<li>Call a compound skill and expand it into multiple groups of samples along the order of its sub-skill calls; the history of the latter sample contains the feedback after the execution of the previous action block.</li>\n</ul>\n<blockquote>\n<p><strong>Take an example (only demonstrates segmentation)</strong>: A composite skill call executes 3 sub-skills in sequence, which produce 2, 3, and 2 atomic actions respectively. After expansion, three action block samples with lengths 2, 3, and 2 are obtained. Each sample is matched with the history at the corresponding boundary; these 7 actions will not be merged into one block. The policy thus learns both the action content and the block end position.</p>\n</blockquote>\n<p>These expanded samples form hetero-strategy data $\\mathcal D_{\\mathrm{off}}$. The “different strategies” here refer to samples that have been executed and rewritten by skills, rather than raw data directly collected by the deployment strategy through the same interface; they are continuously generated during the training process and do not necessarily come from a fixed pre-collected data set.</p>\n<p>The default original action block sampling ratio is 0.5 in ALFWorld and 0.75 in ScienceWorld; the 8 tracks per task in the former can be divided into 4 direct sampling and 4 skill-enhanced sampling, while the latter is 6 and 2. The two-way samples are finally aligned to the same interface, so the trained policy does not need to retrieve skills or execute skill functions.</p>\n<h4 id=\"-块感知信用分配整条轨迹与相同状态分别比较\">④ Block-aware credit allocation: compare the entire trajectory with the same state separately</h4>\n<p>To judge whether an action deserves to be learned more or less, SPACE simultaneously looks at “what is the result of the entire trajectory” and “how is the subsequent performance under the same observation”, that is, Chunk-Aware Two-Level Advantages. Let $M_\\tau$ be the number of decision rounds in the unified action block representation, $r(\\tau)$ be the terminal reward, the sampling group with the same task and initial conditions is recorded as $\\mathcal G$, and the trajectory-level advantage is:</p>\n\n\\[A_{\\tau}^{\\mathrm{traj}}=\\frac{r(\\tau)-\\mu_{\\mathcal G}}{\\sigma_{\\mathcal G}+\\epsilon}.\\]\n\n<p>For the $i$ action block, first calculate the reward of <strong>discount according to</strong> remaining decision round, and then broadcast it to each action in the block:</p>\n\n\\[G_{\\tau,i}=\\gamma_c^{M_\\tau-i}r(\\tau).\\]\n\n<p>Then take the anchor state key $z_{\\tau,i,j}$ observed before the action is executed, form a set $H(z)$ of action occurrence positions sharing the same anchor point, and normalize it by the return mean and standard deviation of the set:</p>\n\n\\[A_{\\tau,i,j}^{\\mathrm{step}}=\n\\frac{G_{\\tau,i}-\\mu_{H(z_{\\tau,i,j})}}\n{\\sigma_{H(z_{\\tau,i,j})}+\\epsilon},\n\\qquad\nA_{\\tau,i,j}=A_{\\tau}^{\\mathrm{traj}}+\\lambda_{\\mathrm{step}}A_{\\tau,i,j}^{\\mathrm{step}}.\\]\n\n<blockquote>\n<p>Take <strong>as an example (set your own value and ignore the stable term)</strong>: Two successful trajectories take one action at the same anchor point, and the terminal rewards are both 1, but then 1 and 3 rounds of decision-making are required respectively; taking $\\gamma_c=0.9$, the corresponding rewards are 0.9 and 0.729. If the anchor point group only has these two samples, calculated based on the overall standard deviation, the mean is 0.8145, the standard deviation is 0.0855, and the step advantages are +1 and −1 respectively. This local signal biases paths with fewer subsequent decisions; the raw rewards of actions within the same block are the same, but the final advantage can still be different if the anchor comparison group is different.</p>\n</blockquote>\n<p>This is a method of assigning credit based on relative returns within a group, and one cannot claim that it accurately identifies the causal contribution of each action. The problem statement in the article uses success/failure terminal rewards, while the actual training in ScienceWorld uses scaled task scores according to Appendix A.2, and cuts negative values ​​to 0. Abstract settings and specific implementations should be distinguished.</p>\n<h4 id=\"-联合训练目标与推理流程\">⑤ Joint training goals and inference process</h4>\n<p>The original action block trajectory uses PPO-style clipping targets. Let $p_\\theta(a_{\\tau,i,j})$ abbreviated strategy generate the probability of this action under the conditions of history $h_i$ and previous actions in the block, $q_{\\tau,i,j}=p_\\theta(a_{\\tau,i,j})/p_{\\mathrm{old}}(a_{\\tau,i,j})$ is the probability ratio of the old and new strategies, then:</p>\n\n\\[\\mathcal L_{\\mathrm{on}}=-\\mathbb E_{\\tau\\sim\\mathcal D_{\\mathrm{on}}}\n\\left[\\sum_{i=1}^{M_\\tau}\\sum_{j=1}^{\\ell_i}\n\\min\\left(q_{\\tau,i,j}A_{\\tau,i,j},\n\\operatorname{clip}(q_{\\tau,i,j},1-\\varepsilon,1+\\varepsilon)A_{\\tau,i,j}\\right)\\right].\\]\n\n<p>This term increases the probability of favorable actions while limiting the scope of strategy updates; consistent with the original presentation, the KL regular term is omitted here. The skill expansion data uses advantage-weighted self-imitation targets:</p>\n\n\\[\\mathcal L_{\\mathrm{off}}=-\\mathbb E_{\\tau\\sim\\mathcal D_{\\mathrm{off}}}\n\\left[\\sum_{i=1}^{M_\\tau}\\sum_{j=1}^{\\ell_i}\nw(A_{\\tau,i,j})\\log p_\\theta(a_{\\tau,i,j})\\right],\n\\qquad w(A)=\\operatorname{clip}(A,0,w_{\\max}).\\]\n\n<p>This item retains the imitation weights of positive dominant samples and limits excessive weights, distilling the action blocks and their boundaries obtained by skill expansion into the strategy. The overall goal is:</p>\n\n\\[\\mathcal L(\\theta)=\\mathcal L_{\\mathrm{on}}(\\theta)+\\lambda_{\\mathrm{off}}\\mathcal L_{\\mathrm{off}}(\\theta).\\]\n\n<p>When implemented, the advantage of each atomic action is broadcast to the output token corresponding to that action. By default, 16 tasks are sampled per training step, 8 trajectories per task, the learning rate is $10^{-6}$, the history length is 5, and both backbone models run in no-thinking mode.</p>\n<p>The end-to-end process is: hybrid sampling → unfold skill trajectories → calculate two-level advantages → joint update strategy → regularly update the skill library from successful trajectories. During testing, the loop is directly in the manner of “interaction history → variable-length action block → sequential execution → new feedback”. LLM is not re-invoked in the middle of the block; the skill library and its retrieval and execution components no longer participate in reasoning.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-5\">3. Results and findings</h3>\n<p><strong>Main results (Table 1, Table 2)</strong> : SR is the success rate, and round is the average number of LLM decisions per episode. Select each setting uniformly in the table below <strong>Baseline with the highest success rate</strong> Compare and avoid piecing together the success rates of different baselines with the lowest rounds.</p>\n<table>\n<thead>\n<tr>\n<th>Environment / Backbone / Partition</th>\n<th>compare baseline</th>\n<th>Baseline SR → SPACE SR</th>\n<th>Gain (percentage points)</th>\n<th>Baseline round → SPACE round</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ALFWorld / Qwen3-4B / Seen</td>\n<td>GiGPO (SR alongside Multi-action GRPO)</td>\n<td>85.2% → 99.2%</td>\n<td>+14.0</td>\n<td>15.9 → 3.7</td>\n</tr>\n<tr>\n<td>ALFWorld / Qwen3-4B / Unseen</td>\n<td>Multi-action GRPO</td>\n<td>81.3% → 96.9%</td>\n<td>+15.6</td>\n<td>20.9 → 4.4</td>\n</tr>\n<tr>\n<td>ALFWorld / Llama-3.1-8B-Instruct / Seen</td>\n<td>GiGPO</td>\n<td>89.1% → 96.1%</td>\n<td>+7.0</td>\n<td>14.5 → 5.0</td>\n</tr>\n<tr>\n<td>ALFWorld / Llama-3.1-8B-Instruct / Unseen</td>\n<td>GiGPO</td>\n<td>83.6% → 94.5%</td>\n<td>+10.9</td>\n<td>18.8 → 5.2</td>\n</tr>\n<tr>\n<td>ScienceWorld / Llama-3.1-8B-Instruct / Seen</td>\n<td>GiGPO</td>\n<td>35.9% → 67.2%</td>\n<td>+31.3</td>\n<td>10.2 → 5.2</td>\n</tr>\n<tr>\n<td>ScienceWorld / Llama-3.1-8B-Instruct / Unseen</td>\n<td>GiGPO</td>\n<td>34.4% → 61.7%</td>\n<td>+27.3</td>\n<td>10.1 → 5.8</td>\n</tr>\n</tbody>\n</table>\n<p>For example, Qwen3-4B’s ALFWorld Unseen decision rounds are reduced by approximately <strong>78.9%</strong>. In comparison, Llama’s Multi-action GRPO itself only requires 5.4/5.5 rounds, and SPACE is 5.0/5.2 rounds. The main advantage is that the success rate is increased from 71.1%/65.6% to 96.1%/94.5%; it cannot be generalized to all multi-action baselines as a 70% reduction in rounds.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-training-dynamics.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Training curves of SPACE and multi-action reinforcement learning baselines\" loading=\"lazy\" decoding=\"async</a>\n<figcaption>Qwen3-4B’s ALFWorld Unseen success rate curve, the number of actions per round of the two backbones, and the change in strategy entropy; in the later stages of SPACE, 3–4 actions per round were roughly maintained</figcaption>\n</div>\n<p><strong>Action Block Behavior</strong>: Qwen3-4B’s Multi-action GRPO is close to one action per round, and Llama-3.1-8B-Instruct tends to about 5–6 actions per round but with a lower success rate. SPACE resulted in an intermediate granularity of about 3–4 actions in these experiments while maintaining a higher success rate; this range is an experimental observation and cannot be relied upon as a universal optimal block length.</p>\n<p><strong>component ablation (Table 3, ALFWorld/Llama-3.1-8B-Instruct)</strong>:</p>\n<table>\n<thead>\n<tr>\n<th>training configuration</th>\n<th>Seen SR / round</th>\n<th>Unseen SR / round</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Complete SPACE</td>\n<td>96.1% / 5.0</td>\n<td>94.5% / 5.2</td>\n</tr>\n<tr>\n<td>Remove skills</td>\n<td>86.7% / 5.8</td>\n<td>88.3% / 5.7</td>\n</tr>\n<tr>\n<td>Remove block-aware advantages</td>\n<td>90.6% / 5.6</td>\n<td>89.1% / 7.0</td>\n</tr>\n</tbody>\n</table>\n<p>Removing either component reduces the success rate and increases the number of decision rounds, supporting the complementary role of skill-bound supervision and block-aware optimization.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/SPACE-rollout-efficiency.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The impact of the total amount of training sampling decisions and the sampling ratio of the original action block\" loading=\"lazy\" decoding=\"async</a>\n<figcaption> The left picture counts ALFWorld’s training sampling LLM rounds, not the number of tokens; the right picture compares ScienceWorld’s original action block sampling ratio, the decision round of 0.75 is the lowest, and the success rate of 0.875 is higher</figcaption>\n</div>\n<p><strong>efficiency indicators need to differentiate between calibers</strong>: In Figure 3(a), SPACE reaches the final performance of Multi-action GRPO at the 40th training step, corresponding to about 26.6% of the training steps stated in the paper overview; Figure 4(a) counts <strong>sampling LLM in another backbone setting In round</strong>, it takes 43.60K times for SPACE to achieve GRPO performance, and the entire GRPO process is 564.54K times, which is about 7.72% (a reduction of 92.28%). The entire SPACE process is 104.46K times; these values ​​cannot be directly regarded as total tokens, GPU time or end-to-end training costs.</p>\n<p>Trade-off of <strong>sampling ratio</strong>: In Figure 4(b), $\\rho_{\\mathrm{prim}}=0.75$ corresponds to a success rate of 64.5% and 5.51 rounds; 0.875 corresponds to 66.4% and 6.84 rounds. The author chose 0.75 as a compromise between success rate and efficiency. However, the statement in the text that “the success rate is also higher” is inconsistent with the value in the figure. Here, the illustration is based on the data shown in the figure.</p>\n<p><strong>Search during test (Table 4)</strong>: On the difficult validation subset of ScienceWorld, the Best-of-N search takes $N=8$, the GRPO success rate increases from 33.3% to 37.5% (+4.2 percentage points), and SPACE increases from 52.1% to 60.4% (+8.3 percentage points); the average LLM calls after adding search were 74.9 and 48.3 respectively. Single action candidates use 3-step environment look-ahead scoring, and action block candidates use complete block execution scoring. Therefore, this result depends on the evaluation conditions that enable candidate environment look-ahead, and it does not mean that the two environment simulation costs are the same.</p>\n<hr/>\n<h3 id=\"4-局限性-5\">4. Limitations</h3>\n<ol>\n<li><strong>is only verified in the text interactive environment</strong>: The experiment only covers the text settings of ALFWorld and ScienceWorld. ScienceWorld also excludes tasks with optimal solutions exceeding 100 environmental steps. Visual input, continuous control and real robots scenarios have not been verified;</li>\n<li><strong>relies on manual cold start skills and skill induction process</strong>: The method requires manual cold start skills, and continues to summarize and execute skills during training; the main efficiency indicator of the paper is the LLM decision round, and the end-to-end training acceleration including these additional processes cannot be directly inferred based on this.</li>\n</ol>\n<hr/>\n<h2 id=\"abot-agentos\">7. ABot-AgentOS (2026)</h2>\n<p>——Universal robot Agent operating system and lifelong multi-modal memory system for embodied intelligence</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2607.10350\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2607.10350</a> · <a href=\"https://amap-cvlab.github.io/ABot-AgentOS\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<hr/>\n<h3 id=\"精华-6\">Key takeaways</h3>\n<ol>\n<li><strong>Modular layered decoupling architecture</strong>: ABot-AgentOS is deployed between the underlying robot controller and the high-level basic VLM/VLA model, decoupling high-level semantic reasoning, skill execution, multi-level verification and memory retrieval, solving the problems of lack of explicit termination signals and process drift in traditional single-model controllers.</li>\n<li><strong>Agent Harness control closed-loop</strong>: Propose a “reasoning-execution-verification” closed-loop that includes global Main LLM planning, Skill Runner context-isolated local execution, and Verifier run-time/skill-time/end-time multi-stage verification, which significantly reduces false completion and blind stagnation in long-term tasks.</li>\n<li><strong>Universal Multi-modal Graph Memory</strong>: Converts speech, image observation, spatial location, time association and task trajectory into strongly typed multi-modal graph nodes and edges, supporting retrieval and local subgraph extraction based on evidence traceability.</li>\n<li><strong>Failure-Driven Lifelong Self-Evolution (Failure-Driven Lifelong Self-Evolution)</strong>: Build a fail-to-JSON DSL asset mechanism based on Trace diagnosis, adopt strict post-check gating, and achieve cumulative self-evolution with zero ground-truth leakage in cross-Split deployment.</li>\n<li><strong>Embodied WorldBench</strong>: Launches the first executable evaluation benchmark across indoor and outdoor composite scenes, covering 16 scenes, 4 difficulty levels and 200+ composite tasks; and provides an end-to-end student policy distillation training pipeline based on text sandbox and self-evolution reward engine.</li>\n</ol>\n<hr/>\n<h3 id=\"1-研究背景问题-6\">1. Background and problem</h3>\n<p>Embodied AI (Embodied AI) is pushing artificial intelligence from the digital world to the physical world. In recent years, the visual language model (VLM) and the visual language action (VLA) model have given robots excellent natural language understanding, visual scene perception and action prediction capabilities. However, a critical gap remains between semantic understanding and reliable physical execution:</p>\n<ol>\n<li><strong>Semantic beliefs are disconnected from environmental facts</strong>: In complex long-term tasks, existing end-to-end controllers or simple API calls lack explicit intermediate state verification and termination signals. The robot may have executed the navigation instructions but not moved, or it may have continuously collided locally but thought the task was progressing normally at the language level.</li>\n<li><strong>lacks cross-modality universal Agent hardware abstraction</strong>: Existing systems are mostly highly bound to specific robot forms or control interfaces, and are difficult to seamlessly extend to diverse hardware such as humanoid robots and four-legged dogs.</li>\n<li><strong>Memory is difficult to persist and trace back to self-improvement</strong>: There is a lack of a general multi-modal memory system that can be persistently stored across sessions, traceable to origin, and self-improved from historical interaction failures.</li>\n</ol>\n<p>To this end, the paper proposes <strong>ABot-AgentOS</strong>, a universal robot Agent operating system that runs on the underlying controller and decouples high-level cognition and physical actions.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-6\">2. Methods and innovations</h3>\n<p>ABot-AgentOS is scheduled by <strong>edge cloud in collaboration with dual LLM cores</strong> and <strong>Agent Harness closed-loop</strong>, <strong>general multi-modal graph memory</strong> and <strong>end-to-end distillation training pipeline</strong> are composed of four modules.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-system-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: ABot-AgentOS overall system architecture: multi-source multi-modal input through edge cloud collaboration dual LLM core routing, Agent Harness closed-loop scheduling skills and multi-level verification, combined with universal multi-modal graph memory and underlying controller</a>\n<figcaption>ABot-AgentOS overall system architecture: multi-source multi-modal input through edge cloud collaboration dual LLM core routing, Agent Harness closed-loop scheduling skills and multi-level verification, combined with universal multi-modal graph memory and underlying controller</figcaption>\n</div>\n<h4 id=\"-整体框架与边云协同双核心\">① Overall framework and edge cloud collaboration dual core</h4>\n<p>ABot-AgentOS distinguishes between edge lightweight model and cloud large model (Dual-LLM Core) in architectural design:</p>\n<ul>\n<li><strong>Edge Tiny LLM</strong>: Deployed on the robot end side, it prioritizes regular conversations, simple tool calls and real-time control instructions to reduce response delays.</li>\n<li><strong>Cloud Large LLM</strong>: When the task involves long-term complex reasoning, multi-step planning or difficult graph memory retrieval, the learned routing strategy is automatically upgraded to cloud large model processing.</li>\n</ul>\n<h4 id=\"-agent-harness-闭环控制\">② Agent Harness closed-loop control</h4>\n<p>Agent Harness changes the design of traditional single-model controllers and divides Agent scheduling into three clearly decoupled roles:</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-agent-harness.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Agent Harness Architecture details: Main LLM is responsible for global scene awareness planning, Skill Runner isolates local execution details, and Verifier provides multi-stage real-time and final verification</a>\n<figcaption>Agent Harness Architecture details: Main LLM is responsible for global scene awareness planning, Skill Runner isolates local execution details, and Verifier provides multi-stage real-time and final verification</figcaption>\n</div>\n<ol>\n<li><strong>Main LLM (Semantic Planner)</strong>: Receives user instructions and memory context, and generates adjustable high-level plans and explicit completion conditions based on the current scenario. Instead of directly emitting micro-actions for each foot, the Main LLM decides to call tools directly or delegate subtasks to a Skill Runner.</li>\n<li><strong>Skill Runner (process executor)</strong>: Runs in an independent local context as a skill-level Subagent. It handles complex processes such as local repeated movements, perspective fine-tuning, and collision recovery, and only returns compressed high-level execution result summaries to the Main LLM to prevent local details from blocking the Main LLM’s global planning.</li>\n<li><strong>Verifier (multi-stage verifier)</strong>:\n    <ul>\n<li><strong>Runtime Verification (Runtime Verification)</strong>: Monitor the trajectory and skill status, and promptly identify stagnation, local infinite loops and frequent collisions.</li>\n<li><strong>Skill Verification</strong>: Verify whether the subtask actually achieves the semantic goal, rather than just relying on Tool to return success.</li>\n<li><strong>Finish Verification</strong>: When Main LLM attempts to terminate the task, compare the initial instructions, final visual observation and environmental facts to prevent false completion.</li>\n</ul>\n</li>\n</ol>\n<h4 id=\"-通用多模态图记忆与终身自进化\">③ Universal multi-modal graph memory and lifelong self-evolution</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-memory-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Universal multi-modal memory architecture and offline fault-driven self-evolution loop: write source-traceable type graphs online, and compile failed Traces into controllable JSON DSL evolution assets offline</a>\n<figcaption> Universal multi-modal memory architecture and offline fault-driven self-evolution loop: write source-traceable type graphs online, and compile failed Traces into controllable JSON DSL evolution assets offline</figcaption>\n</div>\n<ol>\n<li><strong>Multimodal Memory Graph (Memory Graph)</strong>: Write entities, events, locations, visual frames, time associations and attribution chains (Provenance) in online interactions into strongly typed nodes and edges, replacing the stack of original video streams or plain text logs.</li>\n<li><strong>Hybrid Graph Retriever</strong>: combines semantic embedding, lexical matching, metadata filtering and graph edge topology expansion to extract high-quality local evidence subgraphs.</li>\n<li><strong>Failure-Driven Lifelong Self-Evolution (Failure-Driven Lifelong Self-Evolution)</strong>:\n    <ul>\n<li><strong>Split isolation protocol</strong>: In the sequence split deployment, the \\(t\\) split can only use the evolution asset \\(A_{&lt;t}\\) that has been promoted in history.</li>\n<li><strong>Trace diagnosis and asset compilation</strong>: After the split is completed, the system performs Trace diagnosis on the failed sample and generates candidate evolution assets in JSON DSL format (covering the stages of memory writing, evidence selection, frame selection, time normalization, etc.).</li>\n<li><strong>Strict gating verification (Gating)</strong>: The candidate asset must improve the score on the target verification set and not reduce the performance on the regression set:\n\\(\\text{Accept}(a) = \\mathbb{I}[\\Delta S_{\\text{target}}(a) \\ge \\tau_{\\text{gain}} \\land \\Delta S_{\\text{reg}}(a) \\ge -\\tau_{\\text{reg}}]\\)\nAfter passing the inspection, it can be upgraded to \\(A_{\\le t}\\) for subsequent split use, achieving cumulative growth without label leakage.</li>\n</ul>\n</li>\n<li><strong>Edge-cloud collaborative privacy management</strong>: Private memories (faces, personal items, etc.) are retained at the edge, and only public environmental memories (roadblocks, road landmarks) without sensitive information are shared on the cloud, with a privacy classification accuracy of over 99%.</li>\n</ol>\n<h4 id=\"-embodiedworldbench-与策略蒸馏训练管线\">④ EmbodiedWorldBench and policy distillation training pipeline</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-embodied-world-bench.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: EmbodiedWorldBench evaluation benchmark overview: 16 executable scenarios and 4-level difficulty settings covering indoor and outdoor composite scenes, NPC interactions and dynamic events</a>\n<figcaption>EmbodiedWorldBench evaluation benchmark overview: 16 executable scenarios and 4-level difficulty settings covering indoor and outdoor composite scenes, NPC interactions and dynamic events</figcaption>\n</div>\n<p>The paper launched <strong>EmbodiedWorldBench</strong>, covering 16 indoor, outdoor and mixed scenes, with 4 difficulty levels and 200+ composite tasks involving navigation, NPC interaction, item search and dynamic event response.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-AgentOS-training-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Student policy end-to-end training pipeline: build environment through text sandbox, self-evolution reward engine to generate preference data and use DPO/SFT to optimize edge deployment model</a>\n<figcaption> Student policy end-to-end training pipeline: build environment through text sandbox, self-evolution reward engine to generate preference data and use DPO/SFT to optimize edge deployment model</figcaption>\n</div>\n<p>In order to transfer the capabilities of the large cloud model Agent Harness to the small on-device model, the paper designed an end-to-end distillation pipeline:</p>\n<ol>\n<li><strong>Controllable text sandbox construction</strong>: Use LLM to automatically generate a text sandbox environment with executable status and complex logic.</li>\n<li><strong>self-evolution reward engine</strong>: Generate automatic scoring and DPO preference pairs based on structured Trace.</li>\n<li><strong>SFT + DPO policy optimization</strong>: Training and deploying lightweight Student Policy in a sandbox environment.</li>\n</ol>\n<hr/>\n<h3 id=\"3-核心结果发现-6\">3. Results and findings</h3>\n<ol>\n<li><strong>Long-range embodied execution</strong>: In the initial subset evaluation of EmbodiedWorldBench, ABot-AgentOS achieved significant improvements in task success rate (Success Rate) and goal completion (Goal Completion) compared with the single controller baseline, and the Verifier mechanism reduced early false terminations by more than 35%.</li>\n<li><strong>multi-modal memory benchmark is fully ahead of</strong>:\n    <ul>\n<li><strong>LoCoMo</strong> (long-horizon session memory): Static version reaches <strong>87.5</strong>, +Self-evo improves to <strong>88.7</strong> (close to the human upper limit of 87.7).</li>\n<li><strong>OpenEQA (EM-EQA)</strong>: Static reaches <strong>59.9</strong> under 8 frame budget, +Self-evo improves to <strong>60.4</strong> (surpassing SnapMem 57.2 and GaussExplorer 57.8).</li>\n<li><strong>Mem-Gallery</strong>: Static reaches <strong>88.6</strong>, +Self-evo improves to <strong>89.0</strong> (on conflict detection CD 97.5% with reject answer AR 100% outstanding performance).</li>\n<li><strong>NExT-QA</strong>: Validation Acc@All reaches <strong>76.5%</strong> (+Self-evo increased by 4.1 points), significantly ahead of classic video agents such as VideoAgent.</li>\n<li><strong>EgoLifeQA</strong>: Obtained the average accuracy of <strong>66.2%</strong> under single frame retrieval settings.</li>\n</ul>\n</li>\n<li><strong>Cross-task generalization of lifelong self-evolution</strong>: The self-evolution mechanism brings stable increments on all 5 memory benchmarks, and the performance gain comes entirely from general improvements to the memory pipeline (such as time normalization, relationship disambiguation), rather than indiscriminate accumulation of memory content.</li>\n</ol>\n<hr/>\n<h3 id=\"4-局限性-6\">4. Limitations</h3>\n<ol>\n<li><strong>Perception and control of noise in the complex real physical world</strong>: At present, large-scale verification is mostly carried out in executable simulation or semi-physical sandbox. In the face of high-noise depth perception, grasping failure and network communication delay in the real world, more in-depth hardware real robot tuning is still needed.</li>\n<li><strong>Automated distillation relies on text sandbox</strong>: Small model strategy distillation currently mainly relies on the text state sandbox environment. In the future, multi-modal visual observation and more complex physical simulation platforms (such as Isaac Sim/Habitat) need to be introduced.</li>\n<li><strong>Memory self-evolution requires a credible feedback signal</strong>: The offline self-evolution mechanism relies on deterministic error diagnosis or human feedback. How to safely define “answer errors” in an open unsupervised environment is still a long-term challenge.</li>\n</ol>\n<hr/>\n<h2 id=\"abot-er\">8. ABot-ER (2026)</h2>\n<p>———One model for embodied understanding, long-horizon planning, and interaction-point grounding, with training data revised through failure diagnosis</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.18355v2\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.18355v2</a> · <a href=\"https://github.com/amap-cvlab/ABot-ER\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<h3 id=\"abot-er-key-takeaways\">Key takeaways</h3>\n<p>ABot-ER unifies spatial relations, scene states, temporal events, action plans, and interaction targets in one embodied reasoning model, supplying judgements, plans, and image coordinates to runtimes such as <a href=\"#abot-agentos\">ABot-AgentOS</a>, while downstream policies carry out physical actions.\nIts most transferable idea is to identify what is wrong with the supervision before coordinating new content, output-protocol repairs, and sampling changes, instead of treating every low score as a shortage of data.\nThe shared backbone receives two task-family-specific low-rank residual branches for question answering and planning, but remains jointly trainable; after protocol repair, the ablation does not show gains in either suite mean, placing a clear boundary on the architectural benefit.\nA single post-training pass on the converged corpus approaches the twelve-benchmark mean of a six-round chain with one fifth of the accumulated post-training, suggesting that the reusable assets include audited data and evaluation rules.\nPoint-hit accuracy, simulated task success, and qualitative physical demonstrations should be distinguished, as should training-time corpus evolution and online adaptation after deployment.</p>\n<hr/>\n<h3 id=\"abot-er-background\">1. Background and problem</h3>\n<p>Moving an object to a requested location requires a robot to understand object-to-person spatial relations, current states, step dependencies, and actionable regions; separate training can produce uneven specialists, while joint training introduces interference between output formats and learning rates across capabilities.\nThe paper calls these bottlenecks <strong>Data-Model Drift</strong>, where a fixed data mixture no longer matches the model’s current weaknesses, and <strong>Modality Entanglement</strong>, where text, plans, and coordinate supervision impose different demands on shared parameters.\nABot-ER aims to combine five kinds of embodied judgement in one checkpoint and establish a training workflow that can be diagnosed, revised, and audited.</p>\n<hr/>\n<h3 id=\"abot-er-method\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-ER-reasoning-interface.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: ABot-ER reasoning interface between observations, the agent runtime, and downstream action policies</a>\n<figcaption>Original Figure 2: ABot-ER sits between observation and control, returning semantic judgements, action plans, and normalized image coordinates. The agent runtime schedules queries, verification, and replanning; downstream policies execute actions.</figcaption>\n</div>\n<h4 id=\"abot-er-overview\">① Overall framework: a unified reasoning model, data-revision engine, and training-selection workflow</h4>\n<p>The <strong>online model</strong> receives images, videos, or textual context and generates the requested response; the <strong>offline data engine</strong> reads evaluations and error records to revise the next training corpus; <strong>two-stage training and checkpoint selection</strong> turn that corpus into a new model while checking for substantial regressions in existing capabilities.\nHere, execution means identifying actionable targets and locations. The model does not directly emit base velocities, joint positions, or torques; at deployment, a runtime passes its judgements to navigation, manipulation, and other execution policies.</p>\n<table>\n<thead>\n<tr>\n<th>Capability dimension</th>\n<th>Input and processing</th>\n<th>Example output</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Spatial and relational reasoning</td>\n<td>Infer directions, distances, and layout from images or multiple views</td>\n<td>Identify the object on the user’s left</td>\n</tr>\n<tr>\n<td>Scene and state understanding</td>\n<td>Recognize task-relevant objects, attributes, and current states</td>\n<td>Identify the tabletop blocks and whether the expression is valid</td>\n</tr>\n<tr>\n<td>Temporal and event reasoning</td>\n<td>Infer event order and state changes from video or before-and-after observations</td>\n<td>Determine whether a block was placed or dropped during transfer</td>\n</tr>\n<tr>\n<td>Long-horizon action organization</td>\n<td>Arrange steps with preconditions using the goal, history, and feedback</td>\n<td>Pick the object, move, and place it in the target region</td>\n</tr>\n<tr>\n<td>Point grounding and affordance</td>\n<td>Ground an instruction in an actionable image region</td>\n<td>Return a grasp point or coordinates inside a valid placement region</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"abot-er-task-conditioning\">② Shared backbone and task-conditioned low-rank residuals: shared knowledge with task-specific capacity</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-ER-model-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Shared ABot-ER backbone with deterministic question-answering and planning residual branches</a>\n<figcaption>Original Figure 3: tasks share image encoding, the language backbone, and the output head. Two residual branches augment Q/V projections in the last four full-attention blocks. Each sequence selects one route; point grounding still follows the question-answering route.</figcaption>\n</div>\n<p><strong>Multimodal encoding.</strong> Images or video frames pass through a vision encoder and projector to form visual representations, while text becomes embeddings. Their original interleaved order is retained at the shared decoder; text-only tasks bypass vision.\nThe 9B instance uses <strong>Qwen3.5-9B</strong>, with 32 decoder blocks arranged as three Gated DeltaNet linear-attention blocks followed by one full-attention block, and a language output head shared by all tasks.</p>\n<p><strong>Task routing.</strong> The data loader inserts a task marker inside the first user message, selects a branch from the record’s task family, and keeps that branch throughout the sequence.\nThe paper’s <code class=\"language-plaintext highlighter-rouge\">[EQA]</code> family covers spatial, state, and temporal questions as well as interaction coordinates; <code class=\"language-plaintext highlighter-rouge\">[TASK_PLAN]</code> covers action plans. These families follow how the data was collected, rather than a text-versus-coordinate split, and there are no five separate capability decoders.</p>\n<p><strong>Residual adaptation.</strong> The <code class=\"language-plaintext highlighter-rouge\">q_proj</code> and <code class=\"language-plaintext highlighter-rouge\">v_proj</code> projections in zero-indexed layers 19, 23, 27, and 31—the last four full-attention blocks—each receive two sets of task-specific low-rank parameters.\nFor one projection, the calculation can be summarized as:</p>\n\n\\[\\widetilde z_c = Wx + b + \\frac{\\alpha}{r} B_c A_c x, \\qquad r=16,\\quad \\alpha=16.\\]\n\n<p>The first two terms are the shared transformation, and the last is the selected task family’s correction. The shared language backbone and residuals train jointly; the vision encoder is frozen and the projector remains trainable, so this is not a frozen backbone with only LoRA trained on top.</p>\n<blockquote>\n<p><strong>Example:</strong> For the same lemon image, both “How many lemons are there?” and “Point to the graspable center” select the question-answering residual; “Put the lemon in the pan, then put the pan in the oven” selects the planning residual.\nThe three calls share object and spatial knowledge while giving plan generation its own parameter correction. The calling task determines the route; the model need not generate an explanation to decide which branch to use.</p>\n</blockquote>\n<h4 id=\"abot-er-data-evolution\">③ Data-model self-evolution: use error evidence to choose the repair</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-ER-data-model-evolution.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Evaluation-driven revision of supervision content, output protocols, and sampling mixtures</a>\n<figcaption>Original Figure 4: each round diagnoses evaluation failures, coordinates content, protocol, and mixture revisions, and selects a new model after data audits, training, and retention checks. The three-stream percentages describe the question-answering partition of a particular development round.</figcaption>\n</div>\n<p>The engine receives capability scores, item-level outputs, training logs, and source records. One coordinating language-model agent proposes root-cause hypotheses and data requirements; deterministic programs check candidate data against format, provenance, exposure-cap, and trajectory-replay requirements.\nExperts calibrate diagnoses and acceptance rules in the initial rounds, and later runs are constrained by those rules. The evolving artifact is the training corpus; the architecture and learning algorithm do not rewrite themselves.</p>\n<p><strong>Capability diagnosis</strong> classifies errors into parsing failures, coordinate-protocol violations versus point misses, multiple-choice errors, numeric parsing errors, open-ended deductions, and planning failures, then maps them to capability gaps. A drop on one benchmark does not automatically establish a dimension-wide weakness; other benchmark trends or item-level evidence are required.\nThe diagnosis feeds three complementary repairs that cannot substitute for one another:</p>\n<table>\n<thead>\n<tr>\n<th>Revision mechanism</th>\n<th>Problem addressed</th>\n<th>Concrete action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Content Evolution</td>\n<td>Missing correct or complete learning targets</td>\n<td>Construct plans with verified preconditions and successful replay to the terminal state; retain evidence-grounded interaction targets</td>\n</tr>\n<tr>\n<td>Protocol Evolution</td>\n<td>Incompatible values or formats for the same target</td>\n<td>Unify numeric coordinate conventions while fixing each task’s point count, wrapper, and action schema</td>\n</tr>\n<tr>\n<td>Mixture Evolution</td>\n<td>Insufficient training exposure to valid supervision</td>\n<td>Adjust sampling within source and repetition caps while retaining data for established capabilities</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Coordinate protocols provide the clearest example.</strong> Historical data mixed 0–1000 coordinates, normalized single points, and eight-point XML. Some labels also described arm-motion endpoints rather than the target regions requested by the question.\nThe repair unifies coordinates as <code class=\"language-plaintext highlighter-rouge\">[0, 1]</code> values relative to the original image, with three decimal places, while preserving each task’s required serialization: eight-point XML for VABench-P and lists of one to three point tuples for Where2Place.</p>\n<blockquote>\n<p><strong>Example:</strong> The same target at the center of an image might be represented as <code class=\"language-plaintext highlighter-rouge\">(500, 500)</code> on the old scale and <code class=\"language-plaintext highlighter-rouge\">(0.500, 0.500)</code> after normalization.\nNumeric consistency alone is insufficient: a single-point list may still fail an evaluator that expects eight points. Even eight valid points teach the wrong task if they land on the arm endpoint rather than the requested object.</p>\n</blockquote>\n<p><strong>Training-budget figures need an explicit accounting basis.</strong> Corpus construction uses a token proxy estimated from characters and media costs, rather than an actual tokenizer count. Unique examples, materialized training records, and assistant supervision tokens measure different things.\nIn the final Stage B corpus, for example, planning represents <strong>25.00% of physical records</strong> but <strong>63.76% of assistant supervision tokens</strong>, because complete plans are much longer than single-option answers. Since the loss is normalized per sequence, the latter share is not directly a loss weight.\nThe figure’s approximately 45% fine-grained capability, 15% benchmark guarantee, and 40% foundational streams belong to <strong>R6’s question-answering partition</strong>, with planning allocated separately; they are not a fixed mixture used by both released stages. Quotas are written into the configuration by hand, while programs implement and check them.</p>\n<p><strong>Data governance</strong> checks contradictory answers for the same image-question pair, duplicate media, invalid references, source eligibility, and test overlap. New labels must be grounded in images, environment states, or trusted annotations.\nOne concrete lesson was R3’s apparent EB-ALFRED score of “100”: its summary included only the first 12 completed episodes out of 300, and official test trajectories had separately entered the legacy training pool. Recomputing the full summary gave 27, which was still unusable because the weights were contaminated.\nThe authors then quarantined three sources in full, covering 23,565 candidate records. R3 remains diagnostic history and is excluded from performance claims; the released line restarts on cleaned data without inheriting weights trained on those sources.</p>\n<h4 id=\"abot-er-training\">④ Two-stage training, a unified loss, and checkpoint selection</h4>\n<p><strong>Stage A: cross-capability foundation.</strong> Supervised training begins from a pretrained VLM on the joint corpus to cover all five capabilities and establish the shared numeric protocol.\n<strong>Stage B: targeted repair.</strong> A shorter supervised fine-tuning run continues from the selected Stage A checkpoint, lowers the learning rate, increases data for deficits such as planning recovery, and retains other-task data to reduce forgetting. This stage is not reinforcement learning.</p>\n<p>All tasks use the same autoregressive cross-entropy objective, supervising assistant outputs only; input tokens, media placeholders, and padding are excluded.\nWriting $S$ for the assistant output positions in one sample, its sequence-normalized objective can be expressed as:</p>\n\n\\[\\mathcal L = -\\frac{1}{\\lvert S\\rvert}\\sum_{t\\in S}\\log p_{\\theta}(y_t\\mid x,c,y_{&lt;t}).\\]\n\n<p>Assistant tokens across a multi-turn sample are normalized together. Relative exposure is controlled mainly through corpus construction and sampling, rather than five separate capability losses.\nPaper v2 reports <strong>462,390 physical records and 294,762 unique identities</strong> for Stage A, and <strong>104,960 records and 52,480 identities</strong> for Stage B, where every identity appears exactly twice. The record counts cannot be added and treated as unique examples.\nThe decoder learning rates are <strong>4×10⁻⁶ and 3×10⁻⁷</strong>, with optimizer and scheduler reset between stages. The complete jobs take approximately <strong>826 GPU hours</strong> across 32 GPUs, excluding data construction and full-suite evaluation.</p>\n<p>Checkpoint selection first checks limits on other-capability regressions, parser reliability, and detected test overlap, then compares leading-benchmark counts and target scores within one checkpoint.\nThe development history is not six continuously accumulated weight updates: major protocol and source changes often trigger retraining from the pretrained model, and the released Stage A→B line must also be distinguished from R6.</p>\n<h4 id=\"abot-er-inference\">⑤ Inference and integration with the physical robot</h4>\n<p>At inference, the caller specifies the task family and activates its residual; the shared output head generates the answer token by token. Five separate task models are unnecessary, but autoregressive generation still involves repeated decoding computations.\nIn the Galaxea R1 Pro demonstrations, ABot-ER is the visual-question-answering component of <a href=\"#abot-agentos\">ABot-AgentOS</a>, served on an external host with one RTX 5090D. AgentOS orchestrates the interaction, and the separate <strong>ABot-M</strong> VLA executes manipulation.\nBefore each action step, the runtime queries the scene and interaction targets; afterward it queries the outcome, then uses the returned judgement to continue or revise the remaining plan.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Task instruction and current observation\"] --&gt; B[\"ABot-ER: state judgements and interaction targets\"]\n    B --&gt; C[\"ABot-AgentOS: organize and dispatch steps\"]\n    C --&gt; D[\"ABot-M or another downstream policy executes\"]\n    D --&gt; E[\"Acquire the post-action observation\"]\n    E --&gt; F[\"ABot-ER: assess state changes and outcomes\"]\n    F --&gt; G{\"Runtime decides whether the goal is achieved\"}\n    G -- \"Continue or revise\" --&gt; C\n    G -- \"Achieved\" --&gt; H[\"End the task\"]\n</code></pre>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-ER-real-world-deployment.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Qualitative block-arithmetic and rock-paper-scissors demonstrations on Galaxea R1 Pro</a>\n<figcaption>Original Figure 7: qualitative block-arithmetic and rock-paper-scissors demonstrations. ABot-ER reads visual states, ABot-AgentOS controls task progression, and a downstream VLA executes actions. These examples provide no additional physical success-rate measurements.</figcaption>\n</div>\n<hr/>\n<h3 id=\"abot-er-results\">3. Results and findings</h3>\n<p><strong>① Multiple capabilities coexist in one checkpoint.</strong> Against nine public baselines in the main table, ABot-ER 9B leads the listed results on six of twelve benchmarks.\nThe equally weighted means over seven perception, three planning, and two point-grounding benchmarks are <strong>63.86, 41.61, and 67.06</strong>, exceeding the strongest listed baseline in each group by <strong>3.94, 4.20, and 11.81</strong> points. Those three reference values come from different models.</p>\n<table>\n<thead>\n<tr>\n<th>Representative benchmark</th>\n<th>ABot-ER 9B</th>\n<th>Best listed baseline</th>\n<th>Metric meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ERQA</td>\n<td><strong>47.31</strong></td>\n<td>Cosmos3-Nano 46.09</td>\n<td>Embodied multiple-choice reasoning accuracy</td>\n</tr>\n<tr>\n<td>RoboVQA</td>\n<td><strong>71.79</strong></td>\n<td>MiMo-Embodied 66.09</td>\n<td>Open-ended robot-video question-answering score</td>\n</tr>\n<tr>\n<td>Cosmos</td>\n<td><strong>68.96</strong></td>\n<td>Cosmos3-Nano 63.18</td>\n<td>Temporal and physical-event multiple-choice accuracy</td>\n</tr>\n<tr>\n<td>EB-ALFRED</td>\n<td><strong>26.67</strong></td>\n<td>MiMo-Embodied 17.33</td>\n<td>Interactive task success rate</td>\n</tr>\n<tr>\n<td>EB-Habitat</td>\n<td><strong>37.00</strong></td>\n<td>Cosmos3-Nano 26.67</td>\n<td>Interactive task success rate</td>\n</tr>\n<tr>\n<td>VABench-P</td>\n<td><strong>63.33</strong></td>\n<td>Cosmos3-Nano 47.54</td>\n<td>Fraction of points inside the target box</td>\n</tr>\n</tbody>\n</table>\n<p>The scores share a 0–100 display scale but have different meanings; their aggregate is not an overall physical-robot success rate.\nThe nine-benchmark EQA mean of <strong>64.57</strong> includes seven perception and two point-grounding tasks. The twelve-benchmark mean is <strong>58.83</strong>, not an equally weighted average of the EQA and planning suite means.</p>\n<p><strong>② Targeted post-training brings gains and trade-offs.</strong> From Stage A to the released checkpoint, the planning mean rises <strong>39.43→41.61</strong>, with EB-ALFRED and EB-Habitat gaining <strong>3.00 and 3.33</strong> points, while Where2Place falls <strong>72.90→70.79</strong>. Improvement is not synchronous across capabilities.</p>\n<p><strong>③ Conditional-branch benefits depend on data consistency.</strong> In controlled paired ablations on <strong>Qwen3.6-35B-A3B</strong>, conditioning improves 11/12 benchmarks and raises the twelve-benchmark mean by <strong>1.36</strong> on the corpus with unaligned protocols. After protocol repair, the best checkpoints of each run give EQA <strong>66.94→66.27</strong> and planning <strong>42.87→41.94</strong>, with neither suite improving.\nET-Plan-Bench retains a consistent benefit: conditioning wins at all 17 matched checkpoints, averaging <strong>+3.3</strong> points. The ablation switches task markers and residuals together, does not isolate their contributions, and does not establish an independent architectural gain for 9B.</p>\n<p><strong>④ The converged corpus transfers, while training history still shapes the capability profile.</strong> With a common starting point, final corpus, and final-pass progress, a single post-training pass and a six-round chain reach twelve-benchmark means of <strong>60.00 and 60.09</strong>, using one fifth as much accumulated post-training in the single-pass case. Interactive planning remains weaker: EB-ALFRED is <strong>25.00 versus 30.00</strong>, and EB-Habitat <strong>48.67 versus 51.67</strong>.\nThe same two-stage corpora also transfer to 2B, 4B, 27B, and 35B-A3B backbones without rerunning corpus revision for each size. The 27B mean is <strong>62.57</strong>; this is a separate scaling experiment and should not be mixed with the training-history comparison.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/ABot-ER-cross-round-tradeoffs.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-round benchmark gains and regressions during ABot-ER development</a>\n<figcaption>Original Figure 6a: each development transition combines gains and regressions. Budgets, initialization, and some historical protocols differ across rounds, so this heatmap describes development history rather than controlled comparisons that change only the data strategy.</figcaption>\n</div>\n<p><strong>⑤ Evaluation details limit the conclusions.</strong> The current VABench-P prediction archive repeats one location eight times, so these cannot be interpreted as eight independent candidates. The paper also leaves the provenance of the EB archives’ original online calls for verification, preventing success rates alone from establishing native closed-loop correction.\nPublic baselines come from leaderboard snapshots at different times, with potentially different original training and evaluation configurations. Point scores measure target hits rather than control precision or physical manipulation success.</p>\n<hr/>\n<h3 id=\"abot-er-limitations\">4. Limitations</h3>\n<p>Development rounds jointly change budgets, learning rates, data, and some evaluation protocols; quotas remain manually specified, and the appendix retains residual audit risks such as uncovered media. Cross-round gains therefore do not independently establish the causal benefit of self-evolution.\nPhysical demonstrations are mainly qualitative, without large-scale success-rate and latency comparisons, and interactive planning still fails frequently. Navigation or manipulation integration requires separate validation of visual judgements, runtime decisions, and downstream control.</p>\n<hr/>\n<h2 id=\"harness-robotic-os\">9. Harness Robotic OS (2026)</h2>\n<p>——Upgrade the four-legged inspection from “navigation stack” to “embodied agent runtime”</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.11225\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.11225</a></p>\n<hr/>\n<h3 id=\"精华-7\">Key takeaways</h3>\n<p>The real question of this article is not “how to navigate more accurately”, but “how to make a bunch of ready-made modules collaborate, leave traces, and be rollable in the same context” - taking system integration itself as the research object. The most worthy reference is the hard boundary it establishes: the real-time control loop (SLAM/planning/control) and the cognitive loop (agent orchestration/memory/reflection) belong to two layers. The agent can only “orchestrate skills” but cannot directly issue movement instructions, so if the reasoning goes wrong, the motor will not be burned. The memory is divided into three layers: working / episodic / semantic based on “retention period” rather than “data type”. The retrieval is jointly conditioned by task intention, spatial location, and scene semantics to avoid stuffing the entire operation and maintenance history into each reasoning context. Self-evolution is deliberately made into “offline candidate → safety gate → staged rollout → rollback” instead of changing the model online. This is a prerequisite for long-running robots to be audited. But be clear: Cognitive runtime (speech/memory/self-evolution) in this article only has protocols and no numbers. What really outperforms the actual test is the classic navigation plus VLM inspection pipeline.</p>\n<hr/>\n<h3 id=\"1-研究背景问题-7\">1. Background and problem</h3>\n<p>Residential property inspections must cover a wide range of public spaces such as roads, fire escapes, building entrances and exits, equipment rooms, and garbage rooms. Manual patrols are limited by manpower and personal experience in terms of frequency, consistency, and traceability. Quadruped robots can climb hills and climb narrow roads, making them a suitable carrier. However, “being able to walk” does not mean “being able to perform inspections” - it also requires continuous positioning, global task planning, reactive obstacle avoidance, scene-level understanding of hidden dangers, human-computer interaction, and connection with the work order system.</p>\n<p>The author points out that a common problem in current deployed systems is that these capabilities are made into a bunch of loosely coupled modules: sensor drivers, navigation algorithms, visual language services, operating interfaces, and enterprise applications each hold state and rely on point-to-point adapters to communicate, resulting in three gaps - <strong>Semantic task intent and robot pose/observation/ Execution status is out of line</strong>, <strong>Historical task experience is not systematically retained and retrieved</strong>, <strong>Prompt words/tool strategies/task maps/skill changes are difficult to evaluate, trace and safely roll back</strong>.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-7\">2. Methods and innovations</h3>\n<h4 id=\"21-整体框架四个平面--一条自进化环\">2.1 Overall framework: four planes + a self-evolution ring</h4>\n<p>HROS divides the system into four layers: <strong>Robot Runtime</strong> (Hardware abstraction: edge computing, multi-modal sensing, connectivity and I/O, quadruped execution), <strong>Embodied Autonomy Skills</strong> (Encapsulate SLAM, perception, global planning, and local motion into stateful, reusable “skills”), <strong>Cognitive Agent Runtime</strong> (Agent orchestration, hierarchical memory, multimodal reasoning, skill and tool scheduling, and self-evolution closed-loop), <strong>Interaction and Operations</strong> (Voice and multi-modal I/O, inspection task console, enterprise closed-loop). The four layers are not call stacks but binding relationships: each skill reports its own input timestamp, execution status, confidence or failure code, and output reference to the shared context bus, and the cognitive layer monitors the progress accordingly. <strong>but does not enter the real-time control loop</strong> .</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-architecture.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: HROS four-layer architecture. The dark solid line is the runtime data flow, the bidirectional arrow is the binding between the agent and the skill, the dotted line is the self-evolution path, and the green line is the safety gate - only the candidate version that has passed the safety gate can return to the skill runtime</a>\n<figcaption>HROS four-layer architecture. The dark solid line is the runtime data flow, the bidirectional arrow is the binding between the agent and the skill, the dotted line is the self-evolution path, and the green line is the safety gate - only the candidate version that has passed the safety gate can return to the skill runtime</figcaption>\n</div>\n<p><strong>stuck point dimensionality reduction｜What exactly does “embodied agent runtime” have more than ordinary navigation stack</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimensions</th>\n<th>Regular four-legged inspection system</th>\n<th>HROS</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Status ownership</td>\n<td>Each module maintains its own state and relies on task-specific adapters to communicate point-to-point.</td>\n<td>Shared context bus, physical state and agent reasoning have the same origin</td>\n</tr>\n<tr>\n<td>historical experience</td>\n<td>Throw it away after running, leaving at most one log</td>\n<td>working / episodic / semantic third-level memory, retrieval based on intention plus location conditions</td>\n</tr>\n<tr>\n<td>Change governance</td>\n<td>Change the prompt or skill and go online directly. If something goes wrong, rely on human resources to roll it back.</td>\n<td>Candidate version goes offline and returns with security gate and staged rollout, which can be traced and rolled back</td>\n</tr>\n<tr>\n<td>control boundary</td>\n<td>The upper layer can directly issue motion instructions</td>\n<td>Agents can only use orchestration skills, and movement instructions must pass the robot-runtime interface.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"22-robot-runtimevbot-四足平台\">2.2 Robot Runtime: Vbot quadruped platform</h4>\n<p>The physical layer uses Vbot quadrupeds as the carrier of sensing, computing power, communication and mobility: binocular cameras, 16-line lidar, IMU, GNSS and 4G/5G. The edge computer is Horizon RDK S100P (6-core ARM Cortex-A78AE + 128 TOPS Nash BPU), which runs perception and intelligent agent services on the machine. The robot controller exposes motion instructions and status feedback through the robot-runtime interface of HROS - <strong>. The design motivation of this layer of isolation is to prevent the upper-layer agent from bypassing the verification and directly sending the bottom-layer executor instruction</strong>.</p>\n<h4 id=\"23-embodied-autonomy-skills四个有状态技能\">2.3 Embodied Autonomy Skills: Four stateful skills</h4>\n<p>This layer is the only part of the entire text that has actual measured numbers. The four modules are all engineered combinations of off-the-shelf open source software:</p>\n<ul>\n<li><strong>state estimation · Fast-LIO2</strong>: Input lidar point cloud and IMU, tightly coupled to estimate 6-DoF pose and incremental mapping, and output a priori point cloud map and online pose. Three working modes - mapping (on-site survey phase), online positioning (daily patrol, real-time scanning and registration to a priori map), and relocation (tracking degradation or restoring pose after restart). The design motivation is a <strong>shared map coordinate system</strong>: residential patrols will repeatedly revisit the same asset under different lighting and different scene appearances. Only by tying each image, each waypoint, each hidden danger event, and each report to this coordinate system can HROS perform spatially related memory retrieval and cross-task comparison.</li>\n<li><strong>Local Perception · Hobot-Stereo</strong>: Inputs synchronized binocular images, outputs dense near-field depth and fuses it with lidar obstacle representation. The design motivation is that laser sparse sampling cannot adequately express short obstacles, fine structures, and occlusion boundaries in the near field. The depth points are first transformed into the map system, filtered by distance and confidence, and then inserted into the local voxel representation consumed by EGO-Planner; <strong>binocular is a supplement rather than a replacement for</strong>. Uncertain observations are treated conservatively and are deleted from the local map if they have not been observed repeatedly for a long time.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-environment-representation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Two sets of complementary environment representations. Left: Global three-dimensional point cloud map built by Fast-LIO2 in the shared mission coordinate system, used for relocation and mission planning; Right: Hobot-Stereo's dense depth (upper left), fused point cloud (upper right), RGB input (lower left), local bird's-eye geometry (lower right), filling the laser gap in the near field</a>\n<figcaption> Two sets of complementary environment representations. Left: Global three-dimensional point cloud map built by Fast-LIO2 in the shared mission coordinate system, used for relocation and mission planning; Right: Hobot-Stereo's dense depth (upper left), fused point cloud (upper right), RGB input (lower left), local bird's-eye geometry (lower right), filling the laser gap in the near field</figcaption>\n</div>\n<ul>\n<li><strong>Task Planning · PCT-Planner</strong>: Property inspection is a <strong>coverage task</strong> rather than a single query from the starting point to the end point. The route must connect the strategically defined viewpoints (firefighting facilities, equipment room entrances, garbage collection points) and be passable throughout. PCT-Planner calculates collision-free sections on the three-dimensional prior point cloud map. The task layer is sorted according to the inspection strategy and saves the results as a reusable task template. The global route at runtime is just <strong>reference</strong> instead of direct motion instructions. The progress is represented by “current road segment + current waypoint + completed viewpoint + remaining inspection actions” - in this way, the orchestrator can pause, resume, and reschedule non-safety-critical tasks without touching the local controller at all.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-inspection-route.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: PCT-Planner generates a global inspection route on a priori point cloud map, connects 8 inspection waypoints, and archives and reuses it as a task template</a>\n<figcaption>PCT-Planner generates a global inspection route on a priori point cloud map, connects 8 inspection waypoints, and archives and reuses it as a task template</figcaption>\n</div>\n<ul>\n<li><strong>Motion Intelligence · EGO-Planner</strong>: Input the global reference route, current pose, and fused obstacle representation, output a dynamically feasible local trajectory, and then convert it into quadruped control instructions constrained by speed, clearance, and continuity. Three behaviors - nominal tracking, local re-planning (generating short detours when temporary obstructions such as pedestrians, illegally parked vehicles, cleaning equipment, etc.), recovery (stopping when there is no feasible local trajectory and reporting a failure code <strong>with type</strong>, leaving it to the task layer to decide whether to wait, retry or call the operator).</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/HROS-local-corridor.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: EGO-Planner optimizes the partially passable corridor (blue area) in front of the dog walking pedestrian. The global route only gives direction, and the decision to give way is completed by the local planner</a>\n<figcaption>EGO-Planner optimizes the partially passable corridor (blue area) in front of the dog walking pedestrian. The global route only gives direction, and the decision to give way is completed by the local planner</figcaption>\n</div>\n<h4 id=\"24-cognitive-agent-runtime一接地的语音交互\">2.4 Cognitive Agent Runtime (1): Grounded Voice Interaction</h4>\n<p>Streaming ASR converts speech into a time-stamped intent hypothesis, <strong>, but does not directly execute</strong> - it must first be grounded with the current robot pose, active tasks, visible scenes, and permission policies. Ambiguous or security-related instructions must be explicitly confirmed. TTS reports task acceptance, navigation progress, discovered hidden dangers, recovery actions, and completion status. The design motivation is to allow text, voice, images, and enterprise messages to enter the same multi-modal task interface, rather than being scattered in independent applications.</p>\n<h4 id=\"25-cognitive-agent-runtime二分层记忆\">2.5 Cognitive Agent Runtime (2): Hierarchical memory</h4>\n<p>The memory is divided into three layers according to the <strong>retention period</strong>: working stores short-range information (current tasks, recent conversations, robot status, local observations, tool calls to be returned); episodic stores task fragments indexed by time (trajectories, decisions, observations, hidden danger events, failure and recovery results); semantic stores stable site knowledge (map partitions, asset identification, inspection rules, historical defects, property disposal processes). Retrieval is jointly conditioned by task intention, spatial location, scene semantics, and execution status.</p>\n<p><strong>stuck point dimensionality reduction｜What are installed in each of the three layers and how does the retrieval occur?</strong></p>\n<blockquote>\n<p><strong>Take</strong> as an example: The robot inspected the door of the power distribution room in Building 3 for the seventh time, and there was a cardboard box on the ground in the screen.</p>\n<ul>\n<li><strong>working memory</strong> Install “at this moment”: the current task ID, the sentence just now “Go to Building 3 and have a look”, the current pose, the last two frames of observation, and the Qwen3-VL call that has not yet been returned. Cleared when the task is over.</li>\n<li><strong>episodic memory</strong> “Which time” was installed: The third inspection was judged as “stuff pile” at the same location, and manual review was changed to “temporary express delivery”; the fifth time a partial replanning was triggered due to pedestrians blocking the road. Timestamped, indexed.</li>\n<li><strong>semantic memory</strong> Installation “This place has always been like this”: The power distribution room is a key fire protection area. The rule is that no objects should be piled within 1 meter in front of the door. It is a high-frequency point in the historical defect record. Does not change with a single task.</li>\n</ul>\n<p>The retrieval is not to pour all three layers into the context, but to use “intent = inspection + location = distribution room + scene semantics = there are boxes on the ground” to conditional recall: semantic gives the applicable rules, episodic gives “the last time this kind of box was judged as express delivery”, and working gives the current screen. So this time there is a chance to stop false positives - and this is what the paper says to use Recall@5 and task completion rate to measure, but the <strong>number has not yet been given to</strong>.</p>\n</blockquote>\n<h4 id=\"26-cognitive-agent-runtime三安全门把守的自进化\">2.6 Cognitive Agent Runtime (3): Self-evolution of security gate guarding</h4>\n<p>Self-evolution is clearly defined as “experience to update” <strong>Governed process</strong> , instead of changing the model online. At the end of each task, the execution trace and manual feedback are written into the experience buffer; in the reflection and evaluation phase, success or failure scoring, failure attribution, consistency checks are performed, and candidate updates (memory entries, prompts, tool selection strategies, task diagrams, reusable skills) are produced; candidate versions are evaluated on offline regression use cases and safety rules, with traceability records, and versioned grayscale is launched after passing the safety gate.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Task execution track + Human feedback\"] --&gt; B[\"experience buffer&lt;br/&gt;episodes · traces · failures\"]\n    B --&gt; C[\"Reflect and evaluate&lt;br/&gt;Score for success or failure · failure attribution · Consistency check\"]\n    C --&gt; D[\"candidate update&lt;br/&gt;memory / prompt / tool strategy / task map / Skills\"]\n    D --&gt; E{\"safety gate&lt;br/&gt;Offline regression + safety rules\"}\n    E -- \"failed\" --&gt; F[\"Reject and leave traces, do not enter runtime\"]\n    E -- \"Pass\" --&gt; G[\"Versioned, traceable staged rollout\"]\n    G --&gt; H[\"Deploy into skill runtime\"]\n    G --&gt; I[\"Keep one-click rollback to the previous version\"]\n    H -.-&gt; A\n</code></pre>\n<p>Note that the two nodes <strong>F and I in this picture are the real design proposition</strong>: any candidate update has a “rejected and left traces” path, and any online version has a “rollback” path. The paper calls this boundary what is necessary to keep long-running robots reproducible and auditable.</p>\n<h4 id=\"27-端到端从图像到工单的证据链\">2.7 End-to-end: Evidence chain from image to work order</h4>\n<p>The inspection and reasoning pipeline is organized according to “observation → interpretation → verification → reporting → review”. OpenClaw selects the image associated with the waypoint, binds the pose, timestamp, waypoint, task ID, applicable inspection strategy, and then calls Qwen3-VL; the returned description is parsed into a <strong>constrained event schema</strong> (hazard category, severity, evidence, location, recommended disposal action). The target categories are divided into two groups - safety category (stacks around the equipment room, occupied fire escapes, water accumulation on the ground, exposed cables) and sanitation category (overflowing trash cans, stains on the ground, scattered garbage and leaves, abnormal accumulation in public areas).</p>\n<p>Only events that pass schema verification will enter the operation pipeline. The system retains the original image, original response of the model, parsed fields, and delivery status. It generates a structured report after labeling the location and area, and routes it to the responsible person for review and dispatch via the DingTalk/Feishu adapter. <strong>Manual corrections are written back in the form of tagged feedback instead of silently overwriting the original results</strong> - which not only ensures that subsequent evaluations and memory updates are informed, but also maintains auditable and replayable records. This design also keeps multimodal reasoning out of safety-critical motion loops.</p>\n<h4 id=\"28-关于训练目标\">2.8 About “Training Objectives”</h4>\n<p>There is no training link in this article. The entire system is assembled from ready-made components. There are no learnable parameters and no loss functions. The only formula in the whole article is the definition of word error rate in the speech experiment:</p>\n\n\\[\\text{WER} = (S + D + I) / N\\]\n\n<p>Here, $S$, $D$, and $I$ are the number of substitution, deletion, and insertion errors respectively, and $N$ is the total number of reference words.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-7\">3. Results and findings</h3>\n<p>System-level measurements deployed in a real residential complex (Table 1):</p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Subsystem</th>\n<th>indicator</th>\n<th>result</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Navigation and Movement</td>\n<td>Task execution</td>\n<td>Waypoint accessibility rate</td>\n<td>100%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Fast-LIO2</td>\n<td>Outdoor positioning error</td>\n<td>&lt; 10 cm</td>\n</tr>\n<tr>\n<td> </td>\n<td>EGO-Planner</td>\n<td>Obstacle response delay</td>\n<td>&lt; 200 ms</td>\n</tr>\n<tr>\n<td>Semantic inspection</td>\n<td>Qwen3-VL</td>\n<td>Garbage overflow detection rate</td>\n<td>95%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Fire exit occupancy detection rate</td>\n<td>95%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Lane occupancy detection rate</td>\n<td>90%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Ground water detection rate</td>\n<td>88%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Qwen3-VL</td>\n<td>Damage detection rate of public facilities</td>\n<td>85%</td>\n</tr>\n<tr>\n<td> </td>\n<td>Inspection reasoning</td>\n<td>Hidden danger false alarm rate/missed detection rate</td>\n<td>All &lt; 5%</td>\n</tr>\n<tr>\n<td>Operation closed-loop</td>\n<td>DingTalk/Feishu Adapter</td>\n<td>Alarm delivery success rate</td>\n<td>99%</td>\n</tr>\n<tr>\n<td> </td>\n<td>HROS report</td>\n<td>Structured report generation accuracy</td>\n<td>99%</td>\n</tr>\n<tr>\n<td>Live operation</td>\n<td>Robot platform</td>\n<td>Continuous battery life</td>\n<td>&gt; 3 h</td>\n</tr>\n<tr>\n<td> </td>\n<td>end-to-end tasks</td>\n<td>Full coverage of single inspection time</td>\n<td>≤ 60 min</td>\n</tr>\n</tbody>\n</table>\n<p>A few points worth noting:</p>\n<ul>\n<li>The detection rate of <strong>decreases regularly with visual categories.</strong>: 95% of garbage overflows and fire escape passages are occupied, and only 85% of public facilities are damaged. The author attributes the diversity of visual forms in the category of facility damage to be much greater than the first two categories - this is consistent with the argument that “hazards are defined by spatial and operational context, rather than just by the identity of the object.”</li>\n<li><strong>has a battery life of 3 hours. For a single mission of 60 minutes, there is room for multiple rounds of</strong>, which is a prerequisite for scheduling.</li>\n<li>The most important thing about <strong>is the part without numbers</strong>: Paper §5.6 wrote a complete controlled experimental protocol for voice interaction, hierarchical memory, and security door self-evolution (WER, grounding intention accuracy, confirmation accuracy, P95 end-to-end delay; Recall@5, spatiotemporal grounding accuracy, context token Reduction rate, stale memory error rate; change in task success rate, regression rate, safety rule violation rate, safety gate rejection rate, rollback success rate, <strong>requires a safety gate escape rate of zero (</strong>), but there are no numbers in these three blocks in Table 1. The original text states that “the values need to be reported after the corresponding controlled test is completed.” In other words, the cognitive runtime of <strong>HROS is currently an architectural proposal and a set of evaluation designs. What is demonstrated is the layer of classic navigation and VLM inspection pipeline</strong> below it.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-7\">4. Limitations</h3>\n<p>The author listed four items: long-term map maintenance (parking patterns, construction, vegetation, and seasonal changes require incremental mapping, change detection, and multi-session map management), open world hazard identification (a wider hazard classification system requires more diverse annotation data, calibration confidence, and ambiguity processing), and agent evaluation and security (memory and self-evolution) Mechanisms need to be specifically benchmarked to measure retrieval quality, adaptation benefits, regression risk and rollback reliability before we can talk about releasing automatic updates in production environments), human-machine collaboration (ASR robustness under outdoor noise, confirmation design of safety-critical instructions, operator load, integration with access control broadcast alarm digital twins).</p>\n<p>One additional sentence that should be taken into account when reading this article: it is a <strong>system and architecture paper</strong>. Navigation and perception all use off-the-shelf open source software. The real novelty lies in the design of inter-layer boundaries and governance processes; and the three most promising pieces of this design (voice grounding, layered memory, and safety gate self-evolution) are still in the protocol stage, and no comparable experimental evidence has yet been provided.</p>\n<hr/>\n<h2 id=\"navharness\">10. NavHarness (2026)</h2>\n<p>———Passing search evidence to fresh navigation sessions to accumulate and revise experience across tasks</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.34276\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.34276</a> · <a href=\"https://github.com/billzhao1030/NavHarness\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a> · <a href=\"https://billzhao1030.github.io\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<p><strong>Navigation index</strong>: <a data-local-language=\"en\" href=\"#/post/vln-papers-extended?section=navharness\">NavHarness in the extended VLN collection</a>.</p>\n<hr/>\n<h3 id=\"精华-8\">Key takeaways</h3>\n<p>NavHarness offers a transferable idea: keep maps, searched places, evidence-backed conclusions, and remaining search options outside the conversation so that a fresh reasoning session can continue the work.\nDuring recovery, the robot stays in place and retains its remaining budget; only the conversation changes and the search plan is reconsidered, with the handover distinguishing a visited place from one ruled out by evidence.\nMemory access is interleaved with observation and action, allowing the model to investigate earlier records and revise conclusions using new views rather than retrieving only at the start.\nIndependent pre-stop verification gives the current search one opportunity to correct its stopping decision, while post-stop certification improves the record inherited by the next task.\nContinuous-deployment experiments further show that, even after maps and task records are retained, organizing experience into source-linked house knowledge brings additional benefits, although incorrect certification can propagate through memory.</p>\n<hr/>\n<h3 id=\"1-研究背景问题-8\">1. Background and problem</h3>\n<p>General-purpose multimodal models can already use observation and movement tools for individual navigation tasks, but a household robot must receive new goals from the previous task’s endpoint and reuse explored space and search experience.\nA longer conversation can retain outdated goals and observations, while a fresh conversation loses searched regions, unchecked places, and failure leads; navigation therefore needs a mechanism that preserves evidence across sessions while allowing earlier conclusions to be reexamined.\nThe paper studies continuous navigation without navigation-specific training, with language, object-category, or image goals, focusing on how experience crosses task, recovery-attempt, and run boundaries.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-8\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/NavHarness-execution-flow.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: NavHarness execution flow: navigation sessions, recovery handovers, pre-stop verification, and post-stop certification</a>\n<figcaption>Original Figure 2: the outer orchestrator advances navigation sessions and handles recovery, pre-stop verification, post-stop certification, and memory retention. One task can involve multiple sessions sharing the same task budget.</figcaption>\n</div>\n<p><strong>① Overall framework: the reasoning session searches, while the outer orchestrator manages handovers.</strong></p>\n<p>NavHarness combines a multi-turn multimodal navigation session, external spatial and task memory, a task-boundary orchestrator, and separate verification and consolidation sessions.\nThe navigation session reads goals and memory, observes the environment, and invokes tools; the orchestrator decides whether to continue, replace the conversation, or close the task while retaining physical state and external records.</p>\n<p>The paper calls a sequence of tasks in one house a <strong>run</strong>, the pursuit of one goal a <strong>task</strong>, and a continuous search for that goal an <strong>attempt</strong>, supported by one <strong>session</strong>. The orchestrator advances a session in <strong>hops</strong>, each a bounded block of model interactions; multiple hops can belong to the same conversation.</p>\n<p><strong>② Memory tiers: changing the conversation does not mean forgetting the house.</strong></p>\n<p>The three tiers can be understood as information in the current conversation, a working archive shared by tasks, and house notes available to later runs.\nA new task receives its goal and references to available files; the navigation session first reads the previous task’s handover, the task index, and house notes, then opens detailed records as the search develops to determine subsequent observations and actions.\nThis preserves experience without inserting every earlier conversation wholesale into the new prompt.</p>\n<table>\n<thead>\n<tr>\n<th>Memory tier</th>\n<th>What it stores</th>\n<th>Who updates it and when it is used</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Active context</td>\n<td>Current goal, reasoning, observations, and retrieved information</td>\n<td>Maintained by the navigation session; replaced at task closure or recovery</td>\n</tr>\n<tr>\n<td>Working memory</td>\n<td>Per-floor occupancy grids, named places and photographs, task index, handovers, and checking records</td>\n<td>Continuously recorded by navigation tools and the orchestrator; reused across tasks and attempts</td>\n</tr>\n<tr>\n<td>Long-term memory</td>\n<td>House index, overview, room notes, navigation skills, and separately saved maps and place records</td>\n<td>The four textual notes are updated only by consolidation; later runs read them again</td>\n</tr>\n</tbody>\n</table>\n<p><strong>The tiers describe use and lifetime, rather than three disjoint databases.</strong> A map can serve as working memory in the current run and be saved for reuse in the next; consolidating textual notes neither converts the map into text nor changes its geometry.\nThe <strong>ledger</strong> indexes each closed task’s goal, status, and named places, while detailed handovers and verdicts remain in separate files for source-level investigation. A navigation session can read earlier tasks but cannot overwrite their records, the orchestrator’s verdicts, or house notes.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/NavHarness-memory-reuse.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: NavHarness reuses experience across navigation tasks through working memory and house knowledge</a>\n<figcaption>Original Figure 1: maps, places, and search experience from task 1 are read again by the fresh session for task 2. Memory access, observation, and action jointly form a closed loop.</figcaption>\n</div>\n<p><strong>③ Spatial tools and online search: remembering where to go also requires knowing how to get there.</strong></p>\n<p>The spatial module receives RGB-D observations, estimates pose with <strong>ORB-SLAM3</strong>, and projects depth into per-floor occupancy grids representing known free space, obstacles, and unexplored areas.\nThe navigation session uses <code class=\"language-plaintext highlighter-rouge\">get_map</code> to inspect the map, <code class=\"language-plaintext highlighter-rouge\">mark</code> to save named places with photographs from at most four headings, and <code class=\"language-plaintext highlighter-rouge\">preview_path</code> to run A* through known free cells and inspect the route and its length. A route preview does not automatically move the robot; the session still chooses the next action.\nMap updates pause when tracking is lost to avoid writing unreliable poses into spatial memory. Robot positions, markers, and routes use SLAM estimates rather than simulator ground-truth poses.</p>\n<p>The execution module receives lists of forward 0.25 m or left/right 15° actions and returns new observations, collisions, and remaining budget; each <code class=\"language-plaintext highlighter-rouge\">step</code> accepts at most 12 actions.\nEach coarse action is split into five 0.05 m or 3° sub-motions to provide sufficiently continuous images for SLAM. This is the shared motion interface, rather than an additional learned low-level navigation policy.\nThe session alternates observations, map queries, record access, and movement. When a house note conflicts with the current view, it can inspect the original record and supply evidence for correction.</p>\n<p><strong>④ Structured recovery handovers: telling the next attempt which searches remain worth pursuing.</strong></p>\n<p>Recovery lets a fresh conversation reconsider the plan while inheriting evidence from the preceding search.\nA session can request recovery, or a configured turn threshold can trigger assessment; the orchestrator considers exploration progress, tracking status, and earlier attempts before approving recovery and selecting whether location, route, floor, or house interpretation needs reassessment.\nThe outgoing session then writes a <strong>recovery note</strong> with movement disabled. Its search observations and process become a handover containing searched places, evidence-supported exclusions, a reliable landmark, untried options, and uncertainties. The fresh session reads it and continues the same goal from the current physical location.</p>\n<blockquote>\n<p><strong>Minimal example, for explanation rather than experimental data:</strong> while looking for a mirror, the old session enters a bathroom and inspects only the wall above the basin; it has not checked behind the door.\nWriting “no mirror found in the bathroom” can incorrectly suggest that the entire room has been ruled out. A structured handover instead records “basin wall checked, target absent; behind the door unchecked and still worth searching.”\nIf the task started with 500 steps and used 420, recovery leaves 80 steps. The new session receives neither another 500 steps nor a reset to the initial robot position.</p>\n</blockquote>\n<p>The controlled GOAT-Bench experiments use 500 movement or turning actions and 200 navigation-model turns per task, with at most one recovery and an 80-turn fallback threshold. Observation and memory tools have no movement-step charge, and recovery shares both remaining task allowances.</p>\n<p>When location needs reassessment, a separate <strong>wake-up session</strong> compares surrounding views with saved place photographs and supplies a location brief to the fresh navigator.\nRecognizing a familiar room differs from recovering metric alignment with the map: the former supplies semantic orientation, while the latter still depends on SLAM. Recovery itself neither moves the robot nor clears stored observations.</p>\n<p><strong>⑤ Two-stage completion checks: correcting the current stop and improving later memory.</strong></p>\n<p>Before ending its search, the navigator writes a <strong>task handover</strong> covering the goal, searched places, outcome evidence, and unfinished searches, then supplies its own completion assessment.\nA separate judge session receives the goal, four views at the stopping location, sampled earlier images, the map, and execution records, using at most 12 frames. It sees neither the navigation conversation nor the navigator’s self-assessment, has no tools, and returns an evidence-backed <code class=\"language-plaintext highlighter-rouge\">complete</code>, <code class=\"language-plaintext highlighter-rouge\">incomplete</code>, or <code class=\"language-plaintext highlighter-rouge\">unknown</code> verdict.\nBy default, all roles use the same model; the conversations and evidence interfaces are separate, which does not make navigator and judge errors independent.</p>\n<table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>When it runs</th>\n<th>Its effect</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Pre-stop verification</td>\n<td>Before STOP</td>\n<td>A definite verdict contradicting the navigator’s claim on the first check returns counter-evidence to the current session, allowing further search</td>\n</tr>\n<tr>\n<td>Post-stop certification</td>\n<td>After the task actually ends</td>\n<td>Records the final assessment for later tasks without changing the completed task’s score</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Each task receives only one pre-stop correction opportunity, and recovery does not reset it.</strong> An <code class=\"language-plaintext highlighter-rouge\">unknown</code> verdict permits closure, and a repeated closure request is honored. If the action-step count does not change between the checks, certification reuses the previous verdict.\nThe orchestrator keeps the navigator’s completion claim separate from the judge’s verdict and reserves environment truth for evaluation. Certification is therefore not ground truth, nor does a certified goal validate every spatial description in the handover.</p>\n<p><strong>⑥ Cross-run consolidation: retaining detailed records while creating accessible knowledge entry points.</strong></p>\n<p>At run end, a separate <strong>consolidation session</strong> reads the ledger, handovers, and existing house notes. Using file tools, it organizes routes, failed searches, corrections, and open questions into four updated files: the index, house overview, room notes, and navigation skills.\nIt can write only these house notes, has no navigation tools, and cannot change the map or overwrite source task records. Skills must be supported by the journal, and notes should preserve sources and distinguish certified outcomes from the navigator’s interpretations, although these content requirements still depend on the model following instructions.\nThe next run can read the overview for search guidance and open detailed records when needed, preventing failure leads omitted by consolidation from becoming permanently inaccessible.</p>\n<p><strong>⑦ End-to-end flow and training objective.</strong></p>\n<p>A task follows “goal and file references → read memory → observe, query, and act → write a recovery handover and replace the conversation when needed → request closure and verification → STOP and certification → update the ledger and save spatial state.” Consolidation runs after the full task sequence ends.\nIn benchmark evaluations, memory carries only within the same GOAT-Bench episode or IR2R-CE tour; every new episode or tour starts with empty memory. Cross-run house-knowledge reuse is evaluated separately through continuous deployment.</p>\n<p><strong>No model parameters are updated, and no new navigation training loss is introduced.</strong> Consolidation updates external notes, as expressed in the paper’s Equation (11):</p>\n\n\\[D_h^{+}=C_\\theta(D_h,L_K).\\]\n\n<p>Here, $D_h$ denotes existing house notes, $L_K$ the task-sequence records, and $C_\\theta$ a consolidation model with fixed parameters. It produces notes for later inference rather than writing experience into model weights through gradients.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-8\">3. Results and findings</h3>\n<p><strong>Evaluation scope.</strong> GOAT-Bench Val-Unseen contains 36 scenes, 360 episodes, and 2,669 subtasks; IR2R-CE also uses Val-Unseen.\n<strong>s-SR</strong> measures individual-task success, <strong>e-SR</strong> the fraction of sequences with every task completed, and <strong>SPL</strong> combines success with path efficiency. The table uses the three-seed means from Tables 1 and 2, with success gains in percentage points.</p>\n<table>\n<thead>\n<tr>\n<th>Dataset and reasoning model</th>\n<th style=\"text-align: right\">Independent-session s-SR</th>\n<th style=\"text-align: right\">NavHarness s-SR</th>\n<th style=\"text-align: right\">s-SR gain</th>\n<th style=\"text-align: right\">NavHarness SPL</th>\n<th style=\"text-align: right\">NavHarness e-SR</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>GOAT-Bench · Qwen3.8-27B</td>\n<td style=\"text-align: right\">41.4%</td>\n<td style=\"text-align: right\">71.7%</td>\n<td style=\"text-align: right\">+30.3</td>\n<td style=\"text-align: right\">48.2</td>\n<td style=\"text-align: right\">14.4%</td>\n</tr>\n<tr>\n<td>GOAT-Bench · GPT-4o</td>\n<td style=\"text-align: right\">43.5%</td>\n<td style=\"text-align: right\">78.3%</td>\n<td style=\"text-align: right\">+34.8</td>\n<td style=\"text-align: right\">57.1</td>\n<td style=\"text-align: right\">26.9%</td>\n</tr>\n<tr>\n<td>GOAT-Bench · Opus 5</td>\n<td style=\"text-align: right\">58.9%</td>\n<td style=\"text-align: right\">81.5%</td>\n<td style=\"text-align: right\">+22.6</td>\n<td style=\"text-align: right\">55.0</td>\n<td style=\"text-align: right\">28.6%</td>\n</tr>\n<tr>\n<td>GOAT-Bench · GPT-6 Astra</td>\n<td style=\"text-align: right\">65.1%</td>\n<td style=\"text-align: right\"><strong>83.7%</strong></td>\n<td style=\"text-align: right\">+18.6</td>\n<td style=\"text-align: right\"><strong>62.3</strong></td>\n<td style=\"text-align: right\"><strong>36.9%</strong></td>\n</tr>\n<tr>\n<td>IR2R-CE · GPT-6 Astra</td>\n<td style=\"text-align: right\">68.4%</td>\n<td style=\"text-align: right\"><strong>85.9%</strong></td>\n<td style=\"text-align: right\">+17.5</td>\n<td style=\"text-align: right\"><strong>76.1</strong></td>\n<td style=\"text-align: right\"><strong>27.8%</strong></td>\n</tr>\n</tbody>\n</table>\n<p>GPT-6 Astra’s IR2R-CE t-nDTW rises from 56.8 to 64.2; the paper reports that its results exceed the previous methods in both benchmark tables.\nUnder the 278-subtask protocol used by some prior methods, the GPT-4o version achieves 77.6% s-SR, compared with HIMM’s 72.8% and 3D-Mem’s 69.1%. Its 78.3% full-split result should not be treated as the same evaluation scope.\n<strong>Gains over independent sessions include the full system—mapping, recovery, and completion checks—and cannot all be attributed to memory.</strong> Controls with matched models and task budgets provide more specific evidence about the mechanisms.</p>\n<p><strong>Cross-task memory and recovery evidence, using Opus 5 on the full benchmark.</strong></p>\n<table>\n<thead>\n<tr>\n<th>Control</th>\n<th style=\"text-align: right\">s-SR</th>\n<th style=\"text-align: right\">Change from full NavHarness</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Full NavHarness</td>\n<td style=\"text-align: right\">81.5%</td>\n<td style=\"text-align: right\">—</td>\n</tr>\n<tr>\n<td>One long conversation for all tasks</td>\n<td style=\"text-align: right\">54.9%</td>\n<td style=\"text-align: right\">−26.6 percentage points</td>\n</tr>\n<tr>\n<td>No cross-task memory, with within-task mechanisms retained</td>\n<td style=\"text-align: right\">66.8%</td>\n<td style=\"text-align: right\">−14.7 percentage points</td>\n</tr>\n<tr>\n<td>Clear the map after each task, keep task records</td>\n<td style=\"text-align: right\">68.9%</td>\n<td style=\"text-align: right\">−12.6 percentage points</td>\n</tr>\n<tr>\n<td>Hide earlier task records, keep the map</td>\n<td style=\"text-align: right\">71.8%</td>\n<td style=\"text-align: right\">−9.7 percentage points</td>\n</tr>\n<tr>\n<td>No recovery, unchanged task budget</td>\n<td style=\"text-align: right\">71.1%</td>\n<td style=\"text-align: right\">−10.4 percentage points</td>\n</tr>\n<tr>\n<td>Recovery with a length-matched ordinary summary</td>\n<td style=\"text-align: right\">73.2%</td>\n<td style=\"text-align: right\">−8.3 percentage points</td>\n</tr>\n<tr>\n<td>No pre-stop verification</td>\n<td style=\"text-align: right\">76.1%</td>\n<td style=\"text-align: right\">−5.4 percentage points</td>\n</tr>\n<tr>\n<td>No post-stop certification</td>\n<td style=\"text-align: right\">79.0%</td>\n<td style=\"text-align: right\">−2.5 percentage points</td>\n</tr>\n</tbody>\n</table>\n<p>The ordinary-summary and structured-handover conditions use the same recovery triggers and budgets; their 8.3-point difference supports the value of how handover information is organized.\nThese interventions remove different mechanisms with interacting effects, so their losses cannot be summed into component contributions. Removing all cross-task memory, for example, has a smaller loss than the sum of removing maps and records separately.</p>\n<p><strong>Agent-directed memory access has its own control.</strong> Appendix Table 12 retains the same initial memory, mapping, record writing, recovery, and completion checks, but replaces historical-text access with scheduled BM25 retrieval: at task start, after recovery, and every 10 navigation turns, it supplies at most 5 original excerpts within 2,000 tokens.\nAllowing the model to choose when and what to retrieve and to pursue follow-up queries raises s-SR from 74.5% to 81.5%, a paired gain of <strong>+7.0 percentage points, 95% CI [+5.9, +8.2]</strong>, and SPL from 49.0 to 55.0. This control changes timing, selection, and follow-up together, so it does not isolate the superiority of one retrieval algorithm.</p>\n<p><strong>Certification improves record accuracy without becoming ground truth.</strong> In Appendix Table 16, among claimed completions, four-view certification agrees with environment truth on 90.7%, compared with 82.6% for accepting every claim. False completions still accepted account for 5.2% of all completion claims, and true completions incorrectly rejected account for 4.1%.</p>\n<p><strong>Continuous deployment: consolidation adds value beyond retained maps and task records.</strong></p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vln/NavHarness-continuous-deployment.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: NavHarness continuous deployment across 36 houses with a control disabling experience consolidation</a>\n<figcaption>Original Figure 3: continuous deployment with Opus 5 across 36 houses. Both conditions retain maps and task records; only run-end consolidation differs. The curves show performance over task progress, with pooled scores and paired gains on the right.</figcaption>\n</div>\n<p>The authors concatenate 10 GOAT-Bench tours per house, relocate the robot to prescribed starts at tour boundaries to model resumption after shutdown, and keep mapping and task-record retention, recovery, verification, and budgets fixed while disabling consolidation in the control.\nConsolidation raises pooled s-SR from <strong>72.8% to 80.5%</strong>, a paired gain of <strong>+7.7 percentage points, 95% CI [+6.3, +9.1]</strong>; SPL rises from <strong>36.5 to 44.3</strong>, a gain of <strong>+7.8, 95% CI [+6.5, +9.2]</strong>.\n<strong>Memory can prompt additional evidence gathering or misdirect a search.</strong> In Appendix Case 10, house notes retain the open question of whether two refrigerator descriptions refer to the same appliance. After completing its task, the navigator inspects both sides, records the answer, and passes it through consolidation to help a later task recognize a dark goal photograph.\nCase 14 shows the opposite risk: a note mentioning only one mirror initially misleads the session. After recovery, it reexamines the goal image and retrieves a failed task’s lead about an unchecked location behind a door. The search succeeds, but its SPL is 0.08, below the no-consolidation control’s 0.38.\nThese cases explain recorded decisions rather than estimating the frequency of mechanisms across houses; the entire step difference between conditions cannot be attributed to a single note.</p>\n<hr/>\n<h3 id=\"4-局限性-8\">4. Limitations</h3>\n<p>The evaluations cover static scanned scenes and finite task sequences, without testing long-term adaptation on real robots or under object motion and layout changes. SLAM drift, cross-run coordinate misalignment, and loop-closure corrections not propagated into existing occupancy cells can undermine old-map reuse, while repeated large-model calls introduce substantial latency.\nThe judge can still accept false completions or reject true ones, incorrect records can become consolidated house knowledge, and goal certification does not validate every spatial or procedural description. The system also requires sufficiently capable multi-turn multimodal reasoning; the tested Qwen3.5-4B and 9B models struggle with this navigation setting.</p>\n<hr/>\n<h2 id=\"supernav\">11. SuperNav (2026)</h2>\n<p>———A general navigation agent organized through navigation skills, visual-point tools, and context management</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.12126\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.12126</a> · <a href=\"https://zju3dv.github.io/SuperNav/\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<p>SuperNav is an embodied-agent harness evaluated primarily through navigation. A general-purpose MLLM interprets requests and selects destinations, while readable Navigation Skills, visual-point tools, goal-progress records, and context management organize search, target rechecking, and failure recovery into a continuing loop; geometric or learned motion backends execute the movements. Its transferable idea is how skills, tools, and execution feedback sustain physical interaction, making it relevant to embodied-agent frameworks. The decision-making MLLM receives no navigation-specific fine-tuning, while the learned executor is trained on navigation trajectories.</p>\n<p><strong>Full analysis and experimental results</strong>: <a data-local-language=\"en\" href=\"#/post/vln-papers-extended?section=supernav\">SuperNav: methods, evaluation protocols, and performance comparisons in the extended VLN collection</a>.</p>\n<hr/>\n<h2 id=\"vista\">12. VISTA (2026)</h2>\n<p>———Giving a multimodal model eyes that can replay and zoom: lossless visual memory plus model-directed visual inspection</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.02200\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.02200</a> · <a href=\"https://github.com/joshhhhhan/VISTA\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<p><strong>Why it is included</strong>: VISTA is evaluated in interactive visual games rather than on robots, but it addresses this collection’s shared question: leave the model unchanged, change only the harness, and let a general-purpose multimodal model retain and revisit visual evidence on demand during long-horizon interaction. The authors also name embodied tasks as the next step.</p>\n<hr/>\n<h3 id=\"精华-9\">Key takeaways</h3>\n<ul>\n<li><strong>The bottleneck is often not model capability but how the harness feeds information</strong>: the same Claude Opus 5.0 scores only 40.68 RHAE on ARC-AGI-3 with the organizers’ minimal harness and 100.00 with VISTA, without any training.</li>\n<li><strong>“Encode once, then discard the raw image” is a hidden ceiling for multimodal agents</strong>: at encoding time the model cannot know which details will matter later. Archiving every original frame and letting the model revisit frames during reasoning amounts to an <strong>explicit, addressable form of attention</strong>.</li>\n<li><strong>Observe images rather than text grids</strong>: a 64×64 grid costs about 4K tokens as text but only about 308 tokens as a 512×512 rendered image. Performance stays comparable or improves, and token usage per game drops from 71.9M to 30.7M.</li>\n<li><strong>Make read-only tools free and actions costly</strong>: <code class=\"language-plaintext highlighter-rouge\">inspect</code> and <code class=\"language-plaintext highlighter-rouge\">read_pixels</code> consume no game actions; only <code class=\"language-plaintext highlighter-rouge\">play</code> counts. This encourages the model to look carefully before acting, and it ends up using 57.4% fewer actions than first-time human players.</li>\n<li><strong>Simplicity transfers</strong>: the same harness, with an almost identical short prompt, carries over to GameWorld, AI GameStore, and BabyVision and clearly outperforms the official baselines using the same model on all three.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-9\">1. Background and problem</h3>\n<p>ARC-AGI-3 is a suite of interactive visual games that <strong>provide neither rules nor goals</strong>: the agent must discover through probing which object is the player, what a click does, and what counts as winning. Most high-scoring methods convert the screen into numeric grids and have an LLM write programs that form an executable world model (program synthesis), which scales poorly as visuals grow complex. Approaches that use a VLM directly suffer from two problems: each image is encoded once, so details may be lost in compression, and during long interactions early observations are truncated or replaced by text summaries once the context fills. The paper asks: <strong>without writing programs, relying only on vision and natural-language reasoning, can the right harness push a general-purpose multimodal model to a perfect score?</strong></p>\n<hr/>\n<h3 id=\"2-主要方法创新点-9\">2. Methods and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-agent-design-comparison.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Comparison of language agents, conventional multimodal agents, and VISTA</a>\n<figcaption>Three agent designs: (a) a language agent sees only text; (b) a conventional multimodal agent encodes each image once and never looks back; (c) VISTA can repeatedly call visual tools before each action, retrieving past frames and reorganizing its own visual input</figcaption>\n</div>\n<p><strong>① Overall framework</strong></p>\n<p>VISTA is not a new model but a <strong>purely mechanical harness with no trained parameters</strong>. It consists of three visual components—<strong>visual observations</strong>, <strong>lossless visual memory</strong>, and <strong>visual inspection tools</strong>—plus two <strong>note files</strong> (<code class=\"language-plaintext highlighter-rouge\">GUIDE.md</code> / <code class=\"language-plaintext highlighter-rouge\">WORKING.md</code>). The harness executes tool calls and returns images or pixel values; all understanding, reasoning, and decision-making is left to the underlying multimodal model (Claude Opus 5.0, GPT-5.6 Sol, or GLM-5.3 Flash) within one multi-turn conversation.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-components-and-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: VISTA components and per-turn pipeline on ARC-AGI-3</a>\n<figcaption>VISTA's core components and per-turn pipeline (ARC-AGI-3 example): (a) observations change from a 64×64 digit grid to a rendered image; (b) every returned frame is archived at full resolution and addressable by turn and frame number; (c) the model can magnify any region in space and retrieve several past frames across time; (d) each turn follows observe → reason → act, where reading and writing notes and inspecting memory are optional and only acting consumes an action</figcaption>\n</div>\n<p><strong>② Module by module</strong></p>\n<p><strong>Visual observation</strong></p>\n<ul>\n<li><strong>Input</strong>: the current environment state. ARC-AGI-3 officially provides a 64×64 integer grid in which each cell is a color index.</li>\n<li><strong>Processing</strong>: 8× nearest-neighbor upscaling into a 512×512 PNG, so each cell becomes a solid block of pixels.</li>\n<li><strong>Output</strong>: one image plus the list of currently available actions.</li>\n<li><strong>Motivation</strong>: images preserve object appearance and spatial relations, so the model can apply visual priors learned in pretraining (“this is a wall”, “these two objects are symmetric”) instead of assembling shapes from 4,096 numbers; token cost also drops sharply (see sticking point ② below).</li>\n</ul>\n<p><strong>Lossless visual memory</strong></p>\n<ul>\n<li><strong>Input</strong>: <strong>every frame</strong> the environment returns, including all intermediate animation frames triggered by an action (clicking a block, for example, returns six frames).</li>\n<li><strong>Processing</strong>: frames are archived unchanged, indexed by <code class=\"language-plaintext highlighter-rouge\">(turn, frame)</code>, and fully decoupled from whatever remains in the model’s context.</li>\n<li><strong>Output</strong>: a frame store that can be addressed at any time (one example game had accumulated 1,472 frames).</li>\n<li><strong>Motivation</strong>: the usual approach encodes once and truncates or summarizes once the context fills, but the model cannot predict at encoding time which details will become critical. Keeping original images <strong>outside</strong> the context means compressing the context no longer destroys visual evidence.</li>\n</ul>\n<p><strong>Visual inspection</strong></p>\n<p>This interface brings the memory to life; the model decides on its own when to use it and where to look:</p>\n<ul>\n<li><code class=\"language-plaintext highlighter-rouge\">inspect(question, views)</code>: <strong>in space</strong>, crops and magnifies any rectangle of any frame (the paper’s example magnifies about 13× to tell which way small blocks face); <strong>across time</strong>, retrieves frames from several past turns in one call for comparison, or replays the animation of an action frame by frame.</li>\n<li><code class=\"language-plaintext highlighter-rouge\">read_pixels(question, views)</code>: splits a region into a grid and returns exact RGB values per cell, for judgments the eye easily gets wrong, such as whether two colors are actually identical.</li>\n<li>Every call must include a <code class=\"language-plaintext highlighter-rouge\">question</code>, forcing the model to state what the look is meant to settle.</li>\n<li><strong>Key design</strong>: inspection tools <strong>consume no game actions</strong>; only <code class=\"language-plaintext highlighter-rouge\">play</code> counts.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-visual-memory-usage.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Model-directed use of visual memory across time and for local details</a>\n<figcaption>Two ways the model directs its use of visual memory: (a) inspection across space and time—after the board resets, a single inspect call retrieves four frames from the preceding 22 turns to reconstruct the full map; (b) inspection of local details—magnifying three small blocks about 13× reveals which side carries the purple marker, identifying each guard's orientation</figcaption>\n</div>\n<p><strong>Note files (GUIDE.md / WORKING.md)</strong></p>\n<ul>\n<li><code class=\"language-plaintext highlighter-rouge\">GUIDE.md</code>: a rulebook that stays valid across levels and contexts (for example, “clicking an orange block turns it into an X marker; clicking the X recreates the block”).</li>\n<li><code class=\"language-plaintext highlighter-rouge\">WORKING.md</code>: a scratchpad for the current level, cleared when the level advances.</li>\n<li>When the context nears its limit, the agent writes a handoff summary to <code class=\"language-plaintext highlighter-rouge\">WORKING.md</code> and resumes in a fresh context; notes, visual memory, and action history are all retained.</li>\n</ul>\n<p><strong>③ End-to-end data flow</strong></p>\n<p>Within one turn, the model may exchange several messages with the harness but executes only one game action. The reader’s version of a single turn:</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Receive current frame + available actions\"] --&gt; B[\"Read GUIDE.md / WORKING.md (optional)\"]\n    B --&gt; C[\"Natural-language reasoning: hypothesize rules, predict outcome\"]\n    C --&gt; D{\"Enough evidence?\"}\n    D -- \"No\" --&gt; E[\"inspect / read_pixels to revisit memory (free)\"]\n    E --&gt; C\n    D -- \"Yes\" --&gt; F[\"Update notes (optional)\"]\n    F --&gt; G[\"play executes one action (the only counted step)\"]\n    G --&gt; H[\"All returned frames stored in lossless visual memory\"]\n    H --&gt; I[\"Last frame becomes next turn's observation\"]\n    I --&gt; A\n</code></pre>\n<p>The prompt is minimal, with four core sentences: finish the game in as few actions as possible; build and keep revising a compact model of the game; before each <code class=\"language-plaintext highlighter-rouge\">play</code>, state the expected result and afterwards state every visible change; write durable understanding into <code class=\"language-plaintext highlighter-rouge\">GUIDE.md</code>. This “predict, then compare” pattern turns the model into an online hypothesis tester.</p>\n<blockquote>\n<p><strong>Sticking point ① — why not just put every frame in the context? An example</strong>: the official implementation automatically feeds up to 7 frames per action. As text grids, each frame costs about 4K tokens, so observations alone take about 28K tokens per request; even as images (about 308 tokens per frame, about 2.2K total), 300 steps accumulate roughly 650K tokens and eventually overflow a 200K context and get truncated. VISTA does the opposite: each turn it <strong>automatically provides only the last frame</strong> (about 308 tokens) and keeps all other frames in a store outside the context, recalling 1–4 frames precisely with <code class=\"language-plaintext highlighter-rouge\">inspect</code> when needed. The context holds the images the model currently considers relevant rather than the images that happened most recently—this is what the paper calls “explicit attention”.</p>\n</blockquote>\n<p><strong>④ Training objective / loss function</strong></p>\n<p>None. VISTA requires no training; all gains come from harness design, and the underlying models are called as-is through closed-source CLIs (Claude Code / Codex) or with open weights.</p>\n<p><strong>⑤ Evaluation metric: RHAE (sticking point ②)</strong></p>\n<p>ARC-AGI-3 uses <strong>Relative Human Action Efficiency (RHAE)</strong> to measure how many actions you save compared with first-time human players. Let $h$ be the human baseline action count for a level (the upper median among first-time players who completed it) and $a$ the agent’s action count. The level score is</p>\n\n\\[S_{\\ell,g} = \\min\\left(1.15,\\ \\left(\\frac{h_{\\ell,g}}{a_{\\ell,g}}\\right)^2\\right)\\]\n\n<p>Unfinished levels score 0. A game has $n$ levels, with level $\\ell$ weighted $w_\\ell = \\ell$ (later levels matter more); if only the first $k$ levels are completed, the game score is the smaller of the weighted average level score and the weighted completion fraction:</p>\n\n\\[S_g = \\min\\left(\\frac{\\sum_{\\ell=1}^{k} w_\\ell}{\\sum_{\\ell=1}^{n} w_\\ell},\\ \\frac{\\sum_{\\ell=1}^{n} w_\\ell S_{\\ell,g}}{\\sum_{\\ell=1}^{n} w_\\ell}\\right)\\]\n\n<blockquote>\n<p><strong>An example</strong>: a game has 2 levels with weights 1 and 2. Level 1: humans take 32 actions, the agent 16 → $(32/16)^2=4$, capped at 1.15. Level 2: humans take 40, the agent 50 → $(40/50)^2=0.64$.\nBoth levels cleared: weighted average $(1.15\\times1 + 0.64\\times2)/3 = 0.81$, completion fraction $3/3=1$, take the smaller → <strong>0.81</strong>.\nOnly level 1 cleared: weighted average $1.15/3 = 0.38$, completion fraction $1/3=0.33$, take the smaller → <strong>0.33</strong>.\nThe square makes extra actions costly, and a score of 100 means <strong>every game is completed with overall weighted efficiency no worse than humans</strong>—actions saved elsewhere can offset a few over-long levels within the 1.15 cap.</p>\n</blockquote>\n<p><strong>⑥ Differences from the official baseline (sticking point ③)</strong></p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Official minimal harness</th>\n<th>VISTA</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Observation format</td>\n<td>64×64 text digit grid</td>\n<td>512×512 rendered image</td>\n</tr>\n<tr>\n<td>History retention</td>\n<td>175K sliding window; the oldest turns are dropped</td>\n<td>All frames archived losslessly outside the context, retrievable by turn and frame number</td>\n</tr>\n<tr>\n<td>Automatic input per step</td>\n<td>Up to 7 intermediate frames</td>\n<td>Only 1 frame (the last); the model inspects the rest on demand</td>\n</tr>\n<tr>\n<td>Long-term knowledge</td>\n<td>None</td>\n<td><code class=\"language-plaintext highlighter-rouge\">GUIDE.md</code> + <code class=\"language-plaintext highlighter-rouge\">WORKING.md</code>, preserved across context restarts</td>\n</tr>\n</tbody>\n</table>\n<hr/>\n<h3 id=\"3-核心结果发现-9\">3. Key results and findings</h3>\n<p><strong>ARC-AGI-3 (25 public games)</strong>: VISTA + Claude Opus 5.0 (xhigh) reaches <strong>RHAE 100.00</strong> with 7,302 actions in total, 57.4% fewer than first-time humans (17,135). VISTA + GPT-5.6 Sol (max) also completes all 25 games, with RHAE 99.00 (99.04 ± 0.17 over three runs). The same models score only 40.68 and 13.33 under the official implementation. To the authors’ knowledge, this is the <strong>first system to reach perfect or near-perfect performance without program synthesis</strong>, matching program-synthesis systems such as Tycho (100.00) and Retrodict (99.86).</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-harness-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: ARC-AGI-3 ablation adding harness components step by step</a>\n<figcaption>Ablation adding harness components step by step (GPT-5.6 Sol): replacing text grids with images 13.33→47.32; relaxing action and time limits 51.66; continuous conversation 65.82; adding the two notes 70.05; adding lossless memory and inspection 94.10 (the largest jump); adding exact pixel readout gives full VISTA at 99.00, with total actions down to 9,126</figcaption>\n</div>\n<p><strong>Key reading of the component ablation</strong>: the largest jump comes from lossless memory plus inspection (70.05 → 94.10, +24), while actions fall from 23,702 to 12,261—once it can look back, the model wastes far fewer blind trials.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-text-vs-image.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Text-grid versus image observations on ARC-AGI-3</a>\n<figcaption>Observation formats compared: under the same harness, image observations (99.00) perform on par with text grids (96.75) while using fewer actions (9,126 vs 10,614) and less than half the tokens per game (30.7M vs 71.9M)</figcaption>\n</div>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-context-and-scale-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Ablations on maximum context size and input image scale</a>\n<figcaption>Context length and input resolution ablations: (a) a 200K context is best (99.0); 100K loses only 0.4 while halving tokens, and 780K does worse while using more than three times the tokens; (b) 4× upscaling (256 pixels, about 77 tokens per frame) matches the default 8×, while 2× is too blurry and 16× wastes context and drops to 88.3</figcaption>\n</div>\n<p><strong>Other findings</strong>:</p>\n<ul>\n<li><strong>A longer context is not always better</strong>: 500K and 780K drop to 94.4 and 93.9, suggesting that inspecting on demand beats keeping everything.</li>\n<li><strong>Open-weight backend</strong>: with GLM-5.3 Flash 320B, the official implementation scores 1.89 → VISTA without inspection tools 13.27 → full VISTA <strong>66.93</strong>, so the visual tools account for most of the gain.</li>\n<li><strong>3D rendering</strong>: rendering the same games in an isometric 3D view still yields RHAE 84.12 (actions rise to 20,640), far above the official text baseline.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/VISTA-general-benchmarks.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: VISTA results on GameWorld, AI GameStore, and BabyVision</a>\n<figcaption>Transfer to other visual environments (GPT-5.6 Sol): GameWorld success rate 63.3% / progress 79.3%, above novice humans (55.3% / 64.1%); AI GameStore geometric mean 140.3, above the human median (100); static BabyVision visual-tracking accuracy 41.0% → 63.2%, still well below humans at 92.3%</figcaption>\n</div>\n<p><strong>Cross-benchmark transfer</strong>: changing only the action interface name (<code class=\"language-plaintext highlighter-rouge\">play</code> → <code class=\"language-plaintext highlighter-rouge\">act</code>) and the task description, the same harness outperforms both the official baselines using the same model and the best previously reported results on all three benchmarks. BabyVision involves no interaction history, so its gain comes purely from zooming into and reading pixels within a single image, showing that the inspection tools have independent value.</p>\n<hr/>\n<h3 id=\"4-局限性-9\">4. Limitations</h3>\n<p>Success depends heavily on the underlying model’s own capabilities; VISTA only draws them out. The models were also released after the public games, so the games may have appeared in their training data; generalization needs further verification on unseen games such as the ARC-AGI-3 private set.</p>\n<hr/>\n<h2 id=\"race\">13. RACE (2026)</h2>\n<p>———When should an agent think? Use the drop in action likelihood to judge whether earlier reasoning still suffices</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.12061\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.12061</a> · <a href=\"https://github.com/HututuAI/RACE\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<p><strong>Why it is included</strong>: RACE is evaluated on text and API interaction tasks rather than on robots, but it addresses a cost problem shared by every long-horizon closed-loop agent: reasoning at every turn is expensive, so how long does earlier reasoning remain sufficient, and when is fresh reasoning needed? Its cross-turn reasoning-cover criterion and training recipe transfer directly to the multi-turn decisions of embodied agents.</p>\n<hr/>\n<h3 id=\"精华-10\">Key takeaways</h3>\n<ul>\n<li>Reasoning has a shelf life: a plan formed at one turn often supports several later actions, so there is no need to think again at every turn. The real question is not “can this turn skip reasoning?” but “how far does existing reasoning still reach?”</li>\n<li>Replace expensive verification with a cheap proxy: instead of regenerating actions for every candidate context, a single teacher-forced pass that measures how much the reference action’s likelihood drops is enough to approximate whether the action can still be recovered.</li>\n<li>Deleting a reasoning step must be judged by its effect on <strong>all later actions</strong>, not only the current one. This is the fundamental difference between cross-turn estimation and earlier per-turn, independent decisions.</li>\n<li>The same labeler (LoGiC) builds SFT data offline and produces RL signals online, so one mechanism spans both training stages. In RL it combines masking with explicitly teaching the model to close <code class=\"language-plaintext highlighter-rouge\">&lt;/think&gt;</code>, rather than tuning the reward.</li>\n</ul>\n<hr/>\n<h3 id=\"1-研究背景问题-10\">1. Background and problem</h3>\n<p>ReAct-style LLM agents reason before every action by default, so reasoning-token cost grows linearly over long trajectories. Existing adaptive-reasoning methods either decide independently at each turn whether to think, ignoring that earlier reasoning can remain effective across several turns, or obtain supervision by generating actions with and without reasoning and comparing them. That cost becomes prohibitive as trajectories grow, and especially in on-policy RL, where it must be repeated for every batch.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-10\">2. Methods and innovations</h3>\n<h4 id=\"21-动机实验推理会跨轮持续生效且似然下降能预测这一点\">2.1 Motivating analysis: reasoning persists across turns, and likelihood drop predicts it</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/RACE-cross-turn-analysis.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Cross-turn reasoning support and the relation between likelihood drop and action recovery</a>\n<figcaption>Cross-turn reasoning support: (a) after removing all reasoning beyond turn s, check whether later actions can still be recovered, giving the persistence span L of the reasoning support; (b) the reference-action likelihood drop d closely tracks the action recovery rate, which exceeds 99% when d ≤ 0.001</figcaption>\n</div>\n<p>Using successful Qwen3.5-9B trajectories on ScienceWorld and WebShop, the authors run two analyses:</p>\n<ul>\n<li><strong>Generation-based measurement (panel a)</strong>: choose a cutoff s, keep the reasoning up to and including turn s, and remove all later reasoning while leaving actions and observations unchanged. At each later turn j, sample K=4 actions and compute the fraction \\(\\mathrm{Rec}_j\\) that recovers the reference action $a_j^*$. Some reasoning supports only one step, while some keeps supporting several later steps (on ScienceWorld, about 11% of reasoning steps support a full 5 steps). The authors call this <strong>cross-turn reasoning persistence</strong>.</li>\n<li><strong>Likelihood-based estimation (panel b)</strong>: compute the mean per-token log-likelihood $\\ell(a_j^* \\mid h)$ of the reference action and compare the full and truncated contexts:</li>\n</ul>\n\n\\[d_j = \\ell(a_j^* \\mid x_j, r_j) - \\ell(a_j^* \\mid \\tilde x_j)\\]\n\n<p>A smaller $d_j$ means the model remains just as confident about the action after the reasoning is removed. Experiments show that $d_j$ and the recovery rate correspond almost monotonically. This replaces “generate many times to verify” with “score once under teacher forcing.”</p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Generation-based verification (prior work)</th>\n<th>Likelihood proxy (this paper)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cost per candidate context</td>\n<td>Autoregressively sample K actions and compare</td>\n<td>One batched teacher-forced scoring pass</td>\n</tr>\n<tr>\n<td>Usable inside on-policy RL</td>\n<td>Must be redone every batch; too expensive</td>\n<td>Cheap enough to run on every rollout batch</td>\n</tr>\n<tr>\n<td>Scope of effect considered</td>\n<td>Usually only the current turn</td>\n<td>The current turn plus every later reference action</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"22-整体框架\">2.2 Overall framework</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/RACE-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Overview of the RACE training approach</a>\n<figcaption>The RACE training framework: the core algorithm LoGiC labels each turn's reasoning as keep (THINK) or remove (SKIP); offline it builds SFT data, and online it drives reasoning masking and reasoning-closure supervision during RL</figcaption>\n</div>\n<p>RACE (Reasoning Adaptation through Cross-Turn Estimation) has three parts. <strong>LoGiC</strong> marks which reasoning steps in a trajectory can be removed. The <strong>SFT stage</strong> uses LoGiC to compress full-reasoning trajectories into “think only when needed” trajectories for supervision. The <strong>RL stage</strong> reruns LoGiC on each batch of successful rollouts, using the result to block gradients on redundant reasoning and to teach the model directly to close its reasoning immediately where it should stop.</p>\n<pre><code class=\"language-mermaid\">graph LR\n    A[\"Full-reasoning trajectories (DeepSeek-V4-Pro)\"] --&gt; B[\"LoGiC offline labeling\"]\n    B --&gt; C[\"Adaptive-reasoning trajectories\"]\n    C --&gt; D[\"RACE-SFT\"]\n    D --&gt; E[\"On-policy rollouts\"]\n    E --&gt; F{\"Trajectory succeeded?\"}\n    F -- \"Yes\" --&gt; G[\"LoGiC labels SKIP turns online\"]\n    G --&gt; H[\"Masked GRPO + reasoning-closure loss\"]\n    F -- \"No\" --&gt; I[\"Standard GRPO\"]\n    H --&gt; J[\"RACE-SFT-RL\"]\n    I --&gt; J\n</code></pre>\n<h4 id=\"23-logic似然引导的渐进式推理覆盖检测\">2.3 LoGiC: Likelihood-Guided Progressive Reasoning Cover Detection</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/RACE-LoGiC.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The three steps of the LoGiC algorithm</a>\n<figcaption>The three LoGiC steps: (1) initialize the likelihood vector of all reference actions on the full trajectory; (2) from turn 2 onward, try removing the current reasoning step to build a candidate trajectory; (3) accept the removal only if the likelihood drop of the current and all later actions stays within the threshold, and carry the result forward to later turns</figcaption>\n</div>\n<p>The intuition behind a “reasoning cover”: keep the fewest reasoning steps that <strong>together</strong> still support every action in the trajectory, like lighting an entire road with the fewest streetlights. LoGiC works as input → processing → output:</p>\n<ul>\n<li><strong>Input</strong>: a successful trajectory \\(\\tau = (q, (r_t, a_t, o_t)_{t=1}^T)\\), with each $a_t$ treated as a fixed reference action $a_t^*$, and a threshold $\\epsilon = 0.001$.</li>\n<li><strong>① Initialization</strong>: compute the likelihood vector under the full-reasoning context, $\\ell^{(0)} = [\\ell(a_1^* \\mid x_1, r_1), \\dots, \\ell(a_T^* \\mid x_T, r_T)]$. The first turn’s reasoning is always kept.</li>\n<li><strong>② Progressive compression</strong>: starting at t=2, in the current compressed context $x^{(t)}$, where all accepted removals already apply, try removing $r_t$ and recompute the likelihoods $\\tilde\\ell_j^{(t)}$ of the reference actions at turn t and every later turn (earlier turns are unaffected and reused).</li>\n<li><strong>③ Likelihood verification</strong>: compute $d_j^{(t)} = \\ell_j^{(t-1)} - \\tilde\\ell_j^{(t)}$ and accept the removal only if $d_j^{(t)} \\le \\epsilon$ holds for every $j \\in {t, \\dots, T}$. On acceptance, update the likelihood vector and context; otherwise keep $r_t$ and add it to the cover.</li>\n<li><strong>Output</strong>: the compressed trajectory $\\tilde\\tau$ and the reasoning cover C, i.e., a THINK / SKIP label for every turn.</li>\n<li><strong>Design motivation</strong>: first, “progressive” means each decision is made on the already compressed context, so several steps that each look removable on their own are not removed together when the remainder could no longer support the actions. Second, “looking ahead” matters because a reasoning step can be irrelevant to the current action yet be the only basis for a later one.</li>\n</ul>\n<blockquote>\n<p><strong>Worked example</strong>: a 4-turn trajectory, threshold ε = 0.001, initial likelihoods $\\ell^{(0)}$ = [-0.20, -0.35, -0.10, -0.40].</p>\n<ul>\n<li><strong>t=2, try removing r2</strong>: recomputing turns 2–4 gives [-0.3504, -0.1003, -0.4006]; the drops 0.0004 / 0.0003 / 0.0006 are all ≤ 0.001 → <strong>accept</strong>. r2 is marked SKIP and the likelihood vector becomes [-0.20, -0.3504, -0.1003, -0.4006].</li>\n<li><strong>t=3, try removing r3</strong> (r2 already removed): the turn-3 action likelihood drops by only 0.0001, so judged on the current turn alone it is clearly removable. But turn 4 falls from -0.4006 to -0.52, a drop of 0.12 → <strong>reject</strong>, and r3 is kept. This is exactly the case that per-turn, independent decisions would delete by mistake.</li>\n<li><strong>t=4, try removing r4</strong>: the turn-4 likelihood falls to -0.95, a drop of 0.55 → reject.</li>\n</ul>\n<p>The final reasoning cover is {r1, r3, r4}, i.e., THINK / SKIP / THINK / THINK. The whole procedure needs only 3 batched scoring passes over candidate trajectories. Generation-based verification would sample K=4 actions at every later turn of every candidate, for (3+2+1)×4 = 24 autoregressive generations.</p>\n</blockquote>\n<p>The threshold of 0.001 is supported by Figure 1(b): at d ≤ 0.001, the action recovery rates on ScienceWorld and WebShop are 99.52% and 99.07%.</p>\n<h4 id=\"24-stage-1基于-logic-的-sft-数据合成\">2.4 Stage 1: LoGiC-based SFT data synthesis</h4>\n<p>Successful full-reasoning trajectories are collected with DeepSeek-V4-Pro, and LoGiC is run with Qwen3.5-9B to obtain $\\tilde\\tau = \\mathrm{LoGiC}(\\tau)$. Removed turns keep an empty <code class=\"language-plaintext highlighter-rouge\">&lt;think&gt;&lt;/think&gt;</code> and output the action directly. Qwen3.5-9B is then trained with standard SFT:</p>\n\n\\[\\mathcal L_{SFT} = -\\mathbb E_{\\tilde\\tau \\sim \\mathcal D_{SFT}} \\sum_{n=1}^{\\lvert \\tilde\\tau \\rvert} \\log \\pi_\\theta(\\tilde\\tau_n \\mid \\tilde\\tau_{&lt;n})\\]\n\n<p>The loss applies only to model-generated reasoning and action tokens. This step first teaches the model when it can act directly, and it serves as the initialization for RL.</p>\n<h4 id=\"25-stage-2推理覆盖感知的-agentic-rl\">2.5 Stage 2: Reasoning-cover-aware agentic RL</h4>\n<p>Offline data gradually drifts away from the evolving policy, so during RL, LoGiC is rerun on the <strong>successful trajectories</strong> of each rollout batch to obtain each trajectory’s set of SKIP turns $S_i$; failed trajectories use standard GRPO. Two mechanisms work together:</p>\n<table>\n<thead>\n<tr>\n<th>Mechanism</th>\n<th>What it does</th>\n<th>Problem it solves</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Reasoning masking</td>\n<td><strong>Reasoning tokens</strong> at SKIP turns are excluded from the GRPO gradient, while <strong>action tokens</strong> are still optimized; the normalization denominator still counts all original tokens</td>\n<td>Prevents the positive advantage of successful trajectories from also reinforcing redundant reasoning</td>\n</tr>\n<tr>\n<td>Reasoning closure</td>\n<td>After the compressed context at a SKIP turn, directly maximize the probability of generating the reasoning terminator <code class=\"language-plaintext highlighter-rouge\">&lt;/think&gt;</code></td>\n<td>Masking only withholds reward; closure supervision actively teaches the model to wrap up right there</td>\n</tr>\n</tbody>\n</table>\n<p>The masked GRPO loss ($K_i$ is the set of positions left after removing the reasoning tokens of SKIP turns, and $P_i$ is the set of all policy-token positions):</p>\n\n\\[\\mathcal L_{GRPO} = -\\frac{1}{\\sum_{i \\in B} \\lvert P_i \\rvert} \\sum_{i \\in B} \\sum_{k \\in K_i} \\min\\left(r_{i,k}(\\theta) \\hat A_i, \\mathrm{clip}(r_{i,k}(\\theta), 1-\\epsilon_{clip}, 1+\\epsilon_{clip}) \\hat A_i\\right)\\]\n\n<p>The reasoning-closure loss ($e$ is <code class=\"language-plaintext highlighter-rouge\">&lt;/think&gt;</code>, $I_{succ}$ is the set of successful trajectories, and normalizing by the total number of turns $T_i$ makes the supervision strength proportional to the share of SKIP turns):</p>\n\n\\[\\mathcal L_{close} = -\\frac{1}{\\sum_{i \\in B} T_i} \\sum_{i \\in I_{succ}} \\sum_{t \\in S_i} \\log \\pi_\\theta(e \\mid x_i^{(t)})\\]\n\n<p>The final actor objective is $\\mathcal L_{actor} = \\mathcal L_{GRPO} + \\lambda \\mathcal L_{close}$, with λ = 0.02 on ScienceWorld, WebShop, and AppWorld and 0.01 on DeepSearch. The task reward handles getting it right and the LoGiC signal handles thinking less; the division of labor is clear, and no length penalty is needed in the reward.</p>\n<p><strong>Inference</strong> has no extra steps: at each turn the model decides on its own whether to write a reasoning step or emit an empty <code class=\"language-plaintext highlighter-rouge\">&lt;think&gt;&lt;/think&gt;</code> and call a tool directly.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-10\">3. Key results and findings</h3>\n<p>On four benchmarks, ScienceWorld (scientific reasoning), WebShop (web shopping), AppWorld (app API use), and DeepSearch (retrieval QA), with Qwen3.5-9B as the backbone:</p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>ScienceWorld success / Tok.</th>\n<th>WebShop</th>\n<th>AppWorld</th>\n<th>DeepSearch</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Qwen3.5-9B (Base)</td>\n<td>18.52 / 2,210</td>\n<td>15.60 / 2,713</td>\n<td>46.15 / 3,134</td>\n<td>29.25 / 1,281</td>\n</tr>\n<tr>\n<td>AdaptThink</td>\n<td>64.49 / 1,252</td>\n<td>44.60 / 748</td>\n<td><strong>68.72</strong> / 2,381</td>\n<td>33.50 / 1,481</td>\n</tr>\n<tr>\n<td>SFT+GRPO (no LoGiC)</td>\n<td>74.55 / 2,073</td>\n<td>52.00 / 2,702</td>\n<td>65.30 / 3,545</td>\n<td>35.75 / 2,163</td>\n</tr>\n<tr>\n<td><strong>RACE-SFT-RL</strong></td>\n<td>73.28 / 1,403</td>\n<td><strong>53.40</strong> / <strong>535</strong></td>\n<td>65.13 / <strong>1,900</strong></td>\n<td>35.00 / <strong>822</strong></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Fewer tokens without losing accuracy</strong>: compared with standard SFT+GRPO, success stays within 1.4 points while reasoning tokens fall by <strong>32.3% / 80.2% / 46.4% / 62.0%</strong>.</li>\n<li><strong>A small model catching up with large ones</strong>: the 9B RACE model surpasses GPT-5.5 (69.88) on ScienceWorld (73.28) and ties Claude-Opus-4.6 on WebShop (53.40), but on AppWorld it still trails GPT-5.5 (91.11) and DeepSeek-V4-Pro (87.69) by a wide margin.</li>\n<li><strong>The RL stage contributes most</strong>: RACE-SFT saves only 4.3%–20.0% of tokens relative to standard SFT; after RL, RACE-SFT-RL gains another 2–30 points of success over RACE-SFT and cuts tokens by another 29%–57%.</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/RACE-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Task performance and reasoning tokens with and without LoGiC</a>\n<figcaption>With versus without LoGiC: the top row shows success rate and the bottom row reasoning tokens per trajectory. The SFT stage shows little difference; in the RL stage, RACE-SFT-RL greatly reduces reasoning tokens at comparable success</figcaption>\n</div>\n<ul>\n<li><strong>Ablation</strong>: removing LoGiC from RL makes reasoning cost soar (AppWorld 1,900 → 8,574 tokens), showing that standard GRPO by itself makes reasoning grow longer during training. Removing only reasoning masking sometimes yields even fewer tokens (only 124 on WebShop), but success falls to 46.00, showing that masking is what keeps reasoning from being cut too far.</li>\n<li><strong>Behavior analysis</strong>: after RL, the share of turns that skip reasoning rises sharply (ScienceWorld 37% → 70%, WebShop 7% → 56%, AppWorld 8% → 52%). Yet the reasoning that remains is not uniformly shorter: on ScienceWorld and AppWorld each reasoning step actually gets longer (132 → 273 tokens on ScienceWorld), concentrating thought on key turns such as planning and error recovery. On DeepSearch the skip rate is only 5.77%, so reasoning is still needed after almost every retrieval.</li>\n<li><strong>Scaling</strong>: the trends are broadly consistent across Qwen3.5-2B / 4B / 9B. Because AppWorld has little training data (147 tasks), its RL gains are unstable for smaller models.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-10\">4. Limitations</h3>\n<p>LoGiC relies on successful trajectories and fixed reference actions, so failed trajectories receive no reasoning signal during RL, and the threshold ε is a single global value that does not adapt to task difficulty. On reasoning-heavy retrieval QA (DeepSearch) it can hardly skip any reasoning, and on AppWorld it still lags clearly behind frontier large models. (These are observations made in this reading; the paper has no separate limitations section.)</p>\n<hr/>\n<h2 id=\"agentic-robots\">14. Agentic Robots (2026)</h2>\n<p>———From predicting actions to organizing execution: connecting how robot capabilities are built and used through Model, Data, Environment, and Harness</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.20442\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.20442</a> · <a href=\"https://github.com/chonghanqin/Awesome-Agentic-Robots\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a></p>\n<h3 id=\"精华-11\">Key takeaways</h3>\n<p>A robot’s capability depends on whether its reasoning model, executors, observations, interfaces, and feedback work together to support the task; action prediction alone does not explain success or failure on long-horizon tasks.\nThe key to an agentic system is using goals and actual execution results to decide what to do next, which capability to invoke, when to obtain new evidence, and how to change strategy after failure.\nThis survey organizes those decisions into four domains—Model, Data, Environment, and Harness—and 17 overlapping functional categories, bringing task execution and improvements to data, training, skills, and software into a single framework.\nA harness can coordinate frozen VLAs, analytical controllers, and reusable skills, but its benefits depend on state handovers, trustworthy feedback, and recovery mechanisms as well as the size of the planning model.\nEvaluation should hold executors and interaction budgets fixed to isolate the agent’s contribution, while also reporting the complete system’s time, computation, additional observations, and human effort.</p>\n<hr/>\n<h3 id=\"1-研究背景问题-11\">1. Research background and problem</h3>\n<p>VLAs connect visual and language knowledge to robot actions, while world models and world-action models (WAMs) further introduce predictions of future states or observations. Long-horizon tasks also require continuous progress tracking, responses to environmental changes, and recovery from failure.\nRelevant work is scattered across model training, data collection, environment construction, and runtime software, making it easy to conflate stronger action models, better toolchains, and more effective agent decisions.\nThrough a unified definition, functional taxonomy, and comparisons of representative work, this survey asks where agents make decisions in robot systems and how those decisions connect the current task to future capability improvements.</p>\n<hr/>\n<h3 id=\"2-主要方法创新点-11\">2. Main methods and contributions</h3>\n<h4 id=\"21-整体框架四个功能领域连接两种反馈循环\">2.1 Overall framework: four functional domains connecting two feedback loops</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Agentic-Robots-four-domains.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Four connected functional domains: Model, Data, Environment, and Harness</a>\n<figcaption>Original paper, Figure 2: Model, Data, Environment, and Harness connect through environmental interaction, execution feedback, planning calls, and learning from experience. These are functional domains rather than four stages that must run in sequence.</figcaption>\n</div>\n<p>The main contribution is a <strong>taxonomy and systematic analysis</strong>. Model covers model learning and the conversion of observations into decisions and control; Data acquires and organizes experience; Environment constructs interactive worlds, tasks, and tests; Harness connects models, tools, and skills to actual execution and manages context, verification, and recovery.</p>\n<p>The authors define agentic robots as robot systems whose agents use environmental observations and execution feedback to autonomously plan and coordinate tasks, deciding during execution whether to continue, acquire information, revise a plan, or recover from failure (§3.1). Implementation may reside within one model or span multiple models, programs, and tools; the criterion is <strong>how tasks are organized and adjusted</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>Comparison</th>\n<th>When considering only the action policy</th>\n<th>The survey’s agentic-system perspective</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Objects of decision-making</td>\n<td>Output the next action segment given observations and conditions</td>\n<td>Also select subgoals, executors, tools, observation requests, and control handovers</td>\n</tr>\n<tr>\n<td>Use of feedback</td>\n<td>Adjust actions within the current policy</td>\n<td>Also trigger replanning, state verification, executor switching, and recovery</td>\n</tr>\n<tr>\n<td>Targets for improvement</td>\n<td>Policy parameters and their training conditions</td>\n<td>Also data, tasks, skill libraries, training experiments, and runtime software</td>\n</tr>\n</tbody>\n</table>\n<p>These are not mutually exclusive generations of technology: a VLA can itself include memory, reasoning, or tool use, and traditional autonomous robots have long used planning and monitoring. The survey emphasizes how foundation-model agents participate in these functions; the label “agentic” does not automatically imply greater autonomy.</p>\n<p>The four domains contain the following 17 functional categories (Table 1). A single work may span several categories: Harness VLA involves orchestration, memory, monitoring, and recovery, while Zero2Skill connects data collection, refinement, and policy training.</p>\n<table>\n<thead>\n<tr>\n<th>Domain</th>\n<th>Functional categories</th>\n<th>What changes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Model (5 categories)</td>\n<td>Training, Perception, Planning, Robot Control, Adaptation</td>\n<td>Learning processes, task evidence, plans, control commands, and adaptation through experience</td>\n</tr>\n<tr>\n<td>Data (3 categories)</td>\n<td>Collection, Annotation, Refinement</td>\n<td>Acquisition of new experience, addition of structured supervision, and selection and correction of existing records</td>\n</tr>\n<tr>\n<td>Environment (3 categories)</td>\n<td>Reconstruction, Task Generation, Benchmarking</td>\n<td>Executable scenes, practice goals and distributions, evaluation conditions, and measurement procedures</td>\n</tr>\n<tr>\n<td>Harness (6 categories)</td>\n<td>Orchestration, Memory, Monitoring and Recovery, Skills, Infrastructure, Layered Systems</td>\n<td>Capability invocation, information retention, failure handling, behavior reuse, service interfaces, and authority across layers</td>\n</tr>\n</tbody>\n</table>\n<p>Two connected but distinct loops operate here. The <strong>within-task loop</strong> adjusts the next step using current observations and execution results. The <strong>cross-task improvement loop</strong> turns experience into better data, models, skills, or software, then uses new tasks to test whether the improvement holds.</p>\n<h4 id=\"22-model从学习过程到机器人动作区分五种干预位置\">2.2 Model: five intervention points from learning to robot actions</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Agentic-Robots-model-interventions.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Training, perception, planning, control, and adaptation interventions for opening a drawer and retrieving an object</a>\n<figcaption>Original paper, Figure 4: the same task of opening a drawer and retrieving an object can be improved through training, perception, planning, control, or adaptation. Different failures require different interventions.</figcaption>\n</div>\n<ul>\n<li><strong>Training: change how the robot learns.</strong> Inputs include task goals, training logs, execution videos, and evaluation results. The agent generates or modifies reward code, objectives, training configurations, policy programs, or experimental procedures; an optimizer produces a new policy, which is tested through real or simulated execution. Eureka iterates reward code, ENPIRE extends this to real-robot policies and training code, and HARBOR emphasizes typed artifacts and stage checks. Measurement criteria must remain stable so that a modification does not change both the method and its judge.</li>\n<li><strong>Perception: turn observations into evidence that the next decision can use.</strong> Inputs include images, depth, robot state, and history. Outputs may be scene relations, geometric targets, symbolic states, or requests to look again. AgenticNav supports navigation with orientation-indexed views, selective recall, and geometric tools; MG-VQA can push or move objects to reveal occluded information. Remembering an object’s identity does not mean its old position is still suitable for immediate action.</li>\n<li><strong>Planning: decide what to do and in what dependency order.</strong> Inputs include instructions, scene representations, history, and available capabilities; outputs include the next operation, subgoal, action sequence, or program. Hi Robot uses a high-level VLM to update short language subtasks for a VLA, while SayPlan checks and revises plans on a scene graph. Feasibility checks before execution and feedback afterward jointly determine how far a plan should extend: greater uncertainty makes fresh observations more important for subsequent decisions.</li>\n<li><strong>Robot Control: translate the selected operation into requirements the execution layer can handle.</strong> Outputs may be language instructions, action primitives, target poses, programs, constraints, or cost functions. ReKep expresses keypoint relations as constraints for a solver to repeatedly optimize motion; VoxPoser constructs spatial value maps for a motion planner. The backend responsible for inverse kinematics, collision checking, and trajectory tracking directly affects the capability of an apparently identical agent.</li>\n<li><strong>Adaptation: change future behavior through experience.</strong> Inputs include failures, corrections, demonstrations, and autonomous interaction results. Outputs may be updated context or planner configurations, or genuinely updated model parameters. TidyBot and DROC can retain experience to change decisions; OLAF and RoboCat involve policy training. The survey distinguishes recovery within the current task, adaptation through context, and long-term improvement after retraining, and calls for checking whether earlier capabilities are retained.</li>\n</ul>\n<h4 id=\"23-data获取经验补充监督再修正已有记录\">2.3 Data: acquire experience, add supervision, and revise existing records</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Agentic-Robots-data-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Data collection, annotation, and refinement, including useful segments from failed trajectories</a>\n<figcaption>Original paper, Figure 5: Collection acquires new experience, Annotation adds task, phase, and outcome information, and Refinement selects useful segments and corrects supervision. Failed trajectories may also contain progress and recovery behavior worth retaining.</figcaption>\n</div>\n<ul>\n<li><strong>Collection: decide what to collect, how, and when to reset.</strong> Given scenes, task coverage, and execution weaknesses, the agent selects practice tasks, invokes policies or demonstration procedures, and evaluates outcomes to continue, retry, or request assistance. The survey distinguishes real physical collection, simulated execution, and synthesis with generative models: AutoRT and SOAR organize real-world collection; RoboGen connects tasks, scenes, and simulated trajectories; RoboCurate and related systems organize generation and check consistency between actions and visual outcomes.</li>\n<li><strong>Annotation: turn videos and state logs into supervision.</strong> Processing includes trajectory segmentation, language explanations, detection and segmentation, geometric queries, and outcome verification. Outputs include textual, spatial, interaction, or outcome labels. NILS generates stage instructions from object motion, state changes, and gripper events; ECoT adds reasoning traces. Answers about spatial distances or object locations can also come from geometric computation or simulation records, with semantic interpretation and measurement evidence serving different roles.</li>\n<li><strong>Refinement: reassess whether existing data is worth learning from and whether its labels are correct.</strong> Inputs include complete trajectories, local segments, and subsequent feedback; outputs are retained data and corrected supervision. HELP and ARS use progress estimates to retain useful portions of failed attempts. Zero2Skill can reapply human-corrected success criteria to earlier demonstrations. Selection need not operate on whole successful or failed trajectories, and the criteria themselves also require verification.</li>\n</ul>\n<h4 id=\"24-environment分别检查世界目标和裁判\">2.4 Environment: examine the world, the goal, and the evaluator separately</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Agentic-Robots-environment-design.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Environment reconstruction, task generation, and benchmarking</a>\n<figcaption>Original paper, Figure 6: Reconstruction builds executable scenes; Task Generation defines goals, constraints, and success conditions; Benchmarking fixes test conditions, reset procedures, metrics, and evaluators.</figcaption>\n</div>\n<ul>\n<li><strong>Reconstruction: turn observations or requirements into interactive scenes.</strong> Inputs may be images, videos, demonstrations, or layout descriptions. The agent generates, combines, or modifies meshes, joints, poses, physical properties, and scene code; compilation, geometry, and simulation checks guide repairs. Articulate-Anything iterates link and joint code, while SceneSmith modifies worlds through structured scene operations and rollback. Visual similarity, static stability, correct contact behavior, and validity in the real world require different levels of verification.</li>\n<li><strong>Task Generation: define what the robot should practice.</strong> Inputs include scenes, capability ranges, and past performance; outputs include goals, initial states, constraints, success conditions, or curriculum distributions. GenSim and RoboGen generate executable tasks, while CurricuLLM and RATs adjust practice according to learning progress. Repairing an infeasible task also requires checking that its original goal is preserved; changing only a solution plan does not necessarily create a new task.</li>\n<li><strong>Benchmarking: specify which capability a score measures.</strong> Given the capability under evaluation and system interfaces, outputs include tasks, perturbations, observation access, reset protocols, interaction budgets, and scoring rules. Tests of open-loop skill composition, closed-loop replanning, active perception, memory, and safety measure different capabilities. If an agent also generates new tests from evaluation results, improved evaluation must be distinguished from improved robot capability.</li>\n</ul>\n<h4 id=\"25-harness让能力能够被调用衔接核验与复用\">2.5 Harness: make capabilities callable, composable, verifiable, and reusable</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Agentic-Robots-harness-functions.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Six harness functions surrounding the decision, dispatch, execution, and feedback loop</a>\n<figcaption>Original paper, Figure 7: tasks and evidence feed decisions and dispatch, which invoke policies, primitives, solvers, or skills and receive actual feedback. The six surrounding harness functions determine whether this execution loop is reliable.</figcaption>\n</div>\n<p>A harness is <strong>the software that tells a model what it can invoke, passes calls to the robot, and returns actual outcomes to the next decision</strong> (§7). It manages input/output contracts, control authority, state, and retained experience as well as function names.</p>\n<p><strong>① Orchestration: select an executor and hand over control.</strong> Inputs include the task, current evidence, executor capabilities, and the previous call’s result. Processing includes routing, parameter binding, function-protocol checks, state transitions, and handover timing; outputs are a concrete dispatch and subsequent decisions to continue or switch. RoboHarness uses a motion-planned memory bridge to move the robot into the starting state required by the next policy, whereas RoboRouter selects a policy suited to the current state. Selecting the right policy and preparing a state it can handle are separate problems.</p>\n<blockquote>\n<p><strong>Example:</strong> suppose object retrieval requires three steps: open the drawer → grasp the object → place it on the table. The drawer-opening tool reports completion, but the gripper still holds the handle, while the grasping policy requires a free gripper. Calling it immediately would fail at the handover. The harness should verify the drawer state, release the handle, and reach an appropriate pose before starting the grasping policy. If sensors then show an empty gripper after the grasp, it should observe again or recover instead of advancing directly to placement. This is an explanatory illustration, not a new experiment in the paper.</p>\n</blockquote>\n<p><strong>② Memory: retain past information and manage whether it is still valid.</strong> Inputs include interactions, events, observations, and outcomes. Writing, updating, and retrieval produce evidence or task state relevant to the next decision. Putting all history into context adds redundancy, while excessive compression loses critical commitments; when a scene changes, old positions need updating or verification. Whether memory persists across tasks depends on the system.</p>\n<p><strong>③ Monitoring and Recovery: turn detected problems into executable repairs.</strong> Before execution, check candidate actions and constraints; during execution, assess progress and whether to interrupt; afterward, interpret success or failure. Then choose among retrying, grounding again, switching executors, replanning, and resetting. REFLECT passes failure explanations to a corrective planner, while DoReMi monitors constraints as skills run. Recovery must also specify whether to continue from the current disturbed state or first restore a known state, with limits on retries and conditions for human intervention.</p>\n<p><strong>④ Skills: turn experience into reusable ways of acting.</strong> Inputs include demonstrations, corrections, successful programs, and failure records. Processing includes abstraction, implementation, testing, admission to the library, revision, and retirement; outputs are loadable textual procedures or callable behaviors. Code as Policies composes perception and control APIs into programs, and subsequent skill libraries retain transferable portions. ASPIRE, RATs, and RoboRSI further use execution evidence to revise skills. The key is verifying new versions and retaining earlier capabilities, beyond simply generating more code.</p>\n<table>\n<thead>\n<tr>\n<th>Object retained or improved</th>\n<th>Plain-language meaning</th>\n<th>Typical forms</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Memory</td>\n<td>Remember what just happened</td>\n<td>Object states, failure records, historical views, task progress</td>\n</tr>\n<tr>\n<td>Skills</td>\n<td>Retain what to do next time this situation occurs</td>\n<td>Textual procedures, functions, programs, callable behaviors</td>\n</tr>\n<tr>\n<td>Model parameters</td>\n<td>Change the model’s own capabilities through training</td>\n<td>Updated weights of planning models, action policies, or code models</td>\n</tr>\n</tbody>\n</table>\n<p><strong>⑤ Infrastructure: provide runnable, inspectable interfaces for tools and policies.</strong> Inputs are invocation requests and robot data. Backend services handle perception, grasping, motion planning, and VLA inference; interfaces return measurements, execution records, or explicit failure information. Typed APIs, ROS 2 / MCP interfaces, remote policy services, and runtime checks outside the model jointly determine available capabilities. If a backend hides perception errors or action latency, the planner also struggles to recover correctly.</p>\n<p><strong>⑥ Layered Systems: divide responsibilities by response speed and authority.</strong> The authors use System 2 for the slow reasoning or program layer responsible for goals and subtasks, System 1 for learned visuomotor policies, and System 0 for analytical control such as inverse kinematics, motion planning, and MPC. Layers exchange language, latent features, paths, or waypoints and update at different frequencies. For example, the cited Ground Slow, Move Fast uses an approximately 2 Hz planner and a 30 Hz policy, followed by MPC tracking (§7.6). These rates belong to that configuration rather than a standard adopted by all systems.</p>\n<p>The following reader-oriented dataflow illustrates one closed-loop execution. It synthesizes mechanisms discussed in the survey and does not imply that the paper proposes this fixed architecture.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Task goal and current observations\"] --&gt; B[\"Retrieve history and verify current state\"]\n    B --&gt; C[\"Select subgoal and executor at the high level\"]\n    C --&gt; D[\"Check parameters, preconditions, and handover state\"]\n    D --&gt; E[\"Invoke a VLA, analytical tool, or skill\"]\n    E --&gt; F[\"Execute motion with the low-level controller\"]\n    F --&gt; G[\"Independently verify progress, outcomes, and constraints\"]\n    G -- \"Continue or advance to the next phase\" --&gt; B\n    G -- \"Failure or insufficient evidence\" --&gt; H[\"Acquire observations, recover, or replan\"]\n    H --&gt; B\n</code></pre>\n<h4 id=\"26-训练与推理明确哪些东西发生了变化\">2.6 Training and inference: specify what actually changes</h4>\n<p>The paper proposes no unified trainable model or dedicated loss function, so its 17 functional categories should not be combined into a new training objective. Surveyed systems may modify rewards under a fixed optimizer, train policies with new annotations and corrected data, or freeze all models and update only context, skill code, or invocation procedures.</p>\n<p>At inference time, the agent advances the task using actual observations and execution feedback. High-level calls may be triggered periodically, by progress events, or according to a budget, while lower layers continue timely motion control. Cross-task improvement retains trajectories, reviews, labels, skill revisions, or experimental results. Establishing lasting capability gains requires reevaluation on new tasks and conditions that did not participate in the modification.</p>\n<hr/>\n<h3 id=\"3-核心结果发现-11\">3. Key results and findings</h3>\n<p><strong>The paper contributes a taxonomy of four domains and 17 overlapping functional categories, comparisons across works, and a research agenda; it does not introduce a new method and evaluate it in a unified leaderboard experiment.</strong> All figures below are results of representative works as reported by the survey (§7.5). They illustrate the importance of interfaces and toolchains and cannot be compared across rows as a method ranking.</p>\n<table>\n<thead>\n<tr>\n<th>Surveyed work</th>\n<th>Comparison conditions and reported results</th>\n<th>Observation supported</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>NavMCP</td>\n<td>QA accuracy is 74.0% with the complete three-channel protocol and 59.1% with an episode-organized interface</td>\n<td>Intent, keyframe-based journey summaries, and persistent memory jointly affect results; the difference cannot be attributed to memory alone</td>\n</tr>\n<tr>\n<td>Show-Harness</td>\n<td>Halving the motion step size raises reported zero-shot success from 60% to 82%</td>\n<td>The same model can perform differently when action-interface granularity changes</td>\n</tr>\n<tr>\n<td>ASPIRE</td>\n<td>On the evaluated LIBERO-Pro perturbations, adding the execution engine raises macro-average success from 14% to 62%</td>\n<td>Primitive-level execution tracking, debugging, and repair verification are important system variables; the reasoning model cannot receive all the credit</td>\n</tr>\n<tr>\n<td>Work by Kuroki and Tang</td>\n<td>Success is 65.0% with full simulation observations and 22.5% with RGB input alone</td>\n<td>Privileged state can hide perception costs; results with different state-access conditions require separate interpretation</td>\n</tr>\n</tbody>\n</table>\n<p>Across the domains, <strong>correct action or tool-call syntax does not ensure successful physical execution; storing experience does not ensure that evidence remains valid; accepting one skill update does not ensure continuous long-term capability growth.</strong> The survey notes that perception and tracking errors accumulate through toolchains and that progress in some self-improving systems is not monotonic. Actual execution evidence, independent measurement, and validation on new tasks are therefore necessary.</p>\n<p>The authors identify four directions for further work (§8):</p>\n<ul>\n<li><strong>Fair evaluation:</strong> compare the agent’s decision-making contribution under the same executors, observation access, and interaction budgets, while reporting resources and human effort for the complete system.</li>\n<li><strong>Real-robot deployment:</strong> specify skill preconditions, whether actions have finished or stopped, and recovery mechanisms for noise, contact, and stale observations.</li>\n<li><strong>Efficient robot use:</strong> trigger high-level reasoning according to task progress and uncertainty, and account for the total cost of model waiting time, networking, tool calls, retries, and physical execution.</li>\n<li><strong>Cross-embodiment generalization:</strong> let agents adjust plans to a new robot’s sensors, motion range, and skills, and measure the effects of additional configuration, training, and transferred experience.</li>\n</ul>\n<hr/>\n<h3 id=\"4-局限性-11\">4. Limitations</h3>\n<p>The evidence comes from existing studies with different observation access, executors, recovery budgets, and simulation or real-world conditions. Classification and synthesis cannot directly establish a common causal benefit for a particular system composition.\nReal-world contact and perception errors, runtime latency, reliable self-improvement, and transfer to unfamiliar robots remain open problems. A single task’s success rate or a simulation score cannot replace their verification.</p>\n<hr/>\n<h2 id=\"harness2\">15. Harness² (2026)</h2>\n<p>———Improving the harness for the current task while learning how to improve future harnesses</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.14224\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.14224</a> · <a href=\"https://github.com/google-research/harness2\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a> · <a href=\"https://harness2.github.io/\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<p><strong>Scope of inclusion:</strong> Harness² evaluates online harness refinement for general agents on coding, office, and legal tasks. It is included as a methodological reference for embodied-agent self-improvement and experience reuse; its results do not establish effectiveness in robot deployment.</p>\n<h3 id=\"harness2-takeaways\">Key takeaways</h3>\n<ol>\n<li>An agent’s capabilities also depend on the prompts, skills, scripts, tool constraints, and orchestration surrounding its model. These executable configurations can improve while model parameters remain frozen.</li>\n<li>Without ground-truth answers, proposing targeted edits, rerunning the task under matched conditions, and retaining changes supported by behavioral contrasts provides more evidence than rewriting a harness by intuition alone, but still does not guarantee correctness.</li>\n<li>Transferable assets include both the final skills or scripts and improvement experience: which situation exposed a weakness, which edit was tried, and what behavior changed.</li>\n<li>Starting each new task from a common base harness and selectively consulting the library avoids directly accumulating rules tailored to previous tasks.</li>\n<li>Additional inference budget is useful through candidate edits, execution evidence, and selective composition. Evaluation must count reruns and editing costs rather than only the steps in the final execution.</li>\n</ol>\n<hr/>\n<h3 id=\"harness2-background\">1. Background and problem</h3>\n<p>Open-world agents continually encounter new tasks whose requirements cannot usually be anticipated during harness design. Online adaptation also lacks ground-truth answers or reliable verifiers to guide edits. Existing approaches either optimize offline on fixed training tasks or refine only the current task, making it difficult to turn the process of diagnosing weaknesses, testing changes, and deciding what to retain into a capability useful for future tasks.</p>\n<p>The paper asks how to improve both the current execution harness and the experience that guides future harness refinement <strong>without updating model weights, accessing scoring feedback, or replaying completed tasks</strong>.</p>\n<hr/>\n<h3 id=\"harness2-method\">2. Method and innovations</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Harness2-framework.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Harness² framework with task-level and harnessing-level recursion</a>\n<figcaption>Figure 3: Harness² couples two levels of recursion. Within a task, editors propose invariant and domain-specific candidates, execute them, and pass the evidence to a composer. After the task, a reflector stores reusable harnesses and evidence-supported lessons in the improvement library.</figcaption>\n</div>\n<p><strong>Overall framework.</strong> Harness² comprises an executor, harness editors, a composer, and an experience reflector. The executor produces trajectories and deliverables; editors propose executable harness changes; the composer weighs probe evidence; and the reflector updates the experience library after each task. The paper calls the runtime configuration around a frozen model a <strong>harness</strong>, and the process of optimizing that configuration <strong>harnessing</strong>.</p>\n<p><strong>① Editable objects: eight file-based components.</strong> The inputs are the current task, a frozen model, and an initial execution harness. Edits modify a component tree and produce a new configuration that can be mounted into the agent runtime. The eight components are System prompt, Guardrails, Memory, Tool guidance, Subagents, Skills, Scripts, and Plugin. They change persistent context, on-demand procedures, deterministic capabilities, separate working contexts, or hooks inside the tool loop.</p>\n<p>The editable surface extends beyond prompts. Scripts execute mechanical checks, Skills load when relevant, and Plugins intervene around tool calls or turn boundaries. Components are chosen to address observed weaknesses rather than added indiscriminately. The edited tree also passes structural validation: skills must have trigger guidance, scripts must compile, and referenced helpers must exist. These checks establish configuration validity, not task correctness.</p>\n<p><strong>② The basic within-task step: Propose–Probe–Compose.</strong> Without an answer key, the system first asks whether a concrete behavior changed after an edit, then decides whether that edit deserves to remain. This is the paper’s behavioral-contrast signal.</p>\n<ul>\n<li><strong>Propose: diagnose weaknesses from a reference execution.</strong> Inputs include the task, current harness, reference execution record, and existing experience. Two editing scopes produce complete candidate harnesses: Invariant (INV) addresses cross-domain procedures such as retries, planning, tool use, and delivery checks; Domain (DOM) addresses domain knowledge, professional procedures, deliverable structure, and constraints.</li>\n<li><strong>Probe: execute the candidates.</strong> Each candidate runs on the same task with matched model and environment configurations, producing a trajectory and deliverables. Comparison with the reference asks whether the targeted weakness was mitigated, unchanged, or accompanied by regressions. Sampling variation and shared model biases still limit the evidence.</li>\n<li><strong>Compose: combine edits according to evidence.</strong> Inputs include candidate diffs, reference and candidate trajectories, and the available task-local history. The composer can merge supported edits, revise conflicts, adopt a candidate, or retain the current harness. It then executes the composed harness and records the observation supporting each decision.</li>\n</ul>\n<blockquote>\n<p><strong>A concrete example:</strong> A task requires reconciling schedule, staffing, and budget files into consistent deliverables. The reference execution omits cross-file reconciliation and never reopens its outputs. An INV candidate adds a script to reopen and check deliverables; a DOM candidate adds a skill for reconciling schedules and budgets. If their probe trajectories show those operations occurring, the composer has evidence to retain the corresponding edits. However, running a check does not establish that every number is correct. In the paper’s Figure 9 case, the final score rises from 43.1 to 77.8; that score is available only to retrospective evaluation, not to the editors or composer.</p>\n</blockquote>\n<p><strong>③ Scaling within-task search: parallel exploration and sequential revision.</strong> Both forms build on the basic contrastive step, but their budgets control different aspects of search.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Harness2-recursion.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Parallel and sequential task-level recursion in Harness²</a>\n<figcaption>Figure 4: Parallel recursion explores multiple candidates against a shared reference set and independently composes successors. Sequential recursion passes the revised harness, accumulated trajectories, and decisions into the next step.</figcaption>\n</div>\n<ul>\n<li><strong>Parallel recursion:</strong> Collect $k$ reference executions under the initial harness, independently propose and probe $k$ INV and $k$ DOM candidates, then let $k$ composition sessions read the entire pool. Each session produces and executes one successor harness. The implementation performs one population update, so $k$ controls search width.</li>\n<li><strong>Sequential recursion:</strong> Starting from the initial harness, chain $k$ improvement steps. Each reads the current harness and accumulated trajectories and decisions to produce the next configuration. Later steps can retain, revise, or undo earlier changes, so $k$ controls revision depth.</li>\n</ul>\n<blockquote>\n<p><strong>Counting the budget:</strong> For parallel recursion with $k=2$, there are 2 reference executions, 4 candidate probes, and 2 composed-harness executions: <strong>8 complete task executions</strong>, plus editing, composition, and final-selection sessions. Even $k=1$ involves 1 reference run, 2 candidate probes, and 1 composed-harness execution. A single improvement step therefore involves more than one extra run. This count excludes additional overhead such as configuration-validation retries.</p>\n</blockquote>\n<p>For $k&gt;1$, a final selector compares anonymous deliverables against the task request and source material. It returns an existing result, creates no new content, and cannot see the originating harness. The appendix explicitly allows it to select an output produced by the initial harness. At $k=1$, final selection is bypassed and the executed successor from the basic step is returned. Adoption means selection in this run, not verified optimality.</p>\n<p><strong>④ Across-task improvement: retain the harness, applicable situation, and evidence.</strong> The experience reflector receives the complete improvement record, including rejected candidates rather than only the selected output. It records each edit, the observed behavioral difference, and the strength of attribution before deciding whether to extract a reusable lesson. When multiple edits are confounded or only one execution supports an observation, attribution can be marked as confounded. With insufficient reusable evidence, the reflector can decline to add an experience entry.</p>\n<p>The library retains the adopted executable harness and an <code class=\"language-plaintext highlighter-rouge\">EXPERIENCE.md</code> describing its applicable situation, lesson, evidence, and confidence. An index lets later editors inspect relevant entries on demand. The two recursive levels differ in what they change within a task and what they carry across tasks:</p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Task-level recursion</th>\n<th>Harnessing-level recursion</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Updated object</td>\n<td>The current task’s execution harness $H$</td>\n<td>The library within the improvement harness $R_t$ that guides future editing</td>\n</tr>\n<tr>\n<td>Evidence</td>\n<td>Reference, candidate, and composed-harness executions on the current task</td>\n<td>The complete improvement process and its decisions</td>\n</tr>\n<tr>\n<td>When it acts</td>\n<td>During probes and iterations on the same task</td>\n<td>After task completion, for use by subsequent tasks</td>\n</tr>\n<tr>\n<td>How the next task starts</td>\n<td>The task-specific harness is not directly inherited</td>\n<td>Start from the common base harness and selectively reuse library components and experience</td>\n</tr>\n</tbody>\n</table>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"New task t + common initial harness H0\"] --&gt; B[\"Reference execution: trajectory and deliverables\"]\n    R[\"Current experience library Rt\"] --&gt; C[\"Propose INV and DOM candidates\"]\n    B --&gt; C\n    C --&gt; D[\"Probe candidates on the same task\"]\n    D --&gt; E[\"Compare behavioral evidence and compose a harness\"]\n    E --&gt; F[\"Execute the successor and return a result\"]\n    F --&gt; G[\"Reflect on the complete improvement record\"]\n    G --&gt; H[\"Update the experience library to Rt+1\"]\n    H --&gt; I[\"Next task: start from H0 again\"]\n    I --&gt; J[\"Use the updated library to guide new edits\"]\n</code></pre>\n<p>The diagram omits anonymous deliverable selection for $k&gt;1$. Throughout recursion within a task, $R_t$ remains fixed. The next task does not directly inherit the previous task’s harness, and task-specific facts discovered earlier must be checked for applicability to the new task.</p>\n<p><strong>⑤ Update rules and training objectives.</strong> The method introduces no gradient training, reinforcement-learning reward, or new loss function. It performs discrete updates to configuration files and the experience library around a frozen model. With $e=(\\tau,y)$ denoting a trajectory and deliverable, the basic improvement step is:</p>\n\n\\[(H',e',\\xi)=\\Phi(q_t,H,\\mathcal E;R_t).\\]\n\n<p>Here $\\mathcal E$ is the available task-local history, and $\\xi$ records candidate probes, composition decisions, and their evidence. Executing changes and retaining their evidence is central to this operator. After task completion, the improvement library is updated as:</p>\n\n\\[R_{t+1}=\\operatorname{Update}(R_t,H_t^{\\star},\\mathcal D_t).\\]\n\n<p>$H_t^{\\star}$ is the adopted harness and $\\mathcal D_t$ the complete improvement record. The star denotes adoption, not correctness or global optimality. Model weights, stage instructions, and decision rules remain fixed; the persistent changes are library components and experience.</p>\n<p><strong>⑥ End-to-end execution.</strong> A new task first runs with the common initial harness to obtain reference trajectories. Editors consult the current library to propose candidates, the executor probes them, and the composer forms a successor from behavioral evidence. Exploration follows the prescribed parallel or sequential budget, a result is delivered, and reflection makes supported experience available to the next task. The whole process takes place at deployment time; benchmark answers, rubrics, and scores are used only for external evaluation.</p>\n<hr/>\n<h3 id=\"harness2-results\">3. Key results and findings</h3>\n<p><strong>Evaluation setup.</strong> Main experiments combine two frozen executors, Gemini 3.5 Flash and GLM-5, with two initial harnesses, OpenCode and Codex, giving four configurations. The default editor and selector are Claude Opus 4.8. WorkBuddy-Bench uses 40/35/25 test tasks in Code/Web/Office, JobBench uses 34 test tasks, and LAB uses 100 test tasks. Methods process task streams, and the main tables report means and standard deviations over three shuffled runs, starting from empty libraries.</p>\n<p><strong>Both a single step and parallel recursion improve performance.</strong> The following representative results come from the main tables. The $k=5$ values add the reported recursion gains to the $k=1$ results. WorkBuddy-Bench and JobBench report scores; LAB Partial is a per-criterion pass rate (%).</p>\n<table>\n<thead>\n<tr>\n<th>Benchmark and execution configuration</th>\n<th style=\"text-align: right\">Initial harness</th>\n<th style=\"text-align: right\">Harness², $k=1$</th>\n<th style=\"text-align: right\">Parallel recursion, $k=5$</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>WorkBuddy-Bench average, Gemini 3.5 Flash / OpenCode</td>\n<td style=\"text-align: right\">72.4</td>\n<td style=\"text-align: right\">77.5</td>\n<td style=\"text-align: right\">80.8</td>\n</tr>\n<tr>\n<td>WorkBuddy-Bench average, GLM-5 / OpenCode</td>\n<td style=\"text-align: right\">64.2</td>\n<td style=\"text-align: right\">75.7</td>\n<td style=\"text-align: right\">79.6</td>\n</tr>\n<tr>\n<td>JobBench, Gemini 3.5 Flash / OpenCode</td>\n<td style=\"text-align: right\">31.5</td>\n<td style=\"text-align: right\">36.0</td>\n<td style=\"text-align: right\">39.0</td>\n</tr>\n<tr>\n<td>JobBench, GLM-5 / OpenCode</td>\n<td style=\"text-align: right\">20.6</td>\n<td style=\"text-align: right\">24.2</td>\n<td style=\"text-align: right\">28.4</td>\n</tr>\n<tr>\n<td>LAB Partial, GLM-5 / OpenCode</td>\n<td style=\"text-align: right\">59.6</td>\n<td style=\"text-align: right\">71.4</td>\n<td style=\"text-align: right\">78.1</td>\n</tr>\n</tbody>\n</table>\n<p>The largest single-step gains over the initial harness are <strong>11.5 points</strong> on WorkBuddy-Bench, <strong>4.5 points</strong> on JobBench, and <strong>11.8 percentage points</strong> on LAB. Increasing the budget to $k=5$ adds 2.9–3.9 points, 3.0–4.2 points, and 2.6–6.7 percentage points, respectively, across the four configurations. Harness² exceeds the compared baselines on WorkBuddy-Bench average and JobBench score in all four configurations. On LAB with Gemini 3.5 Flash / Codex, however, its single-step result of 75.6 is below Meta-Harness’s 76.5; the evidence does not support claiming leadership in every setting.</p>\n<p><strong>Composition, scoped editing, and the library all contribute.</strong> With Gemini 3.5 Flash / OpenCode at $k=1$, the full method scores 77.5 / 36.0 on WorkBuddy-Bench / JobBench. Removing the library lowers these to 74.4 / 34.2; removing the INV/DOM split gives 74.6 / 32.3; and skipping composition to choose between the two candidates gives 75.9 / 34.1. In the appendix, removing Skills from an already improved harness reduces the WorkBuddy-Bench average by 5.3 points, while removing Scripts costs 3.7 points. Multiple components contribute; longer prompts alone do not explain the gains.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Harness2-library-transfer.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Harness² library reuse and cross-benchmark transfer</a>\n<figcaption>Figure 7: Left, edit the harness directly with the improvement library, without new reference executions or candidate probes. Right, transfer JobBench experience to WorkBuddy-Bench. A library accumulated with more exploration better supports subsequent refinement.</figcaption>\n</div>\n<p><strong>Experience helps future tasks, but experimental protocols matter.</strong> Directly editing without execution evidence or a library lowers Code from 73.4 to 63.2 and Web from 69.9 to 65.0. With a library accumulated at $k=5$, even without new probes, Code/Web/Office exceed the initial harness by 0.9/4.4/5.1 points. Transferring JobBench experience to single-step WorkBuddy-Bench refinement adds 0.6/0.5/2.9 points across the three domains. The appendix’s leave-one-out reruns can also access later-task experience; they are an offline reuse analysis, not an estimate of online gains.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Harness2-same-model.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Harness² with the same model as executor and editor</a>\n<figcaption>Figure 8: With OpenCode at k=2, using the same model as executor and editor still improves all five tested models on all three benchmarks. Gains therefore need not depend on a stronger external editor.</figcaption>\n</div>\n<p><strong>The same model can improve its own harness, while full costs still matter.</strong> In the same-model experiment, Claude Opus 5 gains 3.3, 5.5, and 3.0 points on WorkBuddy-Bench, JobBench, and LAB, respectively; GLM-5 gains 13.7 percentage points on LAB. Figure 6 counts total execution and improvement tokens and places both Harness² configurations, $k=1$ and $k=5$, for Gemini 3.5 Flash / OpenCode on the empirical Pareto frontier of the compared methods. This describes the observed cost–performance trade-off in that experiment. The main tables’ <code class=\"language-plaintext highlighter-rouge\">#Steps</code> count model turns in an executor session and cannot replace total cost accounting.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Harness2-case-study.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Harness² case study on cross-file reconciliation and deliverable checks</a>\n<figcaption>Figure 9: In a JobBench production-coordination task, procedural guardrails, a professional reconciliation skill, verification scripts, and tool guidance together address cross-file consistency and missing deliverable sections. The score rises from 43.1 to 77.8.</figcaption>\n</div>\n<hr/>\n<h3 id=\"harness2-limitations\">4. Limitations</h3>\n<p>Repeated executions and editing add substantial inference cost. Parallelism reduces latency only when resources permit, and the paper does not establish a universally optimal budget or an adaptive stopping rule. Behavioral contrasts and anonymous selection remain vulnerable to shared false assumptions, sampling variation, and evaluation noise: the appendix even reports selecting a 55-point output when a 95-point candidate was available. Long-term library consolidation, outdated-experience revision, and retrieval management also remain open.</p>\n<hr/>\n<h2 id=\"gpt-6-astra-jrt\">16. GPT-6-Astra-JRT (2026)</h2>\n<p>———From capability limits with demonstrations and interaction budgets to the gaps in real-world embodied intelligence</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.22471\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.22471</a> · <a href=\"https://sensenova.ai/has-gpt-6-astra-achieved-embodied-intelligence\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<h3 id=\"gpt-6-astra-jrt-takeaways\">Key takeaways</h3>\n<ol>\n<li>A general model’s embodied capabilities must be assessed together with the experience it can read, its control interfaces, and its interaction budget: this report freezes GPT-6-Astra’s weights, lets it organize training demonstrations into a retrievable knowledge package, and evaluates task completion through observation, action, verification, and correction.</li>\n<li>Additional interaction steps can unlock failure recovery, but the benefit depends on whether recovery remains possible; spilled liquid, parts dropped outside the workspace, and progress undone by later actions cannot automatically be recovered through repeated attempts.</li>\n<li>Effective collaboration between high-level reasoning and a low-level policy requires reviewing candidate actions, checking physical outcomes, and choosing suitable action-chunk lengths; simply delegating high-level subgoals to a VLA does not improve success in the reported ablations.</li>\n<li>The main deployment gaps concern physical-state verification, precise contact, transfer of experience across tasks, and the safety and mechanical costs of deliberation time; appearing complete, being declared complete, and being physically complete can be different states.</li>\n<li>Future evaluations should assess satisfaction of human needs, continuing obligations created by the robot, and timely action in an evolving world to distinguish benchmark success from deployable embodied intelligence.</li>\n</ol>\n<hr/>\n<h3 id=\"gpt-6-astra-jrt-background\">1. Background and problem</h3>\n<p>The Joint Research Team (JRT) report, <em>Has GPT-6-Astra Achieved Embodied Intelligence?</em>, examines whether a general model can handle tabletop manipulation, dexterous hands, humanoids, and navigation, while asking how much benchmark success depends on demonstrations, tools, and generous budgets. The authors conduct evaluations on 12 simulation benchmarks, harness ablations, validation on 8 real-robot configurations, and a household prototype that keeps running during deliberation to examine the gap between being capable of completing tasks and being reliable and efficient enough to deploy.</p>\n<hr/>\n<h3 id=\"gpt-6-astra-jrt-method\">2. Main methods and contributions</h3>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-icl-protocol.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Training demonstrations, a frozen knowledge package, and isolated test episodes</a>\n<figcaption>Original Figure 2: training data are used to construct and freeze a knowledge package, which is copied into isolated test episodes; neither the model weights nor the package are updated during testing.</figcaption>\n</div>\n<p><strong>① Overall framework: experience preparation, closed-loop reasoning, and action execution.</strong> The basic system has three stages: a knowledge package stores experience extracted from training data, GPT-6-Astra chooses actions using current observations and that experience, and robot-control interfaces execute the actions and return feedback; some ablations additionally introduce a VLA to propose candidate actions. The contribution is a systematic study of evaluation protocols and harness design; the report does not introduce a GPT-6-Astra model trained with a new loss function.</p>\n<p><strong>Experience preparation: turning demonstrations into files the model can retrieve and use.</strong> Inputs are the training demonstrations permitted by each benchmark, including images, actions, and robot states, with exploration in training scenes allowed in some settings; the model inspects these materials and writes task notes, reference data, and executable code, producing a knowledge package $K$ that is frozen before testing. The authors identify six recurring components: task goals and stage ordering, motion trajectories and grasp poses, demonstration keyframes and contact crops, programs for forward/inverse kinematics and retrieval, completion checks and recovery procedures, and robot specifications and provenance records; these are observed commonalities rather than a mandated template. Package contents also vary: LIBERO organizes composable atomic skills, SIMPLE retains numerical trajectories, and navigation packages retain landmarks, stopping guidance, and recovery experience.</p>\n<p><strong>Concept 1: ICL here involves more than a few demonstration images, and it does not update weights.</strong> In practical terms, the model first writes its own operating manual containing pictures, numerical examples, and programs, then consults it and adapts actions to the current scene during testing. Each test episode starts a fresh session with the same read-only package, retains only its own interaction history, and transfers no experience to other test episodes.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Training demonstrations or training-scene exploration\"] --&gt; B[\"Inspect data and write notes and programs\"]\n    B --&gt; C[\"Freeze knowledge package K\"]\n    C --&gt; D[\"Copy into a fresh test session\"]\n    E[\"Task instruction and current observations\"] --&gt; F[\"Retrieve experience and choose actions\"]\n    D --&gt; F\n    F --&gt; G[\"Controller executes actions\"]\n    G --&gt; H[\"Return new images and robot states\"]\n    H --&gt; F\n</code></pre>\n<p><strong>Closed-loop reasoning: using execution outcomes to revise the next action.</strong> At test time, the model reads the instruction, package, current images, permitted robot states, and episode history, retrieves reference motions or calls helpers, and produces an action or sequence; after execution, new observations inform whether to continue, adjust, recover, or stop. Visual references help compare the current stage with demonstration stages, while numerical references and programs turn experience into executable actions; observation access varies across benchmarks, so the experiments should not all be described as using an identical RGB-only interface.</p>\n<p><strong>Action execution: connecting high-level reasoning to existing robot interfaces.</strong> Inputs may specify end-effector positions and orientations, relative directions and distances, or joint targets; inverse kinematics or existing low-level controllers translate them into physical motion. This lets the model reason about where the gripper should move while controllers handle joint coordination; humanoid experiments also explore issuing targets directly to existing motor controllers without always going through a task-trained VLA.</p>\n<p><strong>Training and inference boundaries.</strong> GPT-6-Astra’s weights remain frozen throughout these experiments, so there is no additional model-training loss; ICL preparation produces an external knowledge package. System 1 in the collaboration experiments uses π0.5 fine-tuned on RoboDojo, which is separate from any update to GPT-6-Astra; inference consists of consulting experience, calling tools, executing actions, and revising decisions from feedback.</p>\n<p><strong>② Interaction budgets: measuring whether the model can progress after failure.</strong> The standard budget is the benchmark’s prescribed control-step limit, while the extended budget allows up to ten times as many steps; the main-text protocol emphasizes continuing from the same environment state and history, preserving consequences of prior actions and terminating early on success or terminal failure. Additional steps create opportunities to regrasp, change approach angles, relocalize, and correct errors; episodes need not consume the full extended budget.</p>\n<blockquote>\n<p><strong>Concept 2: a numerical example separating control steps from elapsed time.</strong> Consider a RoboDojo task with a standard budget of 200 steps at 25 Hz: 1× permits at most 8 seconds of commanded motion, while 10× permits at most 2,000 steps, or 80 seconds. Time spent observing, reasoning, and calling tools is outside those motion durations, so a simulated task with little commanded motion can still take tens of minutes or hours to run. A 10× budget also does not mean resetting the environment for ten independent attempts.</p>\n</blockquote>\n<p>Implementation details differ across benchmarks: the navigation appendices retain earlier successes, apply additional evaluation to unsuccessful episodes, and preserve better per-episode metrics, so these results cannot uniformly be interpreted as uninterrupted trajectories continued from exactly the same state. The aggregate table also distinguishes an independently executed 1× run from the 1× cutoff of a 10× run, and their results can differ.</p>\n<p><strong>③ Harness ablations: who proposes actions and who reviews them.</strong> The authors call the slower, reasoning-oriented GPT-6-Astra System 2 and the RoboDojo-fine-tuned π0.5 System 1, connecting them through different collaboration protocols. In open-loop collaboration, GPT specifies subgoals and the VLA directly executes joint-action sequences; in closed-loop collaboration, forward kinematics first converts VLA-proposed joint actions into candidate end-effector motions, which GPT accepts, modifies, or rejects using observations before execution and feedback.</p>\n<table>\n<thead>\n<tr>\n<th>Collaboration stage</th>\n<th>Open-loop collaboration</th>\n<th>Closed-loop collaboration</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>GPT inputs and outputs</td>\n<td>Produces subgoals from the current task</td>\n<td>Reviews candidate end-effector motions and accepts, modifies, or rejects them</td>\n</tr>\n<tr>\n<td>How VLA outputs reach the robot</td>\n<td>Candidate actions execute directly</td>\n<td>Candidate actions first undergo GPT review</td>\n</tr>\n<tr>\n<td>Main trade-off</td>\n<td>Fewer reasoning calls, but no action-level supervision</td>\n<td>Candidate actions can be corrected, but frequent review consumes many tokens</td>\n</tr>\n</tbody>\n</table>\n<p>The review horizon matters: $L=1$ means that each GPT call reviews one VLA-proposed end-effector action, while $L=4$ reviews four at once; this differs from direct-control experiments in which GPT generates multiple actions itself. The latter compare single actions, fixed four-action chunks, and adaptive chunks of one to four actions selected by GPT; longer chunks reduce calls but delay feedback, making the appropriate horizon dependent on the task stage.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-harness-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Success rates and token costs for RoboDojo harness ablations</a>\n<figcaption>Original Figure 7: success and token cost for different collaboration protocols and action interfaces on RoboDojo; success here is averaged equally across five task categories and should not be conflated with an average over all tasks.</figcaption>\n</div>\n<p>The appendix also ablates agent components individually: a feedback subagent checks outcomes, a planning subagent decomposes tasks, and an execution subagent generates end-effector actions; history compression retains the latest four turns and summarizes earlier interactions in at most 2,000 tokens. These components are added and compared separately, and the results do not establish that adding more modules always improves performance.</p>\n<p><strong>④ Real-robot validation: removing task demonstrations and cost-free retries.</strong> The real-world study covers 8 configurations spanning single arms, dual arms, dexterous hands, wheeled mobile manipulation, and humanoids, without task demonstrations or demonstration-derived packages; it still supplies structured priors such as tool descriptions, joint limits, camera placement, and hand open/close presets, with task guidance or human-written grasp scripts on some platforms. Zero-shot therefore refers to the absence of demonstrations and task-specific training while retaining human priors and controller support. Most trials use a 60-minute wall-clock budget, with platform-specific exceptions, and people judge success from the physical outcome.</p>\n<p>One transferable behavior is <strong>active vision: moving the camera to inspect the contact region before acting</strong>. When a single arm holds a flower stem, the nearby wrist camera cannot see the vase mouth below it; on the dual-arm platform, GPT moves the free arm and its wrist camera until the mouth becomes visible, then completes insertion, making viewpoint selection part of the action decision.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-active-vision.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: A dual-arm robot moves its free wrist camera to observe the vase mouth</a>\n<figcaption>Original Figure 9: insertion fails with an occluded close-up view on a single-arm platform; a dual-arm platform succeeds after moving its free wrist camera to view the vase mouth. This illustrates the role of viewpoint selection, without statistically isolating camera count or other platform differences.</figcaption>\n</div>\n<p><strong>⑤ Household prototype: evaluating whether the whole trajectory serves the user.</strong> The authors build an interactive Isaac Sim apartment with contact, articulated fixtures, liquids, cloth, and cooking processes; GPT controls an AgiBot G2 using only onboard cameras and proprioception, with no scene demonstrations, while deliberation advances world time. The proposed evaluation considers both the user’s explicit request, Intent, and continuing obligations, Duty, such as closing the refrigerator and turning off the tap while making breakfast.</p>\n<table>\n<thead>\n<tr>\n<th>Evaluation dimension</th>\n<th>Common static-goal evaluation</th>\n<th>Direction proposed in this report</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Task specification</td>\n<td>Prescribes target conditions for objects</td>\n<td>Expresses human needs and allows different useful outcomes</td>\n</tr>\n<tr>\n<td>Source of experience</td>\n<td>Uses task-training demonstrations</td>\n<td>Supplies no in-domain demonstrations and requires exploration during deployment</td>\n</tr>\n<tr>\n<td>Time accounting</td>\n<td>Pauses the world during reasoning and primarily counts actions</td>\n<td>Advances the world during reasoning, tool calls, and communication</td>\n</tr>\n<tr>\n<td>Outcome judgment</td>\n<td>Succeeds once a goal state is reached</td>\n<td>Assesses utility, timeliness, and obligations across the trajectory</td>\n</tr>\n</tbody>\n</table>\n<p>These are design principles and a proof of concept rather than a new benchmark with large-scale statistical rankings; illustrative breakfast deadlines and utility weights should not be treated as a validated universal scoring system.</p>\n<hr/>\n<h3 id=\"gpt-6-astra-jrt-results\">3. Main results and findings</h3>\n<p><strong>Simulation: demonstrations and additional interaction bring some benchmarks close to saturation, while long-horizon tasks retain substantial gaps.</strong> The table below prioritizes the corresponding appendix configurations and coverage, reporting full-task success rate, SR (%); RoboLab has no training set and is reported zero-shot without ICL.</p>\n<table>\n<thead>\n<tr>\n<th>Benchmark</th>\n<th style=\"text-align: right\">Standard budget 1×</th>\n<th style=\"text-align: right\">Extended evaluation up to 10×</th>\n<th>Interpretation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>LIBERO-Long++</td>\n<td style=\"text-align: right\">97.5</td>\n<td style=\"text-align: right\">100.0</td>\n<td>120 episodes; atomic-skill experience supports composition into task chains</td>\n</tr>\n<tr>\n<td>LIBERO-PRO</td>\n<td style=\"text-align: right\">98.3</td>\n<td style=\"text-align: right\">99.3</td>\n<td>All 800 episodes; experience from training exploration supports perturbation handling</td>\n</tr>\n<tr>\n<td>LIBERO-Ultra-Long</td>\n<td style=\"text-align: right\">82.2</td>\n<td style=\"text-align: right\">98.9</td>\n<td>90 episodes; additional interaction substantially helps long-chain correction</td>\n</tr>\n<tr>\n<td>RoboDojo, ICL direct control</td>\n<td style=\"text-align: right\">27.6</td>\n<td style=\"text-align: right\">81.9</td>\n<td>210 episodes, averaged over all 42 tasks</td>\n</tr>\n<tr>\n<td>RoboLab, no ICL</td>\n<td style=\"text-align: right\">57.1</td>\n<td style=\"text-align: right\">69.2</td>\n<td>No training demonstrations; results do not depend on a task knowledge package</td>\n</tr>\n<tr>\n<td>SIMPLE, ICL</td>\n<td style=\"text-align: right\">96.3</td>\n<td style=\"text-align: right\">98.8</td>\n<td>Only the 80 shared complete instances in Matched-8</td>\n</tr>\n<tr>\n<td>DexJoCo</td>\n<td style=\"text-align: right\">78.2</td>\n<td style=\"text-align: right\">87.3</td>\n<td>11 tasks and 55 episodes</td>\n</tr>\n<tr>\n<td>Bench2Dex</td>\n<td style=\"text-align: right\">25.6</td>\n<td style=\"text-align: right\">61.5</td>\n<td>26 tasks and 78 episodes; precise control remains difficult</td>\n</tr>\n<tr>\n<td>BEHAVIOR</td>\n<td style=\"text-align: right\">37.0</td>\n<td style=\"text-align: right\">Not extended</td>\n<td>One rollout for each of 100 tasks; the standard budget is already long</td>\n</tr>\n<tr>\n<td>VLN-CE R2R</td>\n<td style=\"text-align: right\">80.0</td>\n<td style=\"text-align: right\">88.0</td>\n<td>A subset of 100 episodes in unseen scenes</td>\n</tr>\n<tr>\n<td>VLN-CE RxR</td>\n<td style=\"text-align: right\">82.0</td>\n<td style=\"text-align: right\">90.0</td>\n<td>A selected subset of 100 English-language episodes</td>\n</tr>\n<tr>\n<td>LHPR-VLN</td>\n<td style=\"text-align: right\">21.1</td>\n<td style=\"text-align: right\">28.9</td>\n<td>114 long-horizon episodes manually filtered for target visibility</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Reporting distinctions.</strong> The report’s aggregate Table 2 lists a VLA-assisted 54.2% for the independent RoboDojo 1× run, whereas its 10× result and corresponding 1× cutoff are 81.9% and 27.6% for direct control; interpreting 54.2%→81.9% as a same-configuration budget ablation is therefore inappropriate. Table 13 and Figure 7 additionally average five categories equally, giving 29.67% for ICL direct control, consistent with 27.62% when averaging all 42 tasks above; SIMPLE’s 98.8% does not represent its complete six-task set, and navigation has the previously described rules for retaining better outcomes.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-benchmark-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: GPT-6-Astra success rates across twelve embodied benchmarks</a>\n<figcaption>Original Figure 1: overview of 12 benchmarks. Published baselines use standard budgets, so extended-budget results should not be interpreted as rankings at matched elapsed time, cost, or identical observation access.</figcaption>\n</div>\n<p><strong>Paired evidence more directly identifies the contribution of ICL.</strong> On SIMPLE’s Common-4 subset of 120 shared instances, standard-budget success increases from 70.8% zero-shot to 90.8% with ICL, a gain of 20.0 percentage points; among the 81 episodes solved in both settings, average action steps fall from 376.9 to 210.4 and test time from 47.0 to 31.4 minutes, while tokens increase from 2.64 million to 6.40 million, in addition to a one-time preparation cost per task. This 120-instance subset differs from the 80-instance Matched-8 set above, so their denominators must remain separate.</p>\n<p><strong>Harness ablations: closed-loop review and adaptation are more useful than simply adding execution modules.</strong> The following values use Figure 7’s equal weighting across five categories; tokens count millions of input and output tokens per episode, rather than dollar costs matched across systems.</p>\n<table>\n<thead>\n<tr>\n<th>Configuration</th>\n<th style=\"text-align: right\">SR (%)</th>\n<th style=\"text-align: right\">Tokens (millions)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>GPT direct-control baseline</td>\n<td style=\"text-align: right\">15.56</td>\n<td style=\"text-align: right\">2.560</td>\n</tr>\n<tr>\n<td>Standalone VLA π0.5</td>\n<td style=\"text-align: right\">6.91</td>\n<td style=\"text-align: right\">GPT tokens not reported</td>\n</tr>\n<tr>\n<td>GPT + VLA open-loop</td>\n<td style=\"text-align: right\">5.83</td>\n<td style=\"text-align: right\">0.387</td>\n</tr>\n<tr>\n<td>GPT + VLA closed-loop, per-action review</td>\n<td style=\"text-align: right\">23.61</td>\n<td style=\"text-align: right\">7.664</td>\n</tr>\n<tr>\n<td>GPT + VLA closed-loop, four-action review</td>\n<td style=\"text-align: right\">25.83</td>\n<td style=\"text-align: right\">2.796</td>\n</tr>\n<tr>\n<td>GPT + ICL</td>\n<td style=\"text-align: right\">29.67</td>\n<td style=\"text-align: right\">9.567</td>\n</tr>\n<tr>\n<td>GPT + ICL + VLA closed-loop</td>\n<td style=\"text-align: right\">54.17</td>\n<td style=\"text-align: right\">19.335</td>\n</tr>\n<tr>\n<td>GPT with adaptive generated action chunks</td>\n<td style=\"text-align: right\">20.00</td>\n<td style=\"text-align: right\">1.146</td>\n</tr>\n</tbody>\n</table>\n<p>Reviewing four actions at once reduces tokens by 63.5% relative to per-action review while increasing success by 2.22 percentage points; ICL combined with closed-loop collaboration reaches the highest success but consumes about 6.9 times as many tokens as four-action review. In direct control, relative directional commands achieve 18.06% versus 9.72% for joint-angle control, suggesting an interface gap between semantic reasoning and low-level action representations; fixed four-action chunks achieve only 11.39%, showing that longer chunks do not automatically improve outcomes. In the appendix, adding a feedback subagent independently raises baseline SR from 15.56% to 24.72%; history compression raises it to 21.11% while reducing tokens from 2.56 million to approximately 0.86 million.</p>\n<p><strong>High success can still be expensive.</strong> At the standard budget, LIBERO-Long++ averages approximately 1.04 million tokens and 53.1 minutes per episode, while Ultra-Long averages 8.89 million tokens and 110.9 minutes. Extended RoboDojo evaluation averages approximately 38.63 million tokens and 216.6 minutes, excluding ICL preparation; Figure 5 also states that approximately 98% of tokens in the runs are cached inputs, so total tokens cannot simply be priced at the uncached-input rate. Benchmarks differ in their treatment of tool and simulation time, and some token records are incomplete; these figures indicate scale under the report’s accounting conventions rather than a strictly uniform ranking of end-to-end latency.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-compute-cost.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Knowledge-package preparation, standard-budget execution, and extended-interaction costs</a>\n<figcaption>Original Figure 5: token and time costs of ICL preparation, standard-budget execution, and additional interaction. Success gains from extra steps should be assessed alongside computation, waiting time, and preparation costs.</figcaption>\n</div>\n<p><strong>Real robots: cross-embodiment feasibility, with remaining gaps in precise contact and long-horizon reliability.</strong> Rigid-object pick-and-place succeeds in 17/18 trials, while plug insertion succeeds in 0/11 across three platforms; AgileX Tracer navigation and search achieve 9/23. On the Tianji dexterous hands, toy grasping succeeds in 0/3 trials with model-written grasp code and 3/3 with human-written grasp scripts, demonstrating the influence of structured priors; Unitree G1 achieves 2/3 in manipulation and 3/3 in locomotion, with its two successful manipulation runs taking approximately 74.5 and 87.8 minutes and API requests accounting for approximately 89%–92% of elapsed time. These small samples establish feasibility more than stable reliability.</p>\n<p><strong>Failure modes: choosing the next step does not guarantee that correct physical states persist.</strong> Examples include treating image overlap between a mug handle and peg as evidence of successful hanging, undoing an earlier placement while adjusting headphones, and being unable to restore a task after spilled liquid even when the cup is righted. The continuously running household prototype reveals three additional problems: focusing on the held object while overlooking displaced items or an open refrigerator, failing to discover unfamiliar mechanisms and plan whole-body positioning, and acting on images that become outdated during deliberation; these are qualitative cases rather than statistically measured failure rates on a new benchmark.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/vla/GPT-6-Astra-JRT-household-failures.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Collisions, forgotten obligations, and delayed actions in a continuously running household</a>\n<figcaption>Original Figure 12: representative household failures include disturbing objects while tidying, leaving the refrigerator open, obstructing access through poor body positioning, overflowing the sink, and charring an egg through decision and execution delays.</figcaption>\n</div>\n<hr/>\n<h3 id=\"gpt-6-astra-jrt-limitations\">4. Limitations</h3>\n<p>Knowledge packages largely depend on task-related demonstrations, and transfer across tasks and embodiments is not systematically validated; observations, interfaces, coverage, budget-extension procedures, and cost accounting vary across benchmarks, without matching inference costs to prior methods, so the results better characterize capability limits than establish uniform system rankings. Most real-robot tasks have few trials, some rely on expert priors and differing success criteria, and the household prototype offers only a few qualitative cases whose physical fidelity, utility scoring, and continuous-time protocol require further validation.</p>\n<hr/>\n<h2 id=\"evo2\">17. Evo² (2026)</h2>\n<p>———Co-evolving the agent harness and the model that improves it</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2610.13025\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2610.13025</a></p>\n<p><strong>Why it is included</strong>: Evo² is evaluated directly on coding and memory tasks rather than on robots or embodied benchmarks. Its weight-harness co-evolution, execution-based attribution, cross-branch strategy reuse, and trajectory recovery nevertheless address mechanisms that embodied agents need for long-running harness evolution. This entry treats those mechanisms as transferable research ideas and does not extrapolate coding-benchmark gains into robot performance.</p>\n<h3 id=\"evo2-highlights\">Highlights</h3>\n<p>Evo² does not optimize model weights and the agent harness as separate artifacts; it turns them into a feedback loop in which better models produce stronger harness edits and evaluated edits become training data for the model. A single shared policy plays two roles: the Proposer writes executable changes, while the Reflector diagnoses their effects and recommends revision, crossover, or retention. EvoTIDE recovers useful data from incomplete edit trajectories, warm-starts the policy with SFT, and then interleaves GRPO updates across both roles. The resulting harnesses improve coding and memory tasks, transfer across benchmarks, and can also improve proprietary models whose weights remain fixed. The broader lesson is to treat an executable system as an experience generator whose structural changes can supervise the policy responsible for future changes.</p>\n<hr/>\n<h3 id=\"evo2-background\">1. Background / Problem</h3>\n<p>Self-evolving agents usually follow one of two paths: update model weights from self-generated experience, or rewrite the agent harness that controls prompts, tools, context, and execution flow. The former improves the model’s problem-solving behavior, while the latter accumulates improvements in executable code, but separating them prevents the model from learning systematically which harness changes work. Evo² asks whether every edit, execution result, and failure diagnosis can train a stronger evolver that drives the next round of harness search.</p>\n<hr/>\n<h3 id=\"evo2-method\">2. Main Method / Contributions</h3>\n<h4 id=\"evo2-coevolution-loop\">2.1 The weight-harness co-evolution loop</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Evo2-weight-harness-coevolution.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The Evo² weight-harness co-evolution loop</a>\n<figcaption>The Evo² feedback loop: a shared Proposer-Reflector policy improves the agent harness, while edits, trajectories, and execution feedback train a stronger evolver.</figcaption>\n</div>\n<p>Evo² combines three coupled components. A <strong>harness tree</strong> stores program variants and their evaluation records; a <strong>shared dual-role evolver</strong> proposes changes and interprets their outcomes; and <strong>EvoTIDE</strong> converts search trajectories into weight-training data. The task executor stays fixed during co-evolution, so changes in candidate performance can be attributed to the harness rather than to a simultaneously changing execution model.</p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Separate self-evolution</th>\n<th>Evo² co-evolution</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Where experience accumulates</td>\n<td>Model weights or harness code</td>\n<td>Both the harness and the evolver</td>\n</tr>\n<tr>\n<td>Capability of the editor</td>\n<td>The same untrained model continues searching</td>\n<td>Search outcomes train the next editor</td>\n</tr>\n<tr>\n<td>Search structure</td>\n<td>A single lineage or candidate archive</td>\n<td>A tree with strategy transfer across branches</td>\n</tr>\n<tr>\n<td>Role of feedback</td>\n<td>Candidate selection</td>\n<td>Editing, diagnosis, and stop decisions</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"evo2-dual-role-evolution\">2.2 Dual-role harness evolution</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Evo2-harness-evolution-pipeline.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The Evo² dual-role harness-evolution and trajectory-collection pipeline</a>\n<figcaption>Harness evolution and trajectory collection: a sampled parent is edited and evaluated before the Reflector chooses revision, crossover, or retention.</figcaption>\n</div>\n<p><strong>Proposer: input, transformation, output.</strong> In Type A mode, the Proposer receives a parent harness, its evaluation history, and a role prompt. It independently selects a mechanism to improve and emits executable file edits that create an initial candidate. In Type B mode, it also receives a concrete edit directive from the Reflector and turns that diagnosis into code. Type A learns to discover improvements; Type B learns to implement feedback reliably.</p>\n<p><strong>Reflector: input, transformation, output.</strong> The Reflector receives the parent and child harnesses, their edit diff, the performance change, and relevant success and failure traces. It infers what strategy the edit attempted and chooses one of three actions: <code class=\"language-plaintext highlighter-rouge\">revise</code> provides a local correction, <code class=\"language-plaintext highlighter-rouge\">crossover</code> imports a strategy from another branch, and <code class=\"language-plaintext highlighter-rouge\">keep</code> retains the candidate without further editing. The quality of a directive is measured by the performance of the harness produced after the Proposer executes it, rather than by the apparent quality of the text itself.</p>\n<p><strong>Crossover searching.</strong> The system extracts mechanisms and observed effects from evaluated harnesses into a strategy library. When the current branch exhibits a weakness, the Reflector can select a donor strategy from another branch and explain how to adapt it to the current recipient. The Type B Proposer performs the source-level integration. The resulting node remains a child of the recipient and records the donor strategy, so Evo² transfers an evaluated mechanism instead of blindly merging two codebases.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Sample a parent from the harness pool\"] --&gt; B[\"Proposer Type A: autonomous edit\"]\n    B --&gt; C[\"Run and score with a fixed executor\"]\n    C --&gt; D{\"Reflector decision\"}\n    D -- \"revise\" --&gt; E[\"Issue a local edit directive\"]\n    D -- \"crossover\" --&gt; F[\"Select a strategy from another branch\"]\n    D -- \"keep\" --&gt; G[\"Retain the current candidate\"]\n    E --&gt; H[\"Proposer Type B: implement directive\"]\n    F --&gt; H\n    H --&gt; I[\"Run, score, and extend the tree\"]\n    G --&gt; I\n    I --&gt; J[\"Send trajectories to EvoTIDE\"]\n</code></pre>\n<p>This simplified view shows one complete loop: edit, execute, and reflect. A second edit occurs only after revision or crossover. <code class=\"language-plaintext highlighter-rouge\">keep</code> is therefore also a learned action: stopping when another edit is unlikely to help saves evaluation budget.</p>\n<h4 id=\"evo2-evotide\">2.3 EvoTIDE: learning from harness evolution</h4>\n<p>One <code class=\"language-plaintext highlighter-rouge\">propose → evaluate → reflect → revise</code> cycle can produce three trajectory types: an autonomous Proposer trajectory, a Reflector trajectory, and a directed Type B Proposer trajectory. EvoTIDE first builds a balanced mixture of successful examples for SFT and then performs interleaved GRPO over both roles as the harness tree grows. At each training round, it freezes a policy snapshot to provide counterpart behavior for the role being optimized; the snapshot is refreshed after the round, reducing instability from both roles changing at once.</p>\n<p>Trajectory recovery addresses a common systems failure: a rollout may contain several valid edits but end with a malformed tool action. <strong>Edit extraction</strong> recovers concrete changes mentioned in reasoning or chat messages. <strong>Prefix continuation</strong> truncates the rollout after its last successful edit, restores the corresponding intermediate harness, and regenerates only the failed suffix.</p>\n<blockquote>\n<p><strong>Minimal example</strong>: suppose a rollout produces three edits. The first two apply successfully, but the third uses an invalid tool format. Discarding the rollout would waste both valid edits. Prefix continuation restores the harness after Edit 2 and regenerates Edit 3; if the new suffix passes application, startup, and task-evaluation checks, the recovered trajectory becomes training data.</p>\n</blockquote>\n<h4 id=\"evo2-training-flow\">2.4 Rewards, parent sampling, and end-to-end flow</h4>\n<p>Both roles receive execution rewards based on the task-score change caused by their decision. For a Proposer edit from parent harness $h$ to $h’$:</p>\n\n\\[r_P^{\\mathrm{exec}} = \\hat V(h') - \\hat V(h)\\]\n\n<p>For a Reflector intervention that changes candidate <code class=\"language-plaintext highlighter-rouge\">h_0</code> into <code class=\"language-plaintext highlighter-rouge\">h_1</code>:</p>\n\n\\[r_R^{\\mathrm{exec}} = \\hat V(h_1) - \\hat V(h_0)\\]\n\n<p>Malformed, non-executable, or no-op edits receive negative rewards. A Reflector is credited for adding a mechanism only when execution traces show that the mechanism actually ran, which reduces accidental reward assignment. The bounded parent pool retains candidates from several tree depths, including strong harnesses that may improve further and weaker harnesses that teach repair behavior, while reserving a fixed sampling share for the root.</p>\n<p>End to end, a parent harness undergoes a Type A edit, fixed-executor evaluation, Reflector diagnosis, and an optional Type B revision. The evaluated candidate enters the tree and strategy library; recovered trajectories support SFT and then role-grouped GRPO. The updated shared policy drives the next search round, closing the loop between better evolvers and better harnesses.</p>\n<hr/>\n<h3 id=\"evo2-results\">3. Key Results / Findings</h3>\n<p>With Qwen3.8-27B, Evo² produces the strongest self-evolved harness on all three coding benchmarks. It reaches <strong>82.1% Pass@1</strong> on Polyglot versus 62.6% for the strongest baseline, <strong>48.3% Resolved</strong> on SWE-bench Verified versus 41.0%, and <strong>58.0% Pass@1</strong> on LiveCodeBench versus 56.0%. In cross-benchmark evaluation, Evo² ranks first in five of six transfer directions, indicating that the learned harnesses contain reusable mechanisms rather than benchmark-specific patches.</p>\n<p>Weight evolution contributes consistently. Compared with the untrained evolver, EvoTIDE adds <strong>+16.3, +5.0, +9.3, and +10.6</strong> percentage points on Polyglot, SWE-bench Verified, LoCoMo, and LongMemEval, respectively. Even when proprietary-model weights stay fixed, dual-role reflection and crossover raise GPT-5-mini to <strong>48.3%</strong> on a 60-task SWE-bench Verified subset, compared with 24.4% for the strongest baseline.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Evo2-accuracy-efficiency.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Evo² LiveCodeBench accuracy versus inference cost</a>\n<figcaption>LiveCodeBench accuracy versus inference cost: Evo² obtains the highest Pass@1 while using fewer completion tokens and fewer LLM calls.</figcaption>\n</div>\n<p>The gain is not explained by a larger inference budget. The Evo² LiveCodeBench champion uses about 3.6K completion tokens and 10.2 LLM calls per task; HGM and DGM score lower while consuming about 6.6K-6.9K tokens and 26-37 calls. Beyond coding, Evo² reaches <strong>60.4 F1</strong> on LoCoMo, and the same harness transfers to LongMemEval-S without further evolution, achieving <strong>71.5% accuracy</strong>.</p>\n<hr/>\n<h3 id=\"evo2-limitations\">4. Limitations</h3>\n<p>Evo² still requires many real task executions to evaluate harness candidates, so search and training costs can grow quickly with task complexity and tree size. Keeping the executor fixed improves causal attribution but does not fully represent deployments where the executor and harness change together, and the evidence is currently concentrated on coding and memory tasks rather than high-risk, strongly stateful real-world agents.</p>\n<hr/>\n<h2 id=\"dream-rsi\">18. Dream-RSI (2026)</h2>\n<p>———Turning historical discovery trees into a replay environment, so exploration policies are screened offline before the next real search</p>\n<p>📄 <strong>Paper</strong>: <a href=\"https://arxiv.org/abs/2609.14858\" rel=\"noopener noreferrer\" target=\"_blank\">arXiv:2609.14858</a> · <a href=\"https://github.com/zhengkid/Dream-RSI\" rel=\"noopener noreferrer\" target=\"_blank\">Code</a> · <a href=\"https://dream-rsi.com/\" rel=\"noopener noreferrer\" target=\"_blank\">Project Page</a></p>\n<p><strong>Why it is included</strong>: The paper has no embodied tasks, robot simulation, or real-robot experiments. It is included because its discovery-tree replay and exploration-scheduling mechanism may inform active exploration, failure recovery, and harness evolution for embodied agents; those applications still need separate validation.</p>\n<blockquote>\n<p>Version note: this entry follows the full PDF of arXiv v2 (6 October 2026); Figures 1–2 and Figures 3–7 are all taken from that version.</p>\n</blockquote>\n<h3 id=\"dream-rsi-highlights\">Highlights</h3>\n<p>Dream-RSI stores the exploration an agent has already done as a <strong>discovery tree</strong> with scores and costs, so a candidate scheduling policy can be replayed along the tree instead of re-running every expensive candidate generation. A policy-development agent edits the executable code that decides whether to open a new branch, dig deeper, parallelize, or stop; after comparing versions across many historical trees, it sends the winner back to online discovery. Each online run produces a new tree, which adds experience for the next round of replay. This loop improves the <strong>exploration orchestrator</strong>, not the underlying model weights; it offers a transferable idea for self-evolving agent harnesses, but the paper has no robot validation.</p>\n<hr/>\n<h3 id=\"dream-rsi-background\">1. Background / Problem</h3>\n<p>Long-horizon algorithm discovery often needs many propose-execute-score cycles, and a fixed exploration policy can keep investing in low-yield directions. If every new scheduling policy required re-running an entire online search, evaluating the policy would cost more than evaluating a single candidate, and feedback would arrive only after a long rollout. The paper asks whether existing execution history can be used to evaluate the next exploration policy cheaply.</p>\n<hr/>\n<h3 id=\"dream-rsi-method\">2. Main Method / Contributions</h3>\n<h4 id=\"dream-rsi-interface\">2.1 Overall framework: online exploration, historical replay, policy improvement</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-overview.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: The Dream-RSI recursive loop of online exploration, replay simulation, and policy improvement</a>\n<figcaption>Paper Figure 1: Online exploration produces a discovery tree; the tree enters a replay pool; the policy-development agent repeatedly replays and edits the scheduling code, then redeploys the winner.</figcaption>\n</div>\n<p>The <strong>online exploration module</strong> takes the current exploration policy, the initial workspace, and earlier history. The policy chooses which nodes to continue from and assigns parallel jobs to a fixed discovery agent. Each new node stores its parent, a workspace snapshot, the full observation, and the score returned by a fixed evaluator, so one real search leaves a reusable tree-shaped record.</p>\n<p><strong>Discovery trees and the shared decision interface</strong>: the tree is rooted at the initial workspace $r$ (root score 0). Every non-root node has exactly one parent: the discovery agent resumes from the parent’s saved workspace and inherits its accumulated observations. The selectable set $A(\\mathcal T)$ is the root plus all current leaves. With $W$ parallel workers, the policy outputs a batch of at most $W$ nodes per round, deciding both where to continue and how many attempts run at once. Online and offline phases share this interface and differ only in state transition: online executes for real (with stochastic outcomes), while offline only replays records.</p>\n<p>The <strong>replay simulator</strong> treats a recorded tree as a local environment: another policy sees only the nodes revealed so far, and after it chooses, the system reveals the corresponding children from the record. It needs no further calls to the base agent or evaluator, but it cannot produce branches absent from the history. The <strong>policy-development module</strong> receives the replay trajectories and scores of different candidate programs over many trees, revises the exploration policy, and hands the version with the best average replay score to the next round of online exploration.</p>\n<pre><code class=\"language-mermaid\">graph TD\n    A[\"Online exploration: policy drives the fixed discovery agent\"] --&gt; B[\"Record nodes, observations, scores, and costs\"]\n    B --&gt; C[\"Add the tree to the historical pool\"]\n    C --&gt; D[\"Offline dreaming: candidate policies replay recorded nodes\"]\n    D --&gt; E[\"Score by quality, calls, and parallel rounds\"]\n    E --&gt; F[\"Deploy the highest-scoring policy code\"]\n    F --&gt; A\n</code></pre>\n<h4 id=\"dream-rsi-replay-tree\">2.2 Sticking point 1: how can a historical tree evaluate a new policy that never actually ran?</h4>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-replay-tree.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Different exploration policies replaying along the same historical discovery tree</a>\n<figcaption>Paper Figure 2: A candidate policy changes the visiting order, parallel grouping, and stopping point over recorded branches; replay feedback comes from nodes that were actually saved.</figcaption>\n</div>\n<blockquote>\n<p><strong>Example</strong>: a real exploration recorded two branches. Branch A has three consecutive nodes scoring 0.2, 0.3, 0.3; branch B has two nodes scoring 0.4, 0.8. A fixed policy spends 3 calls digging into A before opening B; a new policy opens A, then B, and reaches 0.8 along B by its third call. Offline replay can compare the “best score versus calls” curves of the two <strong>visiting orders</strong> because the node outcomes are already recorded. If the new policy wanted to explore an unrecorded branch C, replay has no answer, and it must actually run online to find out.</p>\n</blockquote>\n<p>During offline replay, a selected leaf reveals only the <strong>single</strong> child recorded for it in the original tree; if the root is selected, replay opens the earliest-created branch under the root that has not yet been revealed; if no unrevealed successor remains, it returns empty. Each non-empty batch counts as one round, replay runs for at most $K_2$ rounds, and it stops early when a batch is empty. Replay therefore has no shortcut for peeking at future nodes, and its evaluation range is strictly bounded by the historical tree.</p>\n<h4 id=\"dream-rsi-replay\">2.3 Sticking point 2: why not just pick the policy with the highest score?</h4>\n<p>The system replays the same policy once for each budget preference $\\rho\\in{0,0.25,0.5,0.75,1}$, producing quality-cost points: quality is the best score among revealed nodes divided by the best score recorded in that tree, and cost is the number of discovery-agent calls in the replay. It keeps only the Pareto points that no other point beats in both quality and cost, then scores them as follows (for tree $i$ and policy version $m$):</p>\n\n\\[V_i^m=\\frac{1}{B_i}\\sum_{j=1}^{L}\\left(\\bar a_j-\\bar a_{j-1}\\right)\\left(B_i-\\bar n_j\\right)-\\lambda\\,\\frac{1}{\\lvert\\mathcal R\\rvert}\\sum_{\\rho\\in\\mathcal R}\\frac{k_\\rho}{n_\\rho}\\]\n\n<p>The first term is a normalized hypervolume: $B_i$ is the number of evaluated nodes in that tree, and $\\bar a_j$, $\\bar n_j$ are the quality and call count of the $j$-th Pareto point, so higher quality with fewer calls gives a larger area. In the second term, $k_\\rho$ is the number of sequential rounds and $n_\\rho$ the number of calls; a larger ratio means less parallelism, and $\\lambda$ sets the penalty strength. Finally, scores are averaged over all historical trees to give $V^m$, so the policy does not overfit the accidental structure of a single tree.</p>\n<table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Final best score only</th>\n<th>Dream-RSI replay score</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Search cost</td>\n<td>A late discovery of a high score can still earn full marks</td>\n<td>Records the calls needed to reach each quality level</td>\n</tr>\n<tr>\n<td>Parallel efficiency</td>\n<td>Does not distinguish serial from parallel</td>\n<td>Penalizes too many sequential decision rounds</td>\n</tr>\n<tr>\n<td>Budget preference</td>\n<td>A single cutoff point</td>\n<td>Sweeps multiple budgets and compares the quality-cost frontier</td>\n</tr>\n</tbody>\n</table>\n<p>The policy-development agent repeatedly rewrites the executable scheduling code and includes the currently deployed policy in the candidate set, so the selected policy never scores lower than the old one on the <strong>average replay score over the existing historical trees</strong>. This is an offline selection property; it does not guarantee that scores on new tasks or in real online runs rise monotonically.</p>\n<h4 id=\"dream-rsi-loop\">2.4 Recursive evolution and inference flow</h4>\n<p>In online round $t$, the current policy drives the discovery agent to generate a new tree (using the full earlier history as context, kept separate from the tree under construction) for at most $K_1$ rounds; when the tree is finished it joins the historical pool. The offline phase then builds $M$ policy versions: the policy-development agent inspects the previous version’s replay trajectories and scores plus feedback from earlier revisions, identifies successful decisions and recurring failures, rewrites the executable policy code into the next version, and re-evaluates it on all the same historical trees. The currently deployed policy $\\pi^0$ always stays in the candidate set, and the version with the highest average replay score among the $M$ becomes the next online policy. Once deployed, the new policy may reach regions never visited before, and its new real results widen the coverage of the next round of replay. The base discovery model, candidate evaluator, and execution interface stay fixed; what changes is the code that orchestrates search resources. The paper does not complete this self-improvement loop by updating model weights.</p>\n<hr/>\n<h3 id=\"dream-rsi-results\">3. Core Results / Findings</h3>\n<p>The current arXiv v2 evaluates four task families and nine concrete tasks: four GPU kernels in KernelBench, three mathematical-optimization problems, Lasso path solving, and one agent-harness optimization. The main controlled baseline for scientific-discovery tasks, <strong>Recursive Fixed Exploration</strong>, uses the same discovery agent, evaluator, initial policy, and per-round budget, and only keeps the exploration policy from updating.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-lasso-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Quality and call-cost comparison of Dream-RSI and fixed exploration on Lasso path solving</a>\n<figcaption>Paper Figure 4: (a) Final runtime (ms, lower is better) on six held-out Lasso datasets; (b) average runtime versus cumulative discovery calls across recursive rounds, labeled by round. On both backbones Dream-RSI finds faster solvers with fewer calls.</figcaption>\n</div>\n<p>In the Lasso experiments, with Gemini 3.7 Flash the average runtime falls from <strong>2516.7 ms</strong> under the fixed policy to <strong>2350.6 ms</strong>, and discovery-agent calls drop from <strong>3200</strong> to <strong>1879</strong>; with Gemini 3.1 Pro the numbers are <strong>3587.1 → 2931.0 ms</strong> and <strong>550 → 317 calls</strong>. The paper also notes that on the Pro backbone the average gain is driven mainly by the RCV1 dataset, while the other five held-out datasets are actually slower, so the average should not be read as a gain on every dataset; on the Flash backbone, five of six datasets are faster. The solvers from both backbones beat sklearn and glmnet on all six held-out datasets. Compared with the 51,200 generations reported for SimpleTES, the Pro and Flash runs use roughly <strong>162× and 27× fewer</strong> discovery-agent calls and reach lower average runtime, but the backbone models differ, so this is not a strictly like-for-like comparison.</p>\n<p>In round 1 the two methods are identical by design; afterward the fixed policy stays static, while Dream-RSI “dreams” again each round over the accumulated history. By the final round, Dream-RSI reaches lower average runtime with fewer calls on both backbones (Figure 4(b)). The paper analyzes the discovered solver: SimpleTES switches between LARS and coordinate descent depending on problem dimension, whereas this solver makes the active-set optimization itself adaptive, combining strong-rule screening with Cauchy–Schwarz KKT pruning, computing exact gradients only when necessary and refreshing in full once pruning stops being effective.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-kernel-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Exploration performance versus number of generations on four GPU kernel tasks</a>\n<figcaption>Paper Figure 3: Performance (1/ms, higher is better) versus number of generations on four GPU kernel tasks; VGG16 and LayerNorm reach similar performance with fewer generations, while ConvDiv and ConvMax improve performance under comparable budgets.</figcaption>\n</div>\n<p>On KernelBench, VGG16 and LayerNorm reach similar performance with <strong>2.43× and 1.79× fewer generations</strong>; ConvDiv and ConvMax reach <strong>2.09× and 1.44× higher performance</strong> under comparable budgets, and surpass the PACEvolve baseline capped at two days. The kernel discovered for ConvDiv does not optimize convolution in isolation but restructures the operator chain around downstream pooling and reduction: adjacent convolution outputs are max-pooled immediately, width pooling and later reductions run directly on register-resident values, avoiding materialization of convolution and pooled feature maps, while linear operations such as scaling, averaging, and bias accumulation are deferred to a lightweight final reduction. In mathematical optimization, Sum–Difference scores <strong>1.145427</strong>, above SimpleTES’s 1.143975 and the fixed policy’s <strong>1.144047</strong>; Circle Packing reaches <strong>2.635983</strong>, tying the strongest compared result; Autocorrelation’s <strong>1.456375</strong> is slightly worse than the fixed policy’s <strong>1.456001</strong> (lower is better), so the advantage does not cover every task.</p>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-harness-results.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Discovery process and method comparison for harness optimization on Terminal-Bench 2.1</a>\n<figcaption>Paper Figure 5: (a) Best-so-far Terminal-Bench 2.1 score during discovery, rising from the 0.7247 seed to 0.8090; (b) full-suite comparison with Claude Code (CC), Terminus-Kira (TK), and Meta-Harness (MH).</figcaption>\n</div>\n<p>The harness-optimization experiment follows the Meta-Harness setup, starts from Terminus-Kira as the seed harness, and evaluates on the 89 Terminal-Bench 2.1 tasks with two independent runs per task; the discovery agent, policy-development agent, and evaluation all use Claude Opus 4.8 (Claude Code). The full-suite score rises from <strong>0.7247</strong> to <strong>0.8090</strong>, above Claude Code’s 0.75 and the reproduced Meta-Harness’s 0.79 (Terminus-Kira scores 0.72). The paper runs no fixed-exploration control for this task, estimating that another full search would cost over USD 100,000, so the result mainly shows the final quality of the discovered harness and cannot isolate the contribution of replay-based policy improvement over fixed exploration.</p>\n<p><strong>Further analysis (all on ConvDiv):</strong></p>\n<ul>\n<li><strong>Accumulated replay worlds help</strong>: replaying over the full history gives performance <strong>1.90</strong> (786 calls), while using only the current round’s history gives <strong>1.59</strong> (430 calls). The authors suggest that multiple trees help learn a more general policy and avoid being overly conservative when fitted to a single world.</li>\n<li><strong>Replay beats writing history into the prompt</strong>: abstracting history into directional semantic guidance injected into the prompt lowers final performance for both Dream-RSI and the fixed policy (Figure 6); the authors argue such guidance may constrain exploration.</li>\n<li><strong>Exploration behavior adapts to the stage</strong>: as performance improves, the number of attempts evaluated per round first drops from 110 to 50; once progress stalls it rises back to about 90 and further gains follow (Figure 7).</li>\n</ul>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-guidance-ablation.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Replaying history versus prompt guidance on ConvDiv</a>\n<figcaption>Paper Figure 6: On ConvDiv, replaying history (Dream-RSI) beats using history only as prompt guidance.</figcaption>\n</div>\n<div align=\"center\">\n<a class=\"source-figure\" href=\"https://tingdeliu.github.io/images/agent/Dream-RSI-exploration-evolution.webp\" rel=\"noopener noreferrer\" target=\"_blank\">View original figure: Evolution of the exploration policy across recursive rounds on ConvDiv</a>\n<figcaption>Paper Figure 7: (a) Round-best performance and (b) number of evaluated attempts across recursive rounds on ConvDiv.</figcaption>\n</div>\n<hr/>\n<h3 id=\"dream-rsi-limitations\">4. Limitations</h3>\n<p>Replay is deterministic for recorded nodes but cannot evaluate branches that were never reached; insufficient historical coverage, task-distribution shift, or stochastic execution can all open a gap between offline selection and real performance. The experiments focus on software and mathematical discovery, with no robot simulation or real-robot validation; transferring to embodied agents would require handling irreversible actions, state drift, and safety constraints. The paper uses discovery-agent calls as its main search-cost metric, and storing and replaying history also consumes storage and compute. The Lasso results further show that average gains may be driven by individual datasets, and that cross-backbone comparisons (for example against SimpleTES) are not like-for-like.</p>\n<hr/>\n<h1 id=\"参考资料\">References</h1>\n<h2 id=\"论文引用\">Paper citations</h2>\n<ol>\n<li><strong>HoloAgent-0</strong> (2026). HoloAgent: A Closed-Loop Embodied Agent Operating System with Hierarchical Spatial Memory. arXiv: <a href=\"https://arxiv.org/abs/2606.23565\" rel=\"noopener noreferrer\" target=\"_blank\">2606.23565</a> · Code: <a href=\"https://github.com/HorizonRobotics/HoloAgent\" rel=\"noopener noreferrer\" target=\"_blank\">HorizonRobotics/HoloAgent</a></li>\n<li><strong>Pigey</strong> (2026). Addressing the Orchestration Gap in Generalist Robots via Physical Agency. arXiv: <a href=\"https://arxiv.org/abs/2607.21725\" rel=\"noopener noreferrer\" target=\"_blank\">2607.21725</a></li>\n<li><strong>Thea</strong> (2026). Towards the Harness of Embodied Agents. arXiv: <a href=\"https://arxiv.org/abs/2608.11246\" rel=\"noopener noreferrer\" target=\"_blank\">2608.11246</a> · Code: <a href=\"https://github.com/EIT-HAI/Thea\" rel=\"noopener noreferrer\" target=\"_blank\">EIT-HAI/Thea</a> · Project Page: <a href=\"https://eit-hai.github.io/thea\" rel=\"noopener noreferrer\" target=\"_blank\">eit-hai.github.io/thea</a></li>\n<li><strong>Zetta</strong> (2026). An Efficient Closed-Loop Embodied Harness for Self-Evolving Physical Intelligence. arXiv: <a href=\"https://arxiv.org/abs/2608.16590\" rel=\"noopener noreferrer\" target=\"_blank\">2608.16590</a> · Project Page: <a href=\"https://air-embodied-brain.github.io/zetta\" rel=\"noopener noreferrer\" target=\"_blank\">air-embodied-brain.github.io/zetta</a></li>\n<li><strong>Show-Harness</strong> (2026). Show-Harness: Just a VLM Agent Can Play Robots. arXiv: <a href=\"https://arxiv.org/abs/2609.10522\" rel=\"noopener noreferrer\" target=\"_blank\">2609.10522</a> · Project Page: <a href=\"https://showlab.github.io/Show-Harness\" rel=\"noopener noreferrer\" target=\"_blank\">showlab.github.io/Show-Harness</a></li>\n<li><strong>SPACE</strong> (2026). Act More, Decide Less: Skill-Guided Adaptive Action Chunking for Long-Horizon LLM Agents. arXiv: <a href=\"https://arxiv.org/abs/2609.02042\" rel=\"noopener noreferrer\" target=\"_blank\">2609.02042</a></li>\n<li>\n<p><strong>ABot-AgentOS</strong> (2026). Universal robot Agent operating system and lifelong multi-modal memory system for embodied intelligence. arXiv: <a href=\"https://arxiv.org/abs/2607.10350\" rel=\"noopener noreferrer\" target=\"_blank\">2607.10350</a> · Project Page: <a href=\"https://amap-cvlab.github.io/ABot-AgentOS\" rel=\"noopener noreferrer\" target=\"_blank\">ABot-AgentOS</a></p>\n</li>\n<li><strong>ABot-ER</strong> (2026). ABot-ER: Unified Embodied Reasoning through Agentic Data–Model Co-Evolution. arXiv: <a href=\"https://arxiv.org/abs/2610.18355v2\" rel=\"noopener noreferrer\" target=\"_blank\">2610.18355v2</a> · Code: <a href=\"https://github.com/amap-cvlab/ABot-ER\" rel=\"noopener noreferrer\" target=\"_blank\">amap-cvlab/ABot-ER</a></li>\n<li><strong>Harness Robotic OS</strong> (2026). Upgrade the quadruped inspection from “navigation stack” to “embodied agent runtime”. arXiv: <a href=\"https://arxiv.org/abs/2609.11225\" rel=\"noopener noreferrer\" target=\"_blank\">2609.11225</a></li>\n<li><strong>NavHarness</strong> (2026). NavHarness: Towards Lifelong Embodied Navigation. arXiv: <a href=\"https://arxiv.org/abs/2609.34276\" rel=\"noopener noreferrer\" target=\"_blank\">2609.34276</a> · Code: <a href=\"https://github.com/billzhao1030/NavHarness\" rel=\"noopener noreferrer\" target=\"_blank\">billzhao1030/NavHarness</a> · Project Page: <a href=\"https://billzhao1030.github.io\" rel=\"noopener noreferrer\" target=\"_blank\">billzhao1030.github.io</a></li>\n<li><strong>SuperNav</strong> (2026). SuperNav: An Agentic Navigation System for Any Task in Any Scene. arXiv: <a href=\"https://arxiv.org/abs/2610.12126\" rel=\"noopener noreferrer\" target=\"_blank\">2610.12126</a> · Full analysis: <a data-local-language=\"en\" href=\"#/post/vln-papers-extended?section=supernav\">Extended VLN collection</a></li>\n<li><strong>VISTA</strong> (2026). VISTA: A Visual Harness for Reasoning in an Interactive World. arXiv: <a href=\"https://arxiv.org/abs/2610.02200\" rel=\"noopener noreferrer\" target=\"_blank\">2610.02200</a> · Code: <a href=\"https://github.com/joshhhhhan/VISTA\" rel=\"noopener noreferrer\" target=\"_blank\">joshhhhhan/VISTA</a></li>\n<li><strong>RACE</strong> (2026). When Should Agents Think? Adaptive Reasoning via Cross-Turn Estimation. arXiv: <a href=\"https://arxiv.org/abs/2610.12061\" rel=\"noopener noreferrer\" target=\"_blank\">2610.12061</a> · Code: <a href=\"https://github.com/HututuAI/RACE\" rel=\"noopener noreferrer\" target=\"_blank\">HututuAI/RACE</a></li>\n<li><strong>Agentic Robots</strong> (2026). Towards Agentic Robots: Model, Data, Environment, and Harness. arXiv: <a href=\"https://arxiv.org/abs/2610.20442\" rel=\"noopener noreferrer\" target=\"_blank\">2610.20442</a> · Code: <a href=\"https://github.com/chonghanqin/Awesome-Agentic-Robots\" rel=\"noopener noreferrer\" target=\"_blank\">chonghanqin/Awesome-Agentic-Robots</a></li>\n<li>\n<p><strong>Harness²</strong> (2026). Harness²: Recursive Agent Harnessing for an Open World. arXiv: <a href=\"https://arxiv.org/abs/2610.14224\" rel=\"noopener noreferrer\" target=\"_blank\">2610.14224</a> · Code: <a href=\"https://github.com/google-research/harness2\" rel=\"noopener noreferrer\" target=\"_blank\">google-research/harness2</a> · Project Page: <a href=\"https://harness2.github.io/\" rel=\"noopener noreferrer\" target=\"_blank\">harness2.github.io</a></p>\n</li>\n<li><strong>GPT-6-Astra-JRT</strong> (2026). Joint Research Team. Has GPT-6-Astra Achieved Embodied Intelligence? arXiv: <a href=\"https://arxiv.org/abs/2610.22471\" rel=\"noopener noreferrer\" target=\"_blank\">2610.22471</a> · Project Page: <a href=\"https://sensenova.ai/has-gpt-6-astra-achieved-embodied-intelligence\" rel=\"noopener noreferrer\" target=\"_blank\">sensenova.ai</a></li>\n<li><strong>Evo²</strong> (2026). Evo²: Evolving the Evolver through Weight-Harness Co-Evolution. arXiv: <a href=\"https://arxiv.org/abs/2610.13025\" rel=\"noopener noreferrer\" target=\"_blank\">2610.13025</a></li>\n<li><strong>Dream-RSI</strong> (2026). Dream-RSI: Recursive Self-Improvement through Evolving Worlds. arXiv: <a href=\"https://arxiv.org/abs/2609.14858\" rel=\"noopener noreferrer\" target=\"_blank\">2609.14858v2</a> · Code: <a href=\"https://github.com/zhengkid/Dream-RSI\" rel=\"noopener noreferrer\" target=\"_blank\">zhengkid/Dream-RSI</a> · Project Page: <a href=\"https://dream-rsi.com/\" rel=\"noopener noreferrer\" target=\"_blank\">dream-rsi.com</a></li>\n</ol>\n\n", "styles": ["\n  /* 回到顶部按钮样式 */\n  #backToTop {\n    position: fixed;\n    bottom: 2rem;\n    right: 2rem;\n    width: 3rem;\n    height: 3rem;\n    background: var(--theme-color, #a4a8b1);\n    color: white;\n    border: none;\n    border-radius: 50%;\n    cursor: pointer;\n    opacity: 0;\n    transform: translateY(100%);\n    transition: all 0.3s ease;\n    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 999; /* 确保在其它元素之上 */\n  }\n  \n  #backToTop.show {\n    opacity: 1;\n    transform: translateY(0);\n  }\n  \n  @media (hover: hover) {\n    #backToTop:hover {\n      background: var(--theme-hover-color, #a4a8b1);\n      transform: translateY(0) scale(1.1);\n    }\n  }\n  "], "articleClasses": ["posts", "paper-figures"], "removedImages": 88};
window.BLOG_ARTICLE_FEATURES = window.BLOG_ARTICLE_FEATURES || {};
window.BLOG_ARTICLE_FEATURES["en/embodied-agent-papers"] = function(entry) {
function localId(id) { return entry.querySelector("#"+id); }

  var TAG_MAP = [
    { m: 'Harness Robotic OS', t: ['AgentOS', 'Harness', 'Closed-loop systems', 'Spatial memory', 'self-evolution', 'RSI', 'Real-robot deployment'] },
    { m: 'HoloAgent-0', t: ['AgentOS', 'Closed-loop systems', 'Typed actions', 'Spatial memory', 'Scene graph', '3D semantics', 'Real-robot deployment', 'Multi-machine collaboration'] },
    { m: 'Pigey',       t: ['Closed-loop systems', 'Embodied manipulation', 'Fast and slow dual system', 'Real-robot deployment', 'TAMP', 'VLA', 'double check', 'Zero fine-tuning'] },
    { m: 'Thea',        t: ['Harness', 'Closed-loop systems', 'Scene graph', 'Exit-code evaluation', 'Real-robot deployment', 'Cross-embodiment', 'Active exploration', 'Embodied manipulation'] },
    { m: 'Zetta',       t: ['Harness', 'Closed-loop systems', 'self-evolution', 'RSI', 'High-frequency judge', 'Exception recovery', 'Embodied manipulation', 'High-throughput infrastructure'] },
    { m: 'Show-Harness', t: ['Harness', 'Closed-loop systems', 'Embodied manipulation', 'Typed actions', 'Real-robot deployment', 'Cross-embodiment', 'VLA', 'Zero fine-tuning'] },
    { m: 'SPACE',       t: ['action chunking', 'reinforcement learning', 'Skill induction', 'Long-horizon tasks'] },
    { m: 'ABot-AgentOS', t: ['AgentOS', 'Harness', 'Closed-loop systems', 'Topological graph', 'Spatial memory', 'self-evolution', 'RSI', 'Real-robot deployment'] },
    { m: 'ABot-ER', t: ['Embodied reasoning', 'Data governance', 'self-evolution', 'RSI', 'Long-horizon tasks', 'Real-robot deployment'] },
    { m: 'NavHarness', t: ['Harness', 'Closed-loop systems', 'Spatial memory', 'Exception recovery', 'Embodied navigation', 'Zero fine-tuning', 'Long-horizon tasks'] },
    { m: 'SuperNav', t: ['Harness', 'Closed-loop systems', 'Active exploration', 'Exception recovery', 'Embodied navigation', 'Real-robot deployment'] },
    { m: 'VISTA', t: ['Harness', 'Visual memory', 'Active exploration', 'Zero fine-tuning', 'Long-horizon tasks'] },
    { m: 'RACE', t: ['reinforcement learning', 'Long-horizon tasks', 'Reasoning budget'] },
    { m: 'Agentic Robots', t: ['Survey', 'Harness', 'Closed-loop systems', 'VLA', 'Exception recovery', 'self-evolution', 'RSI', 'Cross-embodiment'] },
    { m: 'Harness²', t: ['Harness', 'Closed-loop systems', 'self-evolution', 'RSI', 'Zero fine-tuning', 'Long-horizon tasks'] },
    { m: 'GPT-6-Astra-JRT', t: ['Harness', 'Closed-loop systems', 'Fast and slow dual system', 'Real-robot deployment', 'Cross-embodiment', 'Zero fine-tuning', 'Exception recovery', 'Reasoning budget'] },
    { m: 'Evo²', t: ['Harness', 'Closed-loop systems', 'self-evolution', 'RSI', 'reinforcement learning', 'Long-horizon tasks', 'Data governance'] },
    { m: 'Dream-RSI', t: ['Harness', 'self-evolution', 'RSI', 'Active exploration', 'Long-horizon tasks', 'Data governance'] },
  ];

  var ALL_TAGS = ['Survey', 'Closed-loop systems', 'Harness', 'AgentOS', 'Embodied manipulation', 'Scene graph', 'Topological graph', 'Real-robot deployment', 'Fast and slow dual system', 'Typed actions', 'Spatial memory', '3D semantics', 'Multi-machine collaboration', 'TAMP', 'VLA', 'double check', 'Exit-code evaluation', 'self-evolution', 'RSI', 'High-frequency judge', 'Cross-embodiment', 'Active exploration', 'Zero fine-tuning', 'action chunking', 'reinforcement learning', 'Skill induction', 'Long-horizon tasks', 'Exception recovery', 'Embodied navigation', 'Visual memory', 'Reasoning budget', 'Embodied reasoning', 'Data governance'];

  var activeTags = [];
  var resultsPanel = null;

  function getTagsForTitle(text) {
    for (var i = 0; i < TAG_MAP.length; i++) {
      if (text.indexOf(TAG_MAP[i].m) !== -1) return TAG_MAP[i].t;
    }
    return null;
  }

  function toggleTag(tag) {
    var idx = activeTags.indexOf(tag);
    if (idx === -1) activeTags.push(tag);
    else activeTags.splice(idx, 1);
    updateFilter();
  }

  function sectionMatches(sectionTags) {
    return activeTags.every(function (t) {
      return sectionTags.indexOf(t) !== -1;
    });
  }

  function updateFilter() {
    var sections = entry.querySelectorAll('.paper-section');
    var bar = localId('paper-filter-bar');
    if (!bar) return;
    var matchedSections = [];

    bar.querySelectorAll('.filter-btn').forEach(function (btn) {
      var t = btn.getAttribute('data-tag');
      if (t === '__all__') {
        btn.classList.toggle('active', activeTags.length === 0);
        btn.setAttribute('aria-pressed', activeTags.length === 0 ? 'true' : 'false');
      } else {
        var active = activeTags.indexOf(t) !== -1;
        btn.classList.toggle('active', active);
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
      }
    });

    sections.forEach(function (s) {
      var sectionTags = s.getAttribute('data-tags').split(',');
      var visible = activeTags.length === 0 || sectionMatches(sectionTags);
      s.classList.toggle('hidden', !visible);
      if (visible) matchedSections.push(s);
    });

    var totalAll = sections.length;
    var matchedAll = matchedSections.length;
    var countEl = bar.querySelector('.filter-count');
    if (countEl) {
      countEl.textContent = activeTags.length === 0
        ? totalAll + ' papers'
        : matchedAll + ' / ' + totalAll + ' papers';
    }

    updateResultsPanel(matchedSections);
  }

  function updateResultsPanel(matchedSections) {
    if (!resultsPanel) return;
    if (activeTags.length === 0) {
      resultsPanel.style.display = 'none';
      return;
    }
    resultsPanel.style.display = 'block';
    var list = resultsPanel.querySelector('.results-list');
    list.innerHTML = '';

    matchedSections.forEach(function (s) {
      var h2 = s.querySelector('h2');
      if (!h2) return;
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.href = '#' + h2.id; a.dataset.jump = h2.id;
      a.textContent = h2.textContent.trim().replace(/#$/, '').trim();
      li.appendChild(a);
      list.appendChild(li);
    });
  }

  function buildFilterBar() {
    var bar = localId('paper-filter-bar');
    if (!bar) return;

    var label = document.createElement('span');
    label.className = 'filter-label';
    label.textContent = 'Filter:';
    bar.appendChild(label);

    var allBtn = document.createElement('button');
    allBtn.className = 'filter-btn active';
    allBtn.type = 'button';
    allBtn.setAttribute('aria-label', 'Clear paper filter');
    allBtn.setAttribute('aria-pressed', 'true');
    allBtn.setAttribute('data-tag', '__all__');
    allBtn.textContent = 'All';
    allBtn.addEventListener('click', function () {
      activeTags = [];
      updateFilter();
    });
    bar.appendChild(allBtn);

    ALL_TAGS.forEach(function (tag) {
      var btn = document.createElement('button');
      btn.className = 'filter-btn';
      btn.type = 'button';
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('data-tag', tag);
      btn.textContent = tag;
      btn.addEventListener('click', function () { toggleTag(tag); });
      bar.appendChild(btn);
    });

    var count = document.createElement('span');
    count.className = 'filter-count';
    count.setAttribute('aria-live', 'polite');
    bar.appendChild(count);

    resultsPanel = document.createElement('div');
    resultsPanel.className = 'paper-filter-results';
    resultsPanel.setAttribute('aria-live', 'polite');
    resultsPanel.style.display = 'none';
    var rLabel = document.createElement('span');
    rLabel.className = 'results-label';
    rLabel.textContent = 'Matching papers:';
    var rList = document.createElement('ul');
    rList.className = 'results-list';
    resultsPanel.appendChild(rLabel);
    resultsPanel.appendChild(rList);
    bar.insertAdjacentElement('afterend', resultsPanel);
  }

  function wrapSections() {

    if (!entry) return;

    var children = Array.from(entry.childNodes);
    var newChildren = [];
    var wrapper = null;

    children.forEach(function (node) {
      var isEl = node.nodeType === 1;
      var tagName = isEl ? node.tagName : null;

      if (tagName === 'H1') {
        if (wrapper) { newChildren.push(wrapper); wrapper = null; }
        newChildren.push(node);
      } else if (tagName === 'H2') {
        if (wrapper) { newChildren.push(wrapper); wrapper = null; }
        var paperTags = getTagsForTitle(node.textContent);
        if (paperTags) {
          wrapper = document.createElement('div');
          wrapper.className = 'paper-section';
          wrapper.setAttribute('data-tags', paperTags.join(','));
          wrapper.appendChild(node);
          var row = document.createElement('div');
          row.className = 'paper-tags-row';
          paperTags.forEach(function (t) {
            var span = document.createElement('span');
            span.className = 'paper-tag';
            span.setAttribute('role', 'button');
            span.setAttribute('tabindex', '0');
            span.textContent = t;
            span.addEventListener('click', function () { toggleTag(t); });
            span.addEventListener('keydown', function (event) {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                toggleTag(t);
              }
            });
            row.appendChild(span);
          });
          wrapper.appendChild(row);
        } else {
          newChildren.push(node);
        }
      } else {
        if (wrapper) wrapper.appendChild(node);
        else newChildren.push(node);
      }
    });

    if (wrapper) newChildren.push(wrapper);

    while (entry.firstChild) entry.removeChild(entry.firstChild);
    newChildren.forEach(function (n) { entry.appendChild(n); });
  }

  wrapSections(); buildFilterBar(); updateFilter();

};
